  @override
  void initState() {
    super.initState();
    final debugCalendarNow = widget.debugCalendarNow;
    if (debugCalendarNow != null) {
      _calendarCycleAnchor = debugCalendarNow;
    }
    final debugAssetData = widget.debugInitialAssetData;
    if (debugAssetData != null) {
      _assetData = <String, Map<String, double>>{
        for (final entry in debugAssetData.entries)
          entry.key: Map<String, double>.from(entry.value),
      };
    }
    final debugRecurring = widget.debugInitialRecurringFixedCosts;
    if (debugRecurring != null) {
      _recurringFixedCosts = List<AssetRecurringFixedCost>.from(debugRecurring);
    }
    final debugFlows = widget.debugInitialRecentFlows;
    if (debugFlows != null) {
      _recentFlows = <Map<String, dynamic>>[
        for (final flow in debugFlows) Map<String, dynamic>.from(flow),
      ];
    }
    final debugSalaryIncomes = widget.debugInitialPayslipSalaryIncomes;
    if (debugSalaryIncomes != null) {
      _payslipSalaryIncomes = <Map<String, dynamic>>[
        for (final row in debugSalaryIncomes) Map<String, dynamic>.from(row),
      ];
    }
    final debugPayslipRows = widget.debugInitialPayslipRows;
    if (debugPayslipRows != null) {
      _payslipRows = <Map<String, dynamic>>[
        for (final row in debugPayslipRows) Map<String, dynamic>.from(row),
      ];
    }
    final debugDisposableBalanceResult =
        widget.debugInitialDisposableBalanceResult;
    if (debugDisposableBalanceResult != null) {
      _serverDisposableBalanceResult = Map<String, dynamic>.from(
        debugDisposableBalanceResult,
      );
    }
    _assetLiabilityRepository = widget.assetLiabilityRepository ??
        AssetLiabilityRepositoryFactory.createDefault(
          supabaseClient: _supabase,
        );
    _investmentAssetRepository = widget.investmentAssetRepository ??
        SupabaseInvestmentAssetRepository(client: _supabase);
    unawaited(_loadMinimumSafetyBalance());
    // 起動時の asset_pref_mirror 個別読み取りを 1 回のバッチ取得へ集約する
    // (端末跨ぎ同期の多数 REST が ERR_INSUFFICIENT_RESOURCES を誘発するのを緩和)。
    // 起動バーストが収束したらキャッシュを失効させ、以降は最新を個別取得する。
    _bootPrefMirrorFuture = _fetchAllPrefMirror();
    _bootPrefMirrorExpiryTimer = Timer(const Duration(seconds: 20), () {
      _bootPrefMirrorFuture = null;
    });
    _loadDataFromSupabase();
    unawaited(_loadAssetLiabilityBootState());
    _loadWatchlistEntries();
    _loadAssetManagementUserProfile();
    _loadPayslipFinanceData();
    _fetchRecentFlows();
    _fetchSubscriptions();
    _fetchMustTasks();
    unawaited(_loadDailyTodos());
    _loadDisplayMode();
    unawaited(_loadAssetChatPrivacySettings());
    _loadMainAccount();
    unawaited(_loadHouseholdTrackerPublishing());
    unawaited(_loadSalaryAmount());
    unawaited(_loadRevolvingConfigs());
    unawaited(_loadCardUsagePolicies());
    unawaited(_loadCategoryBudgets());
    unawaited(_loadRecurringFixedCosts());
    // ドル建てサブスクの円換算に使う USD/JPY を取得し、最新レートで再計算する。
    unawaited(_loadUsdJpyRate());
    unawaited(_loadSubscriptionAudit());
    unawaited(_loadRecurringIgnored());
    unawaited(_loadRecurringIncomeIgnored());
    unawaited(_loadDuplicateIgnored());
    unawaited(_loadDrinkChallenge());
    unawaited(_loadAssetAlertDismissedIds());
    _loadExpectedInflows();
    // ローカル→サーバの順で GC 設定を反映してから削除トゥームストーンを取込む。
    unawaited(_initTombstoneGcAndPull());
    // 他端末で削除されたセクション上書き / 支払日上書きを取り込む (#part292/294)。
    unawaited(_pullDeletedSectionIds());
    unawaited(_pullDebtOverrideDeleted());
    // リボ設定 / ウォッチリストの削除トゥームストーンは restore と同一フューチャ内で
    // pull→restore の順に直列化する (_loadRevolvingConfigs / _loadWatchlistEntries
    // 内 / review #1 restore↔pull レース対策)。
    // 期限切れ・上限超過のトゥームストーンを自動掃除 (#part296 肥大化抑制)。
    unawaited(_pruneTombstonesOnBoot());
    _deadlineTimer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (!mounted) return;
      final previousNow = _now;
      final nextNow = DateTime.now();
      final previousMonthKey = _assetLiabilityStateMonthKey(previousNow);
      final nextMonthKey = _assetLiabilityStateMonthKey(nextNow);
      // _now はこのページでは日付(M/d)までしか表示しない。毎秒 setState すると巨大な
      // ページ全体の再ビルド + ワークブック再計算が常時走り続け、操作時のカクつきの
      // 主因になる。そこでフィールドは毎秒更新して各種判定(月またぎ/給料検知)は最新
      // 時刻で行いつつ、再描画は「表示が実際に変わる=日付が変わった時」だけに絞る。
      final dayChanged = previousNow.year != nextNow.year ||
          previousNow.month != nextNow.month ||
          previousNow.day != nextNow.day;
      _now = nextNow;
      if (dayChanged) {
        setState(() {});
      }
      if (nextMonthKey != previousMonthKey &&
          nextMonthKey != _loadedAssetLiabilityMonthKey) {
        unawaited(_loadAssetLiabilityMonthlyState());
      }
      // リセット保留中(新サイクルだが未検知)なら給料振込を再評価する。
      // 通常時は _salaryResetPending=false で即 return するため軽量。
      _maybeDetectSalaryDeposit();
    });
    _fetchTodayClosing();
    _loadSourceOptionsFromDb();
    _annualRateEvidencePasteRegistration = registerNoteImagePasteListener(
      isEnabled: () =>
          mounted &&
          _annualRateEvidencePasteTargetRow != null &&
          !_verifyingAnnualRateEvidenceAccountIds.contains(
            _annualRateEvidencePasteTargetRow!.id,
          ),
      onImagePasted: _handleAnnualRateEvidencePasted,
    );
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _scrollToInitialFocus();
    });
  }

  @override
  void dispose() {
    _controllers.forEach((_, controller) => controller.dispose());
    _monthlyPaymentControllers.forEach((_, controller) => controller.dispose());
    _actualPaymentControllers.forEach((_, controller) => controller.dispose());
    _paymentDifferenceReasonControllers.forEach(
      (_, controller) => controller.dispose(),
    );
    _annualRateControllers.forEach((_, controller) => controller.dispose());
    _cardStatementImportController.dispose();
    _assetCsvRestoreController.dispose();
    _repaymentSimulationExtraPaymentController.dispose();
    _minimumSafetyBalanceController.dispose();
    _flowMemoController.dispose();
    _flowAmountController.dispose();
    _deadlineTimer?.cancel();
    _bootPrefMirrorExpiryTimer?.cancel();
    _debtCardHighlightTimer?.cancel();
    _cardUsagePolicyMemoSaveTimer?.cancel();
    _assetManagementAiSummaryDebounce?.cancel();
    _existingDeveloperIssueLookupDebounce?.cancel();
    _annualRateEvidencePasteRegistration?.dispose();
    _scrollController.dispose();
    super.dispose();
  }

  Future<void> _loadAssetManagementUserProfile() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null || _isLoadingAssetManagementUserProfile) {
      return;
    }
    setState(() {
      _isLoadingAssetManagementUserProfile = true;
    });
    try {
      final profile = await _profileService.getProfile(userId);
      if (!mounted) {
        return;
      }
      setState(() {
        _assetManagementUserProfile = profile;
        _isLoadingAssetManagementUserProfile = false;
        _assetManagementAiSummaryRequestKey = null;
        _assetManagementAiSummaryResult = null;
        _assetManagementAiSummaryResultKey = null;
      });
    } catch (_) {
      if (!mounted) {
        return;
      }
      setState(() {
        _isLoadingAssetManagementUserProfile = false;
      });
    }
  }

  bool _assetManagementProfileBasicsMissing(UserProfile? profile) {
    if (profile == null) {
      return true;
    }
    final occupation = profile.occupation?.trim() ?? '';
    return occupation.isEmpty || profile.annualIncome == null;
  }

  Future<void> _openProfileSettingsForAssetManagement() async {
    await Navigator.of(context).push(
      MaterialPageRoute<void>(
        settings: const RouteSettings(name: '/profile-settings'),
        builder: (_) => const ProfileSettingsPage(),
      ),
    );
    if (!mounted) {
      return;
    }
    await _loadAssetManagementUserProfile();
  }

  /// AIコメントが指摘するカード明細の未取込・差分に対し、取り込み・照合
  /// パネルへ誘導するリンクの文言。確認が必要なカード名を織り込む。
  String _cardStatementReconciliationLinkLabel(
    AssetLiabilityWorkbook workbook,
  ) {
    final groups = workbook.cardStatementReconciliation.needsReviewGroups;
    if (groups.length == 1) {
      return '${groups.first.billingAccountName}の明細を取り込んで照合する';
    }
    return 'カード明細を取り込んで照合する（${groups.length}件）';
  }

