      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('うどん縛りの前提を更新しました')));
    } finally {
      priceController.dispose();
      baselineController.dispose();
    }
  }

  Future<void> _showDebtPlanDialog() async {
    final monthlyBudgetController = TextEditingController();
    final extraBudgetController = TextEditingController(text: '0');
    final targetMonthsController = TextEditingController(text: '12');
    final memoController = TextEditingController();
    String strategyKey = DebtRepaymentStrategy.snowball.name;

    try {
      final ok = await showDialog<bool>(
        context: context,
        builder: (context) => StatefulBuilder(
          builder: (context, setDialogState) => AlertDialog(
            title: const Text('借金返済プラン作成'),
            content: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  DropdownButtonFormField<String>(
                    initialValue: strategyKey,
                    decoration: const InputDecoration(
                      labelText: '返済方針',
                      border: OutlineInputBorder(),
                      isDense: true,
                    ),
                    items: const [
                      DropdownMenuItem(
                        value: 'snowball',
                        child: Text('少額優先（スノーボール）'),
                      ),
                      DropdownMenuItem(
                        value: 'avalanche',
                        child: Text('高金利優先（アバランチ）'),
                      ),
                      DropdownMenuItem(value: 'dueDate', child: Text('支払日順')),
                      DropdownMenuItem(
                        value: 'hybrid',
                        child: Text('ハイブリッド（高金利×少額）'),
                      ),
                    ],
                    onChanged: (v) {
                      if (v == null) return;
                      setDialogState(() => strategyKey = v);
                    },
                  ),
                  const SizedBox(height: 8),
                  TextField(
                    controller: monthlyBudgetController,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(
                      labelText: '毎月の返済予算（円）',
                      border: OutlineInputBorder(),
                      isDense: true,
                    ),
                  ),
                  const SizedBox(height: 8),
                  TextField(
                    controller: extraBudgetController,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(
                      labelText: '臨時返済予算（円）',
                      border: OutlineInputBorder(),
                      isDense: true,
                    ),
                  ),
                  const SizedBox(height: 8),
                  TextField(
                    controller: targetMonthsController,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(
                      labelText: '目標完済期間（月）',
                      border: OutlineInputBorder(),
                      isDense: true,
                    ),
                  ),
                  const SizedBox(height: 8),
                  TextField(
                    controller: memoController,
                    minLines: 2,
                    maxLines: 4,
                    decoration: const InputDecoration(
                      labelText: '補足（任意）',
                      border: OutlineInputBorder(),
                      isDense: true,
                    ),
                  ),
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(context, false),
                child: const Text('キャンセル'),
              ),
              ElevatedButton(
                onPressed: () => Navigator.pop(context, true),
                child: const Text('作成'),
              ),
            ],
          ),
        ),
      );

      if (ok != true) return;

      final monthlyBudget = int.tryParse(
            monthlyBudgetController.text.replaceAll(',', '').trim(),
          ) ??
          0;
      final extraBudget =
          int.tryParse(extraBudgetController.text.replaceAll(',', '').trim()) ??
              0;
      final targetMonths = int.tryParse(
            targetMonthsController.text.replaceAll(',', '').trim(),
          ) ??
          12;
      final userMemo = memoController.text.trim();

      if (monthlyBudget <= 0 || targetMonths <= 0) {
        if (!mounted) return;
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(const SnackBar(content: Text('返済予算と目標期間を正しく入力してください')));
        return;
      }

      await _generateDebtRepaymentPlan(
        strategyKey: strategyKey,
        monthlyBudget: monthlyBudget,
        extraBudget: extraBudget,
        targetMonths: targetMonths,
        userMemo: userMemo,
      );
    } finally {
      monthlyBudgetController.dispose();
      extraBudgetController.dispose();
      targetMonthsController.dispose();
      memoController.dispose();
    }
  }

  DebtRepaymentStrategy _strategyFromKey(String strategyKey) {
    for (final strategy in DebtRepaymentStrategy.values) {
      if (strategy.name == strategyKey) return strategy;
    }
    return DebtRepaymentStrategy.snowball;
  }

  Future<void> _generateDebtRepaymentPlan({
    required String strategyKey,
    required int monthlyBudget,
    required int extraBudget,
    required int targetMonths,
    required String userMemo,
  }) async {
    final snapshot = _latestSnapshotForPlanning();
    final workbook = _assetLiabilityPlanner.buildWorkbook(
      latestSnapshot: snapshot,
      baseDate: _now,
      monthlyPaymentOverrides: _monthlyPaymentOverrides,
      actualPaymentAmounts: _actualPaymentAmounts,
      paymentDifferenceReasons: _paymentDifferenceReasons,
      annualRateOverrides: _annualRateOverrides,
      paymentDayOverrides: _debtPaymentDayOverrides,
      paidAccountNames: _monthlyPaidAccountNames,
      paymentSourceAccountIds: _paymentSourceAccountIds,
      defaultPaymentSourceAccountIds: _defaultPaymentSourceAccountIds,
      defaultCardBillingAccountIds: _defaultCardBillingAccountIds,
      cardBillingAccountIds: _cardBillingAccountIds,
      revolvingConfigs: _revolvingConfigs,
      cardUsagePolicies: _cardUsagePolicies,
      incomePlans: _monthlyIncomePlans,
      cardStatementLines: _cardStatementLines,
      transferTasks: _transferTasks,
      salaryDay: _salaryDay,
    );
    final liabilities = workbook.debtMasterRows;
    if (liabilities.isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('負債データがありません。まず負債を記録してください。')),
      );
      return;
    }

    final planNow = DateTime.now();
    final currentMonthFlows = _flowsForCycle(planNow);
    int monthlyIncome = 0;
    int monthlyExpense = 0;
    for (final f in currentMonthFlows) {
      final amt = (f['amount'] as num?)?.toInt() ?? 0;
      if (f['action_type'] == 'conquer') monthlyIncome += amt;
      if (f['action_type'] == 'expense') monthlyExpense += amt;
    }
    // 給与明細でのみ管理している給料もサイクル収入へ合算する。
    monthlyIncome += _cycleSalaryIncomeTotal(planNow, currentMonthFlows);

    final currentFixedCost = _subscriptions.fold<int>(
      0,
      (sum, s) => sum + ((s['price'] as num?)?.toInt() ?? 0),
    );
    final netWorth = snapshot.values.fold<double>(0, (sum, v) => sum + v);
    final strategy = _strategyFromKey(strategyKey);
    final inputDebts = liabilities
        .map((row) {
          final minimumPayment = max(
            row.minimumPaymentEstimate,
            row.scheduledPaymentAmount,
          );
          return _debtRepaymentPlanner.normalizeDebt(
            name: row.name,
            balance: row.balance.abs(),
            annualRate: row.annualRate,
            minimumPaymentRate: 0,
            minimumPaymentFloor: minimumPayment,
            paymentDay: row.paymentDay,
          );
        })
        .where((d) => d.name.isNotEmpty && d.balance > 0)
        .toList();

    if (inputDebts.isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('返済対象の負債データを作成できませんでした')));
      return;
    }

    final input = DebtRepaymentPlanInput(
      debts: inputDebts,
      strategy: strategy,
      monthlyBudget: monthlyBudget,
      extraBudget: extraBudget,
      targetMonths: targetMonths,
      monthlyIncome: monthlyIncome,
      monthlyExpense: monthlyExpense,
      fixedCost: currentFixedCost,
      netWorth: netWorth,
      note: userMemo,
      baseMonth: _monthStart(DateTime.now()),
    );

    setState(() => _isGeneratingDebtPlan = true);
    try {
      final result = _debtRepaymentPlanner.generatePlan(input: input);
      final executionPlan = _debtRepaymentPlanner.buildExecutionPlan(
        input: input,
        result: result,
      );

      if (!mounted) return;
      setState(() {
        _debtPlanMarkdown = result.markdown;
        _debtExecutionPlan = executionPlan;
        _selectedDebtExecutionTaskIds =
            executionPlan.tasks.map((task) => task.id).toSet();
        _debtPlannerMode = AssetDebtPlannerMode.ask;
        _debtPlanGeneratedAt = DateTime.now();
      });
      final warningCount = result.warnings.length;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            warningCount == 0
                ? '返済計画を作成しました'
                : '返済計画を作成しました（注意点 $warningCount 件）',
          ),
        ),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('返済計画の作成に失敗しました: $e')));
    } finally {
      if (mounted) {
        setState(() => _isGeneratingDebtPlan = false);
      }
    }
  }

  List<DebtExecutionTask> get _selectedDebtExecutionTasks {
    final plan = _debtExecutionPlan;
    if (plan == null) return const <DebtExecutionTask>[];
    return plan.tasks
        .where((task) => _selectedDebtExecutionTaskIds.contains(task.id))
        .toList(growable: false);
  }

  void _toggleDebtExecutionTask(String taskId, bool selected) {
    setState(() {
      if (selected) {
        _selectedDebtExecutionTaskIds.add(taskId);
      } else {
        _selectedDebtExecutionTaskIds.remove(taskId);
      }
    });
  }

  void _selectAllDebtExecutionTasks() {
    final plan = _debtExecutionPlan;
    if (plan == null) return;
    setState(() {
      _selectedDebtExecutionTaskIds = plan.tasks.map((task) => task.id).toSet();
    });
  }

  void _clearDebtExecutionTaskSelection() {
    setState(() {
      _selectedDebtExecutionTaskIds = <String>{};
    });
  }

  String _mustTaskSignatureFromMap(Map<String, dynamic> task) {
    final title = (task['title'] ?? '').toString().trim().toLowerCase();
    final deadline = DateTime.tryParse(
      task['deadline']?.toString() ?? '',
    )?.toLocal();
    final deadlineKey =
        deadline == null ? '' : DateFormat('yyyy-MM-dd').format(deadline);
    return '$title|$deadlineKey';
  }

  String _mustTaskSignatureFromExecutionTask(DebtExecutionTask task) {
    final deadlineKey = DateFormat('yyyy-MM-dd').format(task.dueDate);
    return '${task.title.trim().toLowerCase()}|$deadlineKey';
  }

  bool _isExecutionTaskAlreadyAdded(DebtExecutionTask task) {
    final signature = _mustTaskSignatureFromExecutionTask(task);
    return _mustTasks.any(
      (item) => _mustTaskSignatureFromMap(item) == signature,
    );
  }

  Future<void> _applyDebtExecutionTasksToMustTasks() async {
    final selectedTasks = _selectedDebtExecutionTasks;
    if (selectedTasks.isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('追加する Code タスクを選択してください')));
      return;
    }

    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('ログイン後に Code タスクを追加できます')));
      return;
    }

    final existingSignatures =
        _mustTasks.map(_mustTaskSignatureFromMap).toSet();
    final rows = <Map<String, dynamic>>[];
    final insertedIds = <String>[];
    var skippedCount = 0;

    for (final task in selectedTasks) {
      final signature = _mustTaskSignatureFromExecutionTask(task);
      if (existingSignatures.contains(signature)) {
        skippedCount++;
        continue;
      }
      existingSignatures.add(signature);
      rows.add({
        'user_id': userId,
        'title': task.title,
        'deadline': task.dueDate.toUtc().toIso8601String(),
        'is_completed': false,
      });
      insertedIds.add(task.id);
    }

    if (rows.isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('選択した Code タスクはすでに必須タスクへ追加済みです')),
      );
      return;
    }

    setState(() => _isApplyingDebtExecutionTasks = true);
    try {
      await _supabase.from('must_tasks').insert(rows);
      await _fetchMustTasks();
      await _fetchTodayClosing();

      if (!mounted) return;
      setState(() {
        _selectedDebtExecutionTaskIds.removeAll(insertedIds);
      });
      _scrollTo(_keyMust);
      final suffix = skippedCount > 0 ? '（重複 $skippedCount 件を除外）' : '';
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Code タスクを ${rows.length} 件追加しました$suffix')),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('Code タスクの追加に失敗しました: $e')));
    } finally {
      if (mounted) {
        setState(() => _isApplyingDebtExecutionTasks = false);
      }
    }
  }

  DateTime _deadlineToday() => DateTime(_now.year, _now.month, _now.day, 18, 0);

  String _remainingToDeadlineText() {
    final diff = _deadlineToday().difference(_now);
    if (diff.isNegative) return '⚠️ 締切(18:00)を過ぎています';
    final h = diff.inHours;
    final m = diff.inMinutes % 60;
    final s = diff.inSeconds % 60;
    return '締切まで ${h.toString().padLeft(2, '0')}:${m.toString().padLeft(2, '0')}:${s.toString().padLeft(2, '0')}';
  }

  double _progress() {
    int done = 0;
    if (_assetsDone) done++;
    if (_liabilitiesDone) done++;
    if (_fixedCostsDone) done++;
    if (_flowsDone) done++;
    if (_mustTasksDone) done++;
    return done / 5.0;
  }

  Future<void> _fetchTodayClosing() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) return;

    setState(() => _isLoadingClosing = true);
    final todayStr = _dateOnly(DateTime.now());

    try {
      final rows = await _supabase
          .from('cfo_daily_closings')
          .select()
          .eq('user_id', userId)
          .eq('date', todayStr)
          .limit(1);

      if (!mounted) return;

      if (rows.isNotEmpty) {
        final r = rows.first;
        setState(() {
          _assetsDone = r['assets_done'] == true;
          _liabilitiesDone = r['liabilities_done'] == true;
          _fixedCostsDone = r['fixed_costs_done'] == true;
          _flowsDone = r['flows_done'] == true;
          _mustTasksDone = r['must_tasks_done'] == true;
          _isLoadingClosing = false;
        });
      } else {
        setState(() {
          _assetsDone = false;
          _liabilitiesDone = false;
          _fixedCostsDone = false;
          _flowsDone = false;
          _mustTasksDone = false;
          _isLoadingClosing = false;
        });
      }
    } catch (e) {
      debugPrint('fetch closing error: $e');
      if (!mounted) return;
      setState(() => _isLoadingClosing = false);
    }
  }

  Future<void> _upsertTodayClosing() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) return;
    final todayStr = _dateOnly(DateTime.now());

    try {
      await _supabase.from('cfo_daily_closings').upsert({
        'user_id': userId,
        'date': todayStr,
        'assets_done': _assetsDone,
        'liabilities_done': _liabilitiesDone,
        'fixed_costs_done': _fixedCostsDone,
        'flows_done': _flowsDone,
        'must_tasks_done': _mustTasksDone,
        'updated_at': DateTime.now().toUtc().toIso8601String(),
      }, onConflict: 'user_id,date');
    } catch (e) {
      debugPrint('upsert closing error: $e');
    }
  }

  Future<void> _toggleClosing(String key, bool value) async {
    setState(() {
      switch (key) {
        case 'assets':
          _assetsDone = value;
          break;
        case 'liabilities':
          _liabilitiesDone = value;
          break;
        case 'fixed':
          _fixedCostsDone = value;
          break;
        case 'flows':
          _flowsDone = value;
          break;
        case 'must':
          _mustTasksDone = value;
          break;
      }
    });
    await _upsertTodayClosing();
  }

  void _scrollTo(GlobalKey key) {
    final ctx = key.currentContext;
    if (ctx == null) return;
    Scrollable.ensureVisible(
      ctx,
      duration: const Duration(milliseconds: 350),
      curve: Curves.easeOut,
    );
  }

  GlobalKey _sectionAnchorKey(AssetManagementSectionId id) {
    return _sectionAnchorKeys.putIfAbsent(id, () => GlobalKey());
  }

  /// セクション先頭に置く高さ0のアンカー。検索からここへ ensureVisible する。
  Widget _sectionAnchor(AssetManagementSectionId id) {
    return SizedBox(key: _sectionAnchorKey(id), height: 0);
  }

  /// カード名・項目名で検索して該当カードへ飛ぶボトムシートを開く。
  void _openSectionSearch() {
    final rootContext = context;
    showModalBottomSheet<void>(
      context: rootContext,
      isScrollControlled: true,
      showDragHandle: true,
      builder: (sheetContext) {
        var query = '';
        return StatefulBuilder(
          builder: (context, setSheetState) {
            final entries = _sectionSearchEntries(query);
            return Padding(
              padding: EdgeInsets.only(
                left: 16,
                right: 16,
                bottom: MediaQuery.of(context).viewInsets.bottom + 16,
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  TextField(
                    autofocus: true,
                    decoration: const InputDecoration(
                      prefixIcon: Icon(Icons.search),
                      hintText: 'カード名・項目名で検索 (例: 定期固定費, Pontaパス)',
                      border: OutlineInputBorder(),
                      isDense: true,
                    ),
                    onChanged: (value) => setSheetState(() => query = value),
                  ),
                  const SizedBox(height: 8),
                  Flexible(
                    child: entries.isEmpty
                        ? const Padding(
                            padding: EdgeInsets.symmetric(vertical: 24),
                            child: Text(
                              '一致するカード・項目がありません。'
                              '表示設定で隠しているカードは検索に出ません。',
                              style: TextStyle(color: Color(0xFF64748B)),
                            ),
                          )
                        : ListView.builder(
                            shrinkWrap: true,
                            itemCount: entries.length,
                            itemBuilder: (context, index) {
                              final entry = entries[index];
                              return ListTile(
                                dense: true,
                                leading: Icon(entry.icon, size: 20),
                                title: Text(entry.label),
                                subtitle: Text(entry.sublabel),
                                onTap: () {
                                  Navigator.of(sheetContext).pop();
                                  WidgetsBinding.instance.addPostFrameCallback(
                                    (_) => entry.onTap(),
                                  );
                                },
                              );
                            },
                          ),
                  ),
                ],
              ),
            );
          },
        );
      },
    );
  }

  /// 検索クエリに一致するジャンプ候補 (セクション + 登録項目) を返す。
  /// クエリ空なら表示中の全セクションを一覧にする (ジャンプメニュー兼用)。
  List<_AssetSectionSearchEntry> _sectionSearchEntries(String query) {
    final q = query.trim().toLowerCase();
    bool matches(String text) => q.isEmpty || text.toLowerCase().contains(q);

    final entries = <_AssetSectionSearchEntry>[];

    // 1) セクション (表示中のみ)。
    for (final id in AssetManagementSectionId.values) {
      if (!_isSectionShown(id)) continue;
      if (!matches(id.label)) continue;
      entries.add(
        _AssetSectionSearchEntry(
          label: id.label,
          sublabel: 'セクション',
          icon: Icons.view_agenda_outlined,
          onTap: () => _scrollTo(_sectionAnchorKey(id)),
        ),
      );
    }

    // 2) 定期固定費 / サブスク (Pontaパス 等)。該当カードのセクションへ飛ぶ。
    for (final cost in _recurringFixedCosts) {
      if (!matches(cost.name)) continue;
      final isSubscription =
          cost.category == AssetRecurringFixedCostCategory.subscription;
      final sectionId = isSubscription
          ? AssetManagementSectionId.subscriptionFixedCost
          : AssetManagementSectionId.recurringFixedCost;
      entries.add(
        _AssetSectionSearchEntry(
          label: cost.name,
          sublabel: isSubscription ? 'サブスク → カードへ移動' : '定期固定費 → カードへ移動',
          icon: Icons.subscriptions_outlined,
          onTap: () => _scrollTo(_sectionAnchorKey(sectionId)),
        ),
      );
    }

    // 3) 負債マスタの各行 (行単位でハイライト付きジャンプ)。
    final workbook = _buildCurrentAssetLiabilityWorkbook();
    if (workbook != null) {
      for (final row in workbook.debtMasterRows) {
        if (!matches(row.name)) continue;
        entries.add(
          _AssetSectionSearchEntry(
            label: row.name,
            sublabel: '負債マスタ → 行へ移動',
            icon: Icons.account_balance_outlined,
            onTap: () => _jumpToDebtMasterCard(row.id),
          ),
        );
      }
    }

    return entries;
  }

  Future<void> _autoCheckFromData() async {
    final todayStr = _dateOnly(DateTime.now());

    // NOTE: Closing checks intentionally use raw inputs recorded today.
    // Do not use display-complemented values here.
    final todayStock = _assetData[todayStr] ?? {};
    final allTypesFilledToday = _assetTypes.isNotEmpty &&
        _assetTypes.every((t) => todayStock.containsKey(t));

    final hasAnyPositive = todayStock.values.any((v) => v >= 0);
    final hasAnyNegative = todayStock.values.any((v) => v < 0);

    final subsOk = _fixedCostSummaryForMonth(_now).isNotEmpty;

    final checkNow = DateTime.now();
    final currentMonthFlows = _flowsForCycle(checkNow);
    final incomeCount =
        currentMonthFlows.where((r) => r['action_type'] == 'conquer').length;
    final expenseCount =
        currentMonthFlows.where((r) => r['action_type'] == 'expense').length;
    // 給与明細でのみ管理している給料も「収支の記録あり」とみなす。
    final salaryIncome = _cycleSalaryIncomeTotal(checkNow, currentMonthFlows);
    final flowsOk = (incomeCount + expenseCount) > 0 || salaryIncome > 0;

    final now = DateTime.now();
    final mustThisMonth = _mustTasks.where((t) {
      final d = DateTime.parse(t['deadline']).toLocal();
      return d.year == now.year && d.month == now.month;
    }).toList();
    final mustOk = mustThisMonth.isNotEmpty;

    setState(() {
      if (allTypesFilledToday && hasAnyPositive) _assetsDone = true;
      if (allTypesFilledToday && hasAnyNegative) _liabilitiesDone = true;
      if (subsOk) _fixedCostsDone = true;
      if (flowsOk) _flowsDone = true;
      if (mustOk) _mustTasksDone = true;
    });

    await _upsertTodayClosing();

    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('自動チェックを反映しました（不足があれば手動でONできます）')),
    );
  }

  Future<void> _copyDailySummary() async {
    if (_effectiveAssetDataByDate.isEmpty) {
      _updateChartData();
    }

    final now = DateTime.now();
    final todayStr = _dateOnly(now);

    String? snapshotDate;
    if (_assetData.containsKey(todayStr)) {
      snapshotDate = todayStr;
    } else if (_sortedDates.isNotEmpty) {
      snapshotDate = _sortedDates.last;
    }

    double totalAssets = 0;
    double totalLiabilities = 0;

    final Map<String, double> snap = snapshotDate != null
        ? Map<String, double>.from(
            _effectiveAssetDataByDate[snapshotDate] ??
                _assetData[snapshotDate] ??
                const <String, double>{},
          )
        : <String, double>{};
    snap.forEach((_, v) {
      if (v >= 0) totalAssets += v;
      if (v < 0) totalLiabilities += v;
    });

    final fixedCostSummary = _fixedCostSummaryForMonth(now);
    final totalFixed = fixedCostSummary.total;

    final currentMonthFlows = _flowsForCycle(now);
    int totalIncome = 0;
    int totalExpense = 0;
    int totalTransfer = 0;
    for (final f in currentMonthFlows) {
      final amt = (f['amount'] as num?)?.toInt() ?? 0;
      if (f['action_type'] == 'conquer') totalIncome += amt;
      if (f['action_type'] == 'expense') totalExpense += amt;
      if (f['action_type'] == 'transfer') totalTransfer += amt;
    }
    // 給与明細でのみ管理している給料もサイクル収入へ合算する。
    totalIncome += _cycleSalaryIncomeTotal(now, currentMonthFlows);

    final monthLabel = '${now.year}/${now.month.toString().padLeft(2, '0')}';
    final flowCycleLabel = _salaryCycleRangeLabel(now);
    final mustThisMonth = _mustTasks.where((t) {
      final d = DateTime.parse(t['deadline']).toLocal();
      return d.year == now.year && d.month == now.month;
    }).toList()
      ..sort(
        (a, b) => (a['deadline'] as String).compareTo(b['deadline'] as String),
      );

    final done = [
      _assetsDone,
      _liabilitiesDone,
      _fixedCostsDone,
      _flowsDone,
      _mustTasksDone,
    ].where((x) => x).length;

    final buf = StringBuffer();
    buf.writeln('## 本日18:00 CFO締め（$todayStr）');
    buf.writeln('- 進捗: **$done/5 完了**');
    buf.writeln('- ①資産: ${_assetsDone ? "✅" : "⬜️"}');
    buf.writeln('- ②負債: ${_liabilitiesDone ? "✅" : "⬜️"}');
    buf.writeln('- ③固定費: ${_fixedCostsDone ? "✅" : "⬜️"}');
    buf.writeln('- ④収支: ${_flowsDone ? "✅" : "⬜️"}');
    buf.writeln('- ⑤必須タスク: ${_mustTasksDone ? "✅" : "⬜️"}');
    buf.writeln('');

    buf.writeln('### ①② ストック（スナップショット: ${snapshotDate ?? "未記録"}）');
    buf.writeln('- 総資産: ¥${NumberFormat('#,###').format(totalAssets)}');
    buf.writeln('- 総負債: ¥${NumberFormat('#,###').format(totalLiabilities)}');
    buf.writeln(
      '- 純資産: ¥${NumberFormat('#,###').format(totalAssets + totalLiabilities)}',
    );
    if (snap.isNotEmpty) {
      buf.writeln('- 内訳:');
      final entries = snap.entries.toList()
        ..sort((a, b) => b.value.compareTo(a.value));
      for (final e in entries) {
        buf.writeln('  - ${e.key}: ¥${NumberFormat('#,###').format(e.value)}');
      }
    }
    buf.writeln('');

    buf.writeln('### ③ 固定費（$monthLabel）');
    buf.writeln('- 月額合計: ¥${NumberFormat('#,###').format(totalFixed)}');
    if (fixedCostSummary.isNotEmpty) {
      for (final entry in fixedCostSummary.entries) {
        buf.writeln(
          '  - ${entry.name}: ¥${NumberFormat('#,###').format(entry.amount)}',
        );
      }
    } else {
      buf.writeln('  - （未登録）');
    }
    buf.writeln('');

    buf.writeln('### ④ 収支（給料サイクル $flowCycleLabel）');
    buf.writeln('- 収入合計: ¥${NumberFormat('#,###').format(totalIncome)}');
    buf.writeln('- 支出合計: ¥${NumberFormat('#,###').format(totalExpense)}');
    buf.writeln('- 振替合計: ¥${NumberFormat('#,###').format(totalTransfer)}');
    buf.writeln(
      '- 差額: ¥${NumberFormat('#,###').format(totalIncome - totalExpense)}',
    );
    buf.writeln('');

    buf.writeln('### ⑤ 必須タスク（$monthLabel）');
    if (mustThisMonth.isEmpty) {
      buf.writeln('- （未登録）');
    } else {
      for (final t in mustThisMonth) {
        final d = DateTime.parse(t['deadline']).toLocal();
        final done = (t['is_completed'] as bool?) == true;
        buf.writeln(
          '- ${done ? "✅" : "⬜️"} ${t["title"]}（締切 ${DateFormat('MM/dd').format(d)}）',
        );
      }
    }

    await Clipboard.setData(ClipboardData(text: buf.toString()));
    if (!mounted) return;
    ScaffoldMessenger.of(
      context,
    ).showSnackBar(const SnackBar(content: Text('サマリーをコピーしました（投稿用）')));
  }

  // ==========================================
  // 1 & 2. 資産・負債の記録（ストック）
  // ==========================================

  Uri _bankSheetCsvUri(String gid) {
    return Uri.https(
      'docs.google.com',
      '/spreadsheets/d/$_bankSheetId/export',
      <String, String>{'format': 'csv', 'gid': gid},
    );
  }

  Future<List<List<String>>> _fetchBankSheetRows(String gid) async {
    final response = await http.get(_bankSheetCsvUri(gid));
    if (response.statusCode != 200) {
      throw Exception('Googleシート取得 HTTP ${response.statusCode}');
    }
    final csvData = utf8.decode(response.bodyBytes);
    return _parseCsvRows(csvData);
  }

  List<List<String>> _parseCsvRows(String csvData) {
    return const LineSplitter()
        .convert(csvData)
        .map(_parseCsvLine)
        .where((row) => row.any((cell) => cell.trim().isNotEmpty))
        .toList();
  }

  List<String> _parseCsvLine(String line) {
    final cells = <String>[];
    final buffer = StringBuffer();
    var inQuotes = false;

    for (var index = 0; index < line.length; index++) {
      final char = line[index];
      if (char == '"') {
        if (inQuotes && index + 1 < line.length && line[index + 1] == '"') {
          buffer.write('"');
          index++;
        } else {
          inQuotes = !inQuotes;
        }
      } else if (char == ',' && !inQuotes) {
        cells.add(buffer.toString());
        buffer.clear();
      } else {
        buffer.write(char);
      }
    }
    cells.add(buffer.toString());
    return cells;
  }

  double? _parseSheetAmount(String value) {
    final normalized = value
        .trim()
        .replaceAll(',', '')
        .replaceAll('¥', '')
        .replaceAll('￥', '')
        .replaceAll('円', '')
        .replaceAll('−', '-')
        .replaceAll(RegExp(r'\s+'), '');
    if (normalized.isEmpty) {
      return null;
    }
    return double.tryParse(normalized);
  }

  double? _extractSmbcBalance(List<List<String>> rows) {
    for (final row in rows) {
      if (row.length >= 6 &&
          RegExp(r'^\d{4}/\d{1,2}/\d{1,2}$').hasMatch(row[1].trim())) {
        final balance = _parseSheetAmount(row[5]);
        if (balance != null) {
          return balance;
        }
      }
    }
    return null;
  }

  double? _extractJibunBalance(List<List<String>> rows) {
    for (final row in rows) {
      if (row.length >= 5 &&
          RegExp(r'^\d{4}年\d{1,2}月\d{1,2}日$').hasMatch(row[0].trim())) {
        final balance = _parseSheetAmount(row[4]);
        if (balance != null) {
          return balance;
        }
      }
    }
    return null;
  }

  void _applyFetchedAssetBalance({
    required String assetName,
    required double balance,
  }) {
    if (!_assetTypes.contains(assetName)) {
      _assetTypes.add(assetName);
      _initControllers();
      _updateLastUpdatedDates();
      _sortAssetTypes();
    }
    _controllers[assetName]?.text = balance.toStringAsFixed(0);
  }

  void _showSheetFetchResult({
    required String assetName,
    required double balance,
    required Color color,
  }) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          '$assetNameの残高をシートから取得しました: ¥${NumberFormat('#,###').format(balance.round())}',
        ),
        backgroundColor: color,
      ),
    );
  }

  Future<void> _fetchSmbcDataFromSheet() async {
    setState(() => _isFetchingSmbc = true);
    try {
      final rows = await _fetchBankSheetRows(_smbcSheetGid);
      final balance = _extractSmbcBalance(rows);
      if (balance == null) {
        throw Exception('三井住友銀行の残高データが見つかりませんでした');
      }
      const smbcName = '三井住友銀行';
      setState(() {
        _applyFetchedAssetBalance(assetName: smbcName, balance: balance);
      });
      if (mounted) {
        _showSheetFetchResult(
          assetName: smbcName,
          balance: balance,
          color: const Color(0xFF047857),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('データ取得に失敗しました: $e')));
      }
    } finally {
      if (mounted) {
        setState(() => _isFetchingSmbc = false);
      }
    }
  }

  Future<void> _fetchJibunDataFromSheet() async {
    setState(() => _isFetchingJibun = true);
    try {
      double? balance;
      for (final gid in _jibunCandidateSheetGids) {
        final rows = await _fetchBankSheetRows(gid);
        balance = _extractJibunBalance(rows);
        if (balance != null) {
          break;
        }
      }
      final resolvedBalance = balance;
      if (resolvedBalance == null) {
        throw Exception('じぶん銀行の残高行が見つかりませんでした。GoogleシートのGIDまたは日付/残高列を確認してください');
      }
      const jibunName = 'じぶん銀行';
      setState(() {
        _applyFetchedAssetBalance(
          assetName: jibunName,
          balance: resolvedBalance,
        );
      });
      if (mounted) {
        _showSheetFetchResult(
          assetName: jibunName,
          balance: resolvedBalance,
          color: const Color(0xFFEA580C),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('データ取得に失敗しました: $e')));
      }
    } finally {
      if (mounted) {
        setState(() => _isFetchingJibun = false);
      }
    }
  }

  Future<List<Map<String, dynamic>>> _fetchAssetHistoryRows(
    String userId,
  ) async {
    late final List<Map<String, dynamic>> firstPage;
    try {
      firstPage = await _fetchAssetHistoryRpcPage(
        0,
        AssetManagementEgressPolicy.queryPageSize - 1,
      );
    } on PostgrestException catch (error) {
      if (!AssetManagementEgressPolicy.isMissingAssetHistoryRpcCode(
        error.code,
      )) {
        rethrow;
      }
      debugPrint(
        'Bounded asset history RPC is not deployed; using fallback: $error',
      );
      return AssetManagementEgressPolicy.fetchBoundedPages(
        maxRows: AssetManagementEgressPolicy.maxAssetHistoryRows,
        fetchPage: (from, to) async {
          final dynamic response = await _supabase
              .from('cfo_assets')
              .select('id,title,amount,created_at')
              .eq('user_id', userId)
              .order('created_at', ascending: true)
              .order('id', ascending: true)
              .range(from, to);
          return (response as List)
              .whereType<Map>()
              .map((row) => Map<String, dynamic>.from(row))
              .toList(growable: false);
        },
      );
    }

    return AssetManagementEgressPolicy.fetchBoundedPages(
      maxRows: AssetManagementEgressPolicy.maxAssetHistoryRows,
      firstPage: firstPage,
      fetchPage: _fetchAssetHistoryRpcPage,
    );
  }

  Future<List<Map<String, dynamic>>> _fetchAssetHistoryRpcPage(
    int from,
    int to,
  ) async {
    final dynamic response = await _supabase
        .rpc(
          'asset_management_recent_cfo_assets',
          params: <String, Object?>{
            'p_lookback_days':
                AssetManagementEgressPolicy.assetHistoryLookbackDays,
          },
        )
        .order('created_at', ascending: true)
        .order('id', ascending: true)
        .range(from, to);
    return (response as List)
        .whereType<Map>()
        .map((row) => Map<String, dynamic>.from(row))
        .toList(growable: false);
  }

  Future<void> _loadDataFromSupabase() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) return;
    try {
      final data = await _fetchAssetHistoryRows(userId);
      final Map<String, Map<String, double>> loadedData = {};
      final Set<String> loadedTypes = {'現金'};
      for (var item in data) {
        final createdAt = DateTime.parse(item['created_at']);
        final recordDate = AssetBalanceTimestampService.localRecordDate(
          createdAt,
          now: DateTime.now(),
        );
        final String dateKey = DateFormat('yyyy-MM-dd').format(recordDate);
        final String title = item['title'];
        final double amount = (item['amount'] as num).toDouble();
        loadedTypes.add(title);
        if (!loadedData.containsKey(dateKey)) {
          loadedData[dateKey] = {};
        }
        loadedData[dateKey]![title] = amount;
      }
      if (mounted) {
        setState(() {
          _assetTypes = loadedTypes.toList();
          _assetData = loadedData;
          _updateLastUpdatedDates();
          _sortAssetTypes(); // ★ ここで降順ソート
          _initControllers();
          _updateChartData();
        });
      }
    } catch (e) {
      debugPrint('Error loading assets: $e');
    }
  }

  // ★ 資産項目を金額の降順（資産→負債）で並び替える
  void _sortAssetTypes() {
    _assetTypes.sort((a, b) {
      final lastDateA = _lastUpdatedDates[a];
      final lastDateB = _lastUpdatedDates[b];

      // データがないものは -infinity として一番下へ
      final amountA = lastDateA != null
          ? (_assetData[lastDateA]?[a] ?? -double.infinity)
          : -double.infinity;
      final amountB = lastDateB != null
          ? (_assetData[lastDateB]?[b] ?? -double.infinity)
          : -double.infinity;

      // 降順（大きい順）
      return amountB.compareTo(amountA);
    });
  }

  GlobalKey _assetRowKeyForType(String type) {
    return _assetRowKeys.putIfAbsent(
      type,
      () => GlobalKey(debugLabel: 'asset_row_$type'),
    );
  }

  void _setWatchlistEntries(List<AssetWatchlistEntry> entries) {
    _watchlistByType = <String, AssetWatchlistEntry>{
      for (final entry in entries) entry.assetType: entry,
    };
  }

  List<AssetWatchlistEntry> get _visibleWatchlistEntries {
    final entries = _watchlistByType.values
        .where((entry) => _assetTypes.contains(entry.assetType))
        .toList();
    entries.sort((a, b) {
      final groupCompare = a.group.toLowerCase().compareTo(
            b.group.toLowerCase(),
          );
      if (groupCompare != 0) {
        if (a.group.isEmpty) return 1;
        if (b.group.isEmpty) return -1;
        return groupCompare;
      }
      return a.assetType.toLowerCase().compareTo(b.assetType.toLowerCase());
    });
    return entries;
  }

  /// ウォッチリストの集約ミラー pref_key (1 行 jsonb / MIRROR_PREF_SCHEMA.md)。
  static const String _watchlistMirrorKey = 'watchlist_entries';

  Future<void> _loadWatchlistEntries() async {
    final entries = await widget.watchlistService.loadEntries();
    if (mounted) {
      setState(() {
        _setWatchlistEntries(entries);
      });
    }
    // 先に他端末の削除トゥームストーンを取込んでから復元する。restore より前に
    // pull を直列化し、stale な tombstone での削除項目の復活/backfill を防ぐ
    // (review #1 restore↔pull レース)。
    await _pullWatchlistDeleted();
    // ローカル読込後にサーバ集約ミラーから復元する (端末間同期 / 集約優先)。
    await _restoreWatchlistFromMirror();
    unawaited(_refreshSyncSources());
  }

  /// ウォッチリストを `asset_pref_mirror` (pref_key: watchlist_entries) へ
  /// 1 行 upsert する (リボ設定と同じ集約方針 / #3352)。
  Future<void> _mirrorWatchlist() async {
    unawaited(_syncTimestampStore.markChanged(_watchlistMirrorKey));
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      return;
    }
    try {
      await _supabase.from('asset_pref_mirror').upsert(<String, dynamic>{
        'user_id': userId,
        'pref_key': _watchlistMirrorKey,
        'value': AssetWatchlistService.encodeMirrorValue(
          _watchlistByType.values.toList(),
        ),
        'updated_at': DateTime.now().toUtc().toIso8601String(),
      });
      // 全量 upsert 成功 = 全キー同期済み → dirty クリア。
      await _syncDirtyKeysStore.clearDomain(_watchlistMirrorKey);
    } catch (e) {
      debugPrint('watchlist mirror upsert failed: $e');
    }
    unawaited(_refreshSyncSources());
  }

  /// 削除したウォッチリスト項目のトゥームストーン (clear 伝播 / 復活防止)。
  static const MirrorTombstoneStore _watchlistTombstones = MirrorTombstoneStore(
    storageKey: 'watchlist_entries_deleted_v1',
  );

  Future<void> _recordWatchlistTombstone(
    String assetType, {
    required bool deleted,
  }) async {
    final store = await SharedPreferences.getInstance();
    if (deleted) {
      await _watchlistTombstones.addId(store, assetType);
    } else {
      await _watchlistTombstones.removeId(store, assetType);
    }
    unawaited(_mirrorWatchlistDeleted());
  }

  /// ウォッチリストの削除トゥームストーンをサーバへ反映 (他端末伝播)。
  Future<void> _mirrorWatchlistDeleted() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      return;
    }
    try {
      final store = await SharedPreferences.getInstance();
      final ids = _watchlistTombstones.activeIds(store);
      await _supabase.from('asset_pref_mirror').upsert(<String, dynamic>{
        'user_id': userId,
        'pref_key': 'watchlist_entries_deleted',
        'value': MirrorTombstoneStore.encodeMirror(ids),
        'updated_at': DateTime.now().toUtc().toIso8601String(),
      });
    } catch (e) {
      debugPrint('watchlist tombstone mirror upsert failed: $e');
    }
  }

  /// 他端末で削除されたウォッチリスト項目を取り込み、ローカルからも除去する。
  Future<void> _pullWatchlistDeleted() async {
    final debugMirror = widget.debugWatchlistDeletedMirror;
    if (debugMirror == null && _supabase.auth.currentUser == null) {
      return;
    }
    try {
      Map<String, dynamic>? value = debugMirror;
      if (value == null) {
        final rows = await _bootSelectPrefMirror('watchlist_entries_deleted');
        if (rows.isEmpty) {
          return;
        }
        final raw = rows.first['value'];
        if (raw is! Map) {
          return;
        }
        value = Map<String, dynamic>.from(raw);
      }
      final ids = MirrorTombstoneStore.decodeMirror(value);
      if (ids.isEmpty) {
        return;
      }
      final store = await SharedPreferences.getInstance();
      final incoming = await _watchlistTombstones.mergeRemoteIds(store, ids);
      final next = Map<String, AssetWatchlistEntry>.from(_watchlistByType);
      final before = next.length;
      next.removeWhere((key, _) => incoming.contains(key));
      if (next.length == before || !mounted) {
        return;
      }
      final mergedList = next.values.toList();
      setState(() {
        _setWatchlistEntries(mergedList);
      });
      _persistInBackground(
        widget.watchlistService.replaceAll(mergedList),
        'watchlist pull save',
      );
    } catch (e) {
      debugPrint('watchlist tombstone pull failed: $e');
    }
  }

  /// サーバ集約ミラーからウォッチリストを復元する (集約優先 + legacy local fallback)。
  /// ローカルに既に項目がある場合は上書きしない (オフライン編集を握り潰さない安全側)。
  Future<void> _restoreWatchlistFromMirror() async {
    final debugMirror = widget.debugWatchlistMirror;
    if (debugMirror == null && _supabase.auth.currentUser == null) {
      return;
    }
    final hasLocal = _watchlistByType.isNotEmpty;
    // 削除トゥームストーン: 復活させない / バックフィルしない。
    final tombstoned = _watchlistTombstones.activeIds(
      await SharedPreferences.getInstance(),
    );
    // フラグ OFF + ローカル値あり: サーバに無ければ初回バックフィルして終了。
    if (!_mirrorReadsAuthoritative && hasLocal && debugMirror == null) {
      unawaited(
        _backfillPrefIfServerMissing(_watchlistMirrorKey, _mirrorWatchlist),
      );
      return;
    }
    try {
      final dynamic value;
      final DateTime? mirrorUpdatedAt;
      if (debugMirror != null) {
        value = debugMirror;
        mirrorUpdatedAt = DateTime.now().toUtc();
      } else {
        final rows = await _bootSelectPrefMirror(_watchlistMirrorKey);
        if (rows.isEmpty) {
          // サーバ行が無い: ローカルにあれば初回バックフィル。
          if (hasLocal) {
            unawaited(_mirrorWatchlist());
          }
          return;
        }
        value = rows.first['value'];
        mirrorUpdatedAt = DateTime.tryParse(
          rows.first['updated_at']?.toString() ?? '',
        );
      }
      final serverEntries = AssetWatchlistService.decodeMirrorValue(value);
      if (serverEntries.isEmpty || !mounted) {
        return;
      }
      final adoptConflicts = await _shouldAdoptMirror(
        prefKey: _watchlistMirrorKey,
        hasLocal: hasLocal,
        mirrorUpdatedAt: mirrorUpdatedAt,
      );
      // union マージ: ローカルに無い assetType はサーバから追加 (他の項目は維持)。
      final localTypes = _watchlistByType.keys.toSet();
      final merged = Map<String, AssetWatchlistEntry>.from(_watchlistByType);
      final serverTypes = <String>{};
      var changed = false;
      // 削除トゥームストーン済み項目はローカルからも除く (clear 伝播 / 復活防止)。
      merged.removeWhere((key, _) {
        if (tombstoned.contains(key)) {
          changed = true;
          return true;
        }
        return false;
      });
      final dirtyKeys = await _syncDirtyKeysStore.loadDirty(
        _watchlistMirrorKey,
      );
      for (final entry in serverEntries) {
        serverTypes.add(entry.assetType);
        if (tombstoned.contains(entry.assetType)) {
          continue;
        }
        // #3415 保守的 per-key ガード: ローカル編集済み (dirty) キーは、ドメイン
        // 全体 adopt の巻き添えで上書きしない (同一キー衝突はローカル優先)。
        // フラグ OFF はここに来ても merged が local 由来 (空) なので
        // !containsKey が先に成立し no-op (本番無変更)。
        if (!merged.containsKey(entry.assetType) ||
            (adoptConflicts && !dirtyKeys.contains(entry.assetType))) {
          merged[entry.assetType] = entry;
          changed = true;
        }
      }
      if (changed && mounted) {
        final mergedList = merged.values.toList();
        setState(() {
          _setWatchlistEntries(mergedList);
        });
        // オフライン参照用にローカルへ書き戻し、ローカル更新時刻をミラーへ揃える。
        _persistInBackground(
          widget.watchlistService.replaceAll(mergedList),
          'watchlist restore save',
        );
        // additive 追加 / tombstone 除去でもデータが変化したので時刻を整合させる
        // (review #2 / ローカルが新しければ退行しない)。
        unawaited(
          _realignMirrorTimestamp(_watchlistMirrorKey, mirrorUpdatedAt),
        );
      }
      // ローカルにあってサーバに無い項目は、マージ結果をサーバへバックフィル。
      final localHasExtra = localTypes.any(
        (type) => !tombstoned.contains(type) && !serverTypes.contains(type),
      );
      if (localHasExtra && debugMirror == null) {
        unawaited(_mirrorWatchlist());
      }
    } catch (e) {
      debugPrint('watchlist mirror restore failed: $e');
    }
  }

  void _jumpToAssetType(String type) {
    final key = _assetRowKeys[type];
    if (key == null || key.currentContext == null) {
      _scrollTo(_keyStock);
      return;
    }
    _scrollTo(key);
  }

  Future<void> _showWatchlistDialog(String type) async {
