                  controller: groupController,
                  decoration: const InputDecoration(
                    labelText: 'Group',
                    hintText: 'invest / debt / this week',
                    border: OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: memoController,
                  maxLines: 3,
                  decoration: const InputDecoration(
                    labelText: 'Memo',
                    hintText: 'Why this item matters now',
                    border: OutlineInputBorder(),
                  ),
                ),
              ],
            ),
          ),
          actions: [
