              TextButton(
                onPressed: () async {
                  final entries = await widget.watchlistService.removeEntry(
                    type,
                  );
                  if (!mounted) return;
                  setState(() {
                    _setWatchlistEntries(entries);
                  });
                  unawaited(_recordWatchlistTombstone(type, deleted: true));
                  unawaited(_mirrorWatchlist());
                  if (dialogContext.mounted) {
                    Navigator.of(dialogContext).pop();
                  }
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(content: Text('Removed $type from watchlist')),
                  );
                },
                child: const Text('Remove'),
              ),
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(),
              child: const Text('Cancel'),
            ),
            FilledButton(
              onPressed: () async {
                final entries = await widget.watchlistService.saveEntry(
                  AssetWatchlistEntry(
                    assetType: type,
                    group: groupController.text,
                    memo: memoController.text,
                    addedAt: existing?.addedAt ?? DateTime.now(),
                  ),
                );
                if (!mounted) return;
                setState(() {
                  _setWatchlistEntries(entries);
                });
                unawaited(_recordWatchlistTombstone(type, deleted: false));
                // ローカル編集を dirty 記録 (巻き添え上書き防止)。
                unawaited(
                  _syncDirtyKeysStore.markDirty(_watchlistMirrorKey, type),
                );
                unawaited(_mirrorWatchlist());
                if (dialogContext.mounted) {
                  Navigator.of(dialogContext).pop();
                }
                ScaffoldMessenger.of(context).showSnackBar(
                  SnackBar(content: Text('Updated watchlist for $type')),
                );
              },
