  void _initControllers() {
    final newControllers = <String, TextEditingController>{};
    for (var type in _assetTypes) {
      if (_controllers.containsKey(type)) {
        newControllers[type] = _controllers[type]!;
      } else {
        newControllers[type] = TextEditingController();
      }
    }
    _controllers = newControllers;
  }

  void _updateLastUpdatedDates() {
    _lastUpdatedDates = {};
    final sortedDates = _assetData.keys.toList()..sort();
    for (var type in _assetTypes) {
      String? lastDate;
      for (var date in sortedDates.reversed) {
        if (_assetData[date]?.containsKey(type) ?? false) {
          lastDate = date;
          break;
        }
      }
      _lastUpdatedDates[type] = lastDate;
    }
  }

  void _toggleMinusForType(String type) {
    final controller = _controllers[type];
    if (controller == null) return;

    final current = controller.text.trim();
    if (current.isEmpty) {
      controller.text = '-';
    } else if (current.startsWith('-')) {
      controller.text = current.substring(1);
    } else {
      controller.text = '-$current';
    }

    controller.selection = TextSelection.collapsed(
      offset: controller.text.length,
    );
  }

  Future<void> _recordAssetAmountForToday(
    String type,
    double amount, {
    bool clearController = true,
    String? successMessage,
  }) async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) return;

    final today = _todayDateKey();
    final previousDate = _lastUpdatedDates[type];
    final previousAmount =
        previousDate == null ? null : _assetData[previousDate]?[type];
    try {
      await _supabase.from('cfo_assets').insert({
        'user_id': userId,
        'title': type,
        'amount': amount,
        'created_at': AssetBalanceTimestampService.encodeForDatabase(
          DateTime.now(),
        ),
      });

      setState(() {
        if (!_assetData.containsKey(today)) _assetData[today] = {};
        _assetData[today]![type] = amount;
        _updateLastUpdatedDates();
        _sortAssetTypes();
        _updateChartData();
      });

      final autoRecorded = previousAmount == null
          ? false
          : await _autoRecordUnknownExpenseFromAssetDrop(
              assetType: type,
              dateKey: today,
              previousAmount: previousAmount,
              currentAmount: amount,
            );
      if (autoRecorded) {
        await _fetchRecentFlows();
      }

      if (clearController) {
        _controllers[type]?.clear();
      }

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            autoRecorded
                ? '✅ $type を記録し、減少分を使途不明金として自動追加しました'
                : successMessage ?? '✅ $type を記録しました',
          ),
          backgroundColor: const Color(0xFF047857),
        ),
      );
      await _fetchTodayClosing();
    } catch (e) {
      debugPrint('Error saving $type: $e');
    }
  }

  Future<void> _quickUpdateAssetData(String type) async {
    final today = _todayDateKey();
    final lastDate = _lastUpdatedDates[type];
    if (lastDate == null || lastDate == today) {
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('$type は過去の記録がある場合のみ簡易更新できます')));
      return;
    }

    final lastAmount = _assetData[lastDate]?[type];
    if (lastAmount == null) {
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('$type の前回残高が見つかりません')));
      return;
    }

    await _recordAssetAmountForToday(
      type,
      lastAmount,
      successMessage: '✅ $type を前回と同額で簡易更新しました',
    );
  }

  /// 前回残高があり本日未更新 (= 同額で簡易更新できる) 口座の一覧。
  List<String> _staleQuickUpdatableTypes() {
    final today = _todayDateKey();
    return _assetTypes.where((type) {
      final lastDate = _lastUpdatedDates[type];
      if (lastDate == null || lastDate == today) return false;
      return _assetData[lastDate]?[type] != null;
    }).toList(growable: false);
  }

  /// 本日未更新の全口座を「前回と同額」で一括記録する。
  /// 金額が変わらないため減少検知 (使途不明金の自動追加) は対象外で、
  /// cfo_assets への insert は 1 リクエストに、当日クロージング再取得も
  /// 1 回にまとめる (1 口座ずつの 同額 連打で N 往復になるのを避ける)。
  Future<void> _quickUpdateAllStaleAssets() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) return;
    final today = _todayDateKey();
    final amounts = <String, double>{};
    for (final type in _staleQuickUpdatableTypes()) {
      final lastDate = _lastUpdatedDates[type];
      final amount = lastDate == null ? null : _assetData[lastDate]?[type];
      if (amount != null) {
        amounts[type] = amount;
      }
    }
    if (amounts.isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('同額で記録できる未更新口座はありません')));
      return;
    }

    final summaryLines = amounts.entries
        .map((entry) => '・${entry.key}: ${_formatYen(entry.value)}')
        .join('\n');
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text('未更新${amounts.length}口座を前回と同額で記録'),
        content: SingleChildScrollView(
          child: Text('以下を本日の残高として記録します。\n\n$summaryLines'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(false),
            child: const Text('キャンセル'),
          ),
          FilledButton(
            onPressed: () => Navigator.of(dialogContext).pop(true),
            child: const Text('一括記録'),
          ),
        ],
      ),
    );
    if (confirmed != true || !mounted) return;

    final nowIso = AssetBalanceTimestampService.encodeForDatabase(
      DateTime.now(),
    );
    try {
      await _supabase.from('cfo_assets').insert([
        for (final entry in amounts.entries)
          {
            'user_id': userId,
            'title': entry.key,
            'amount': entry.value,
            'created_at': nowIso,
          },
      ]);

      setState(() {
        final todayMap = _assetData.putIfAbsent(
          today,
          () => <String, double>{},
        );
        amounts.forEach((type, amount) => todayMap[type] = amount);
        _updateLastUpdatedDates();
        _sortAssetTypes();
        _updateChartData();
      });

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('✅ ${amounts.length}口座を前回と同額で一括記録しました'),
          backgroundColor: const Color(0xFF047857),
        ),
      );
      await _fetchTodayClosing();
    } catch (e) {
      debugPrint('Error bulk quick update: $e');
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('一括記録に失敗しました。時間をおいて再試行してください')),
      );
    }
  }

  List<AssetObsidianExistingBalance> _obsidianImportExistingBalances() {
    final balances = <AssetObsidianExistingBalance>[];
    for (final type in _assetTypes) {
      final dateKey = _lastUpdatedDates[type];
      final date = dateKey == null ? null : DateTime.tryParse(dateKey);
      final amount = dateKey == null ? null : _assetData[dateKey]?[type];
      if (date == null || amount == null) continue;
      balances.add(
        AssetObsidianExistingBalance(
          accountName: type,
          observedDate: date,
          amount: amount,
        ),
      );
    }
    return balances;
  }

  List<AssetObsidianExistingSubscription>
      _obsidianImportExistingSubscriptions() {
    return <AssetObsidianExistingSubscription>[
      for (final cost in _recurringFixedCosts)
        if (cost.category == AssetRecurringFixedCostCategory.subscription)
          AssetObsidianExistingSubscription(
            id: cost.id,
            name: cost.name,
            amount: cost.amount,
          ),
    ];
  }

  Future<void> _showObsidianVaultImportDialog() async {
    final imported = await showDialog<AssetObsidianApplySelection>(
      context: context,
      barrierDismissible: false,
      builder: (dialogContext) => AssetObsidianVaultImportDialog(
        existingBalances: _obsidianImportExistingBalances(),
        existingSubscriptions: _obsidianImportExistingSubscriptions(),
        onApply: _applyObsidianVaultSelection,
      ),
    );
    if (!mounted || imported == null || imported.totalCount == 0) return;
    final summaries = <String>[
      if (imported.balances.isNotEmpty) '残高${imported.balances.length}件を反映',
      if (imported.subscriptionCancellations.isNotEmpty)
        '解約済みサブスク${imported.subscriptionCancellations.length}件を削除',
    ];
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('✅ Obsidian保管庫から${summaries.join('、')}しました'),
        backgroundColor: const Color(0xFF047857),
      ),
    );
  }

  Future<void> _applyObsidianVaultSelection(
    AssetObsidianApplySelection selection,
  ) async {
    final subscriptions = validateObsidianSubscriptionCancellations(
      selection.subscriptionCancellations,
      _recurringFixedCosts,
    );
    if (selection.balances.isNotEmpty) {
      await _applyObsidianVaultBalances(selection.balances);
    }
    if (subscriptions.isEmpty) return;
    await _deleteRecurringFixedCosts(subscriptions);
  }

  /// 確認済みのObsidian残高だけを本日のスナップショットとして一括保存する。
  ///
  /// 保管庫の記録は既存履歴の再分類を表す場合があるため、通常の手入力保存で行う
  /// 残高減少→使途不明金の自動生成は実行しない。Markdown本文やローカルパスも
  /// Supabaseへ送信しない。
  Future<void> _applyObsidianVaultBalances(
    List<AssetObsidianImportCandidate> candidates,
  ) async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      throw StateError('残高の反映にはログインが必要です。');
    }
    if (candidates.isEmpty) return;

    final nowIso = AssetBalanceTimestampService.encodeForDatabase(
      DateTime.now(),
    );
    await _supabase.from('cfo_assets').insert([
      for (final candidate in candidates)
        {
          'user_id': userId,
          'title': candidate.accountName,
          'amount': candidate.amount,
          'created_at': nowIso,
        },
    ]);

    if (!mounted) return;
    final today = _todayDateKey();
    setState(() {
      final todayMap = _assetData.putIfAbsent(today, () => <String, double>{});
      for (final candidate in candidates) {
        if (!_assetTypes.contains(candidate.accountName)) {
          _assetTypes.add(candidate.accountName);
        }
        todayMap[candidate.accountName] = candidate.amount;
      }
      _initControllers();
      _updateLastUpdatedDates();
      _sortAssetTypes();
      _updateChartData();
    });
    await _fetchTodayClosing();
  }

  Future<void> _saveSingleAssetData(String type) async {
    final controller = _controllers[type];
    if (controller == null || controller.text.isEmpty) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('$type の金額を入力してください')));
      return;
    }

    final cleanText = controller.text.replaceAll(',', '');
    final parsedAmount = double.tryParse(cleanText);
    if (parsedAmount == null) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('$type の金額形式が不正です')));
      return;
    }
    final double amount = parsedAmount;
    await _recordAssetAmountForToday(type, amount);
  }

  Future<void> _saveAssetData() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) return;
    final String today = DateFormat('yyyy-MM-dd').format(DateTime.now());
    final Map<String, double> todayData = {};
    bool hasData = false;
    final List<String> invalidTypes = [];

    _controllers.forEach((assetType, controller) {
      if (controller.text.isNotEmpty) {
        final cleanText = controller.text.replaceAll(',', '');
        final parsedAmount = double.tryParse(cleanText);
        if (parsedAmount == null) {
          invalidTypes.add(assetType);
          return;
        }
        final double amount = parsedAmount;
        todayData[assetType] = amount;
        hasData = true;
      }
    });

    if (invalidTypes.isNotEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('金額形式を確認してください: ${invalidTypes.join(', ')}')),
      );
      return;
    }

    if (!hasData) return;

    try {
      final nowIso = AssetBalanceTimestampService.encodeForDatabase(
        DateTime.now(),
      );
      final previousAmounts = <String, double?>{
        for (final entry in todayData.entries)
          entry.key: _lastUpdatedDates[entry.key] == null
              ? null
              : _assetData[_lastUpdatedDates[entry.key]]?[entry.key],
      };
      for (var entry in todayData.entries) {
        await _supabase.from('cfo_assets').insert({
          'user_id': userId,
          'title': entry.key,
          'amount': entry.value,
          'created_at': nowIso,
        });
      }
      setState(() {
        if (!_assetData.containsKey(today)) _assetData[today] = {};
        _assetData[today]!.addAll(todayData);
        _updateLastUpdatedDates();
        _sortAssetTypes(); // ★ 一括更新後にも並び替え
        _updateChartData();
      });
      var autoRecordedCount = 0;
      for (final entry in todayData.entries) {
        final previousAmount = previousAmounts[entry.key];
        if (previousAmount == null) {
          continue;
        }
        final autoRecorded = await _autoRecordUnknownExpenseFromAssetDrop(
          assetType: entry.key,
          dateKey: today,
          previousAmount: previousAmount,
          currentAmount: entry.value,
        );
        if (autoRecorded) {
          autoRecordedCount += 1;
        }
      }
      if (autoRecordedCount > 0) {
        await _fetchRecentFlows();
      }
      _controllers.forEach((_, controller) => controller.clear());
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              autoRecordedCount > 0
                  ? '資産・負債を一括記録し、減少分を使途不明金として$autoRecordedCount件自動追加しました。'
                  : '資産・負債を一括記録しました。',
            ),
          ),
        );
      }
      await _fetchTodayClosing();
      // メイン口座の残高更新が給料反映なら、ここで検知して支払済みをリセットする
      // (残高増は入金フローを生成しないため、残高窓ベースの検知が要)。
      _maybeDetectSalaryDeposit();
    } catch (e) {
      debugPrint('Error saving assets: $e');
    }
  }

