  Future<void> _toggleSubscriptionPaid(String id, bool current) async {
    try {
      await _supabase
          .from('subscriptions')
          .update({'is_paid': !current}).eq('id', id);
      await _fetchSubscriptions();
      await _fetchTodayClosing();
