  // ==========================================
  // 4. 今月の支出と収入の記録（フロー）
  // ==========================================
  /// DB の過去 subscriptions から payment_source を取得してデフォルト選択肢にマージ
  /// (Win版#115: wealth_struggles に payment_source 列は存在しない。
  ///  支払先の蓄積は subscriptions.payment_source 側のみ)
  Future<void> _loadSourceOptionsFromDb() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) return;
    try {
      final data = await _supabase
          .from('subscriptions')
          .select('payment_source')
          .eq('user_id', userId)
          .not('payment_source', 'is', null)
          .limit(200);
      final sources = <String>{};
      for (final row in data) {
        final src = row['payment_source']?.toString().trim() ?? '';
        if (src.isNotEmpty) sources.add(src);
      }
      if (!mounted) return;
      final defaults = _sourceOptions.toList();
      for (final s in sources) {
        if (!defaults.contains(s)) defaults.add(s);
      }
      setState(() => _sourceOptions = defaults);
    } catch (e) {
      debugPrint('_loadSourceOptionsFromDb error: $e');
    }
  }

  Future<void> _loadPayslipFinanceData() async {
    // テスト注入 (debugInitialPayslip*) がある場合はフェッチで上書きしない。
    if (widget.debugInitialPayslipSalaryIncomes != null ||
        widget.debugInitialPayslipRows != null) {
      return;
    }
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      if (!mounted) return;
      setState(() {
        _payslipRows = <Map<String, dynamic>>[];
        _payslipSalaryIncomes = <Map<String, dynamic>>[];
        _isLoadingPayslipFinance = false;
      });
      return;
    }
    if (mounted) {
      setState(() => _isLoadingPayslipFinance = true);
    }
    try {
      final payslips = await _supabase
          .from('payslips')
          .select(
            'id,pay_date,company_name,gross_amount,net_amount,confidence,review_status,source_pdf_path',
          )
          .eq('user_id', userId)
          .order('pay_date', ascending: false)
          .limit(12);
      final salaryIncomes = await _supabase
          .from('salary_incomes')
          .select('id,pay_date,amount,description,source,confidence')
          .eq('user_id', userId)
          .order('pay_date', ascending: false)
          .limit(12);
      if (!mounted) return;
      setState(() {
        _payslipRows = List<Map<String, dynamic>>.from(payslips);
        _payslipSalaryIncomes = List<Map<String, dynamic>>.from(salaryIncomes);
        _isLoadingPayslipFinance = false;
        _payslipIngestionMessage = null;
      });
    } catch (e) {
      debugPrint('Error loading payslip finance data: $e');
      if (!mounted) return;
      setState(() {
        _payslipRows = <Map<String, dynamic>>[];
        _payslipSalaryIncomes = <Map<String, dynamic>>[];
        _isLoadingPayslipFinance = false;
        _payslipIngestionMessage =
            '給与明細テーブルの準備がまだです。最新マイグレーション適用後に再読み込みしてください。';
      });
    }
  }

  Future<void> _pickAndUploadPayslipPdf() async {
    if (_isUploadingPayslip) return;
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('給与明細PDFをアップロードする前にログインしてください。')),
      );
      return;
    }

    setState(() {
      _isUploadingPayslip = true;
      _payslipIngestionMessage = 'PDFの選択を待っています...';
    });
    try {
      final result = await FilePicker.pickFiles(
        type: FileType.custom,
        allowedExtensions: const <String>['pdf'],
        allowMultiple: false,
        withData: true,
      );
      if (result == null || result.files.isEmpty) {
        if (mounted) {
          setState(() {
            _isUploadingPayslip = false;
            _payslipIngestionMessage = null;
          });
        }
        return;
      }
      final file = result.files.single;
      final bytes = file.bytes;
      if (bytes == null || bytes.isEmpty) {
        throw Exception('PDFの中身が空でした。');
      }
      final timestamp = DateFormat('yyyyMMdd_HHmmss').format(DateTime.now());
      final fileName = _safePayslipStorageFileName(file.name);
      final storagePath = '$userId/$timestamp-$fileName';

      await _supabase.storage.from('payslips').uploadBinary(
            storagePath,
            bytes,
            fileOptions: const FileOptions(
              contentType: 'application/pdf',
              upsert: true,
            ),
          );
      final response = await _supabase.functions.invoke(
        'ai-hub',
        body: <String, dynamic>{
          'action': 'payslip.parse',
          'storage_path': storagePath,
          'enable_ai_fallback': true,
          'trace_id': 'asset-payslip-upload',
        },
      );
      final data = response.data;
      final parsed = data is Map ? Map<String, dynamic>.from(data) : null;
      final status = parsed?['status']?.toString() ?? 'parsed';
      if (!mounted) return;
      setState(() {
        _payslipIngestionMessage = status == 'needs_review'
            ? '給与明細を取り込みました。信頼度が低いため確認してください。'
            : '給与明細を取り込み、給料収入へ反映しました。';
      });
      await _loadPayslipFinanceData();
      unawaited(_computeDisposableBalanceFromServer(enableAiActions: false));
    } catch (e) {
      debugPrint('Error uploading payslip PDF: $e');
      if (!mounted) return;
      setState(() {
        _payslipIngestionMessage = '給与明細のアップロードに失敗しました: $e';
      });
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('給与明細のアップロードに失敗しました: $e')));
    } finally {
      if (mounted) {
        setState(() => _isUploadingPayslip = false);
      }
    }
  }

  Future<void> _computeDisposableBalanceFromServer({
    bool enableAiActions = true,
  }) async {
    if (_isComputingDisposableBalance) return;
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) return;
    setState(() {
      _isComputingDisposableBalance = true;
      _disposableBalanceMessage = '可処分残高を計算しています...';
    });
    try {
      final response = await _supabase.functions.invoke(
        'ai-hub',
        body: <String, dynamic>{
          'action': 'asset.disposable_balance.compute',
          'as_of_date': _dateOnly(_now),
          'salary_day': _salaryDay,
          'enable_ai_actions': enableAiActions,
          'trace_id': 'asset-disposable-balance',
        },
      );
      final data = response.data;
      if (!mounted) return;
      setState(() {
        _serverDisposableBalanceResult =
            data is Map ? Map<String, dynamic>.from(data) : null;
        _disposableBalanceMessage = '可処分残高を更新しました。';
      });
    } catch (e) {
      debugPrint('Error computing disposable balance: $e');
      if (!mounted) return;
      setState(() {
        _disposableBalanceMessage = 'サーバー計算を利用できないため、端末側の概算を表示しています。';
      });
    } finally {
      if (mounted) {
        setState(() => _isComputingDisposableBalance = false);
      }
    }
  }

  String _safePayslipStorageFileName(String value) {
    const fallback = 'payslip.pdf';
    final trimmed = value.trim().isEmpty ? fallback : value.trim();
    final sanitized = trimmed
        .replaceAll(RegExp(r'[^A-Za-z0-9._-]+'), '-')
        .replaceAll(RegExp(r'-+'), '-');
    if (sanitized.toLowerCase().endsWith('.pdf')) {
      return sanitized;
    }
    return '$sanitized.pdf';
  }

  Future<void> _fetchRecentFlows() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) return;
    try {
      final cutoff = AssetManagementEgressPolicy.recentFlowCutoff(
        DateTime.now(),
      ).toIso8601String();
      final data = await AssetManagementEgressPolicy.fetchBoundedPages(
        maxRows: AssetManagementEgressPolicy.maxRecentFlowRows,
        fetchPage: (from, to) async {
          final dynamic response = await _supabase
              .from('wealth_struggles')
              .select('id,action_type,amount,description,occurred_at')
              .eq('user_id', userId)
              .gte('occurred_at', cutoff)
              .order('occurred_at', ascending: false)
              .order('id', ascending: false)
              .range(from, to);
          return (response as List)
              .whereType<Map>()
              .map((row) => Map<String, dynamic>.from(row))
              .toList(growable: false);
        },
      );

      if (mounted) {
        setState(() {
          _recentFlows = List<Map<String, dynamic>>.from(data);
        });
        unawaited(
          _resolveInitialDisplayMode(
            hasExistingData:
                _recentFlows.isNotEmpty || _subscriptions.isNotEmpty,
          ),
        );
        // フロー更新後に給料振込検知を再評価(サイクル窓の収入が増えた可能性)。
        _maybeDetectSalaryDeposit();
      }
    } catch (e) {
      debugPrint('Error fetching flows: $e');
    }
  }

  Future<Set<String>> _fetchSmbcImportKeys({
    required String userId,
    required DateTime firstTransactionDate,
    required DateTime lastTransactionDate,
  }) async {
    final start = DateTime(
      firstTransactionDate.year,
      firstTransactionDate.month,
      firstTransactionDate.day,
    ).toUtc();
    final end = DateTime(
      lastTransactionDate.year,
      lastTransactionDate.month,
      lastTransactionDate.day + 1,
    ).toUtc();
    final rows = await AssetManagementEgressPolicy.fetchBoundedPages(
      maxRows: AssetManagementEgressPolicy.maxImportDedupRows,
      fetchPage: (from, to) async {
        final dynamic response = await _supabase
            .from('wealth_struggles')
            .select('id,description,occurred_at')
            .eq('user_id', userId)
            .gte('occurred_at', start.toIso8601String())
            .lt('occurred_at', end.toIso8601String())
            .like('description', '%[import:smbc:%]')
            .order('occurred_at', ascending: true)
            .order('id', ascending: true)
            .range(from, to);
        return (response as List)
            .whereType<Map>()
            .map((row) => Map<String, dynamic>.from(row))
            .toList(growable: false);
      },
    );
    final keys = <String>{};
    for (final row in rows) {
      final key = _extractSmbcImportKey(row['description']?.toString() ?? '');
      if (key != null) {
        keys.add(key);
      }
    }
    return keys;
  }

  Future<void> _pickAndImportSmbcCsv() async {
    if (_isImportingSmbcCsv) return;
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) return;

    setState(() => _isImportingSmbcCsv = true);
    try {
      final result = await FilePicker.pickFiles(
        type: FileType.custom,
        allowedExtensions: const ['csv'],
        allowMultiple: false,
        withData: true,
      );
      if (result == null || result.files.isEmpty) return;

      final file = result.files.single;
      final bytes = file.bytes;
      if (bytes == null || bytes.isEmpty) {
        throw Exception('CSVデータを読み込めませんでした');
      }

      final text = const CsvBytesDecoder().decode(
        bytes,
        looksValid: SmbcCsvImportService.looksLikeCsv,
        formatName: '三井住友銀行CSV',
      );
      final parsed = const SmbcCsvImportService().parse(text);
      if (parsed.transactions.isEmpty) {
        throw Exception('登録できる三井住友銀行の入出金明細が見つかりませんでした');
      }

      var firstTransactionDate = parsed.transactions.first.date;
      var lastTransactionDate = firstTransactionDate;
      for (final transaction in parsed.transactions.skip(1)) {
        if (transaction.date.isBefore(firstTransactionDate)) {
          firstTransactionDate = transaction.date;
        }
        if (transaction.date.isAfter(lastTransactionDate)) {
          lastTransactionDate = transaction.date;
        }
      }
      final knownImportKeys = await _fetchSmbcImportKeys(
        userId: userId,
        firstTransactionDate: firstTransactionDate,
        lastTransactionDate: lastTransactionDate,
      );
      final records = <Map<String, dynamic>>[];
      final classificationExpenses = <Map<String, dynamic>>[];
      var duplicateCount = 0;

      for (final transaction in parsed.transactions) {
        if (knownImportKeys.contains(transaction.importKey)) {
          duplicateCount += 1;
          continue;
        }
        knownImportKeys.add(transaction.importKey);
        final flowType = transaction.isDeposit ? '収入' : '支出';
        records.add({
          'user_id': userId,
          'action_type': transaction.actionType,
          'amount': transaction.amount,
          'description': _withFlowImportMarker(
            _composeFlowDescription(
              flowType: flowType,
              source: _smbcCsvSource,
              memo: transaction.displayMemo,
            ),
            transaction.importKey,
          ),
          'occurred_at': transaction.date.toUtc().toIso8601String(),
        });
        if (!transaction.isDeposit) {
          classificationExpenses.add({
            'source': 'smbc_csv',
            'id': transaction.importKey,
            'posted_at': _dateOnly(transaction.date),
            'description': transaction.displayMemo,
            'amount': transaction.amount.abs(),
          });
        }
      }

      for (var i = 0; i < records.length; i += 200) {
        final chunk = records.sublist(i, min(i + 200, records.length));
        await _supabase.from('wealth_struggles').insert(chunk);
      }
      if (classificationExpenses.isNotEmpty) {
        unawaited(_classifyImportedExpenses(classificationExpenses));
      }

      final latestDate = parsed.latestDate;
      final latestBalance = parsed.latestBalance;
      if (mounted) {
        setState(() {
          if (!_sourceOptions.contains(_smbcCsvSource)) {
            _sourceOptions = [..._sourceOptions, _smbcCsvSource];
          }
          if (latestDate != null) {
            _selectedFlowHistoryMonth = _monthStart(latestDate);
          }
          if (latestBalance != null) {
            _applyFetchedAssetBalance(
              assetName: '三井住友銀行',
              balance: latestBalance.toDouble(),
            );
          }
        });
      }

      await _fetchRecentFlows();
      await _fetchTodayClosing();

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            '三井住友CSVを取り込みました: ${records.length}件登録 / '
            '$duplicateCount件重複スキップ / ${parsed.skippedRows}行スキップ',
          ),
          backgroundColor: const Color(0xFF047857),
        ),
      );
    } catch (e) {
      debugPrint('Error importing SMBC CSV: $e');
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('三井住友CSVの取込に失敗しました: $e')));
    } finally {
      if (mounted) {
        setState(() => _isImportingSmbcCsv = false);
      }
    }
  }

  Future<void> _classifyImportedExpenses(
    List<Map<String, dynamic>> expenses,
  ) async {
    try {
      await _supabase.functions.invoke(
        'ai-hub',
        body: <String, dynamic>{
          'action': 'expense.classify',
          'source': 'smbc_csv',
          'expenses': expenses,
          'trace_id': 'asset-smbc-csv-classify',
        },
      );
    } catch (e) {
      debugPrint('Expense classification failed: $e');
    }
  }

  String _flowSourceForAssetType(String assetType) {
    final normalized = assetType.trim().isEmpty ? '口座' : assetType.trim();
    return '[$normalized]';
  }

  bool _isAutoAssetDeltaFlow(Map<String, dynamic> flow) {
    return _extractAutoAssetDeltaKey(flow['description']?.toString() ?? '') !=
        null;
  }

  String _autoAssetDeltaKey({
    required String dateKey,
    required String assetType,
    required double previousAmount,
    required double currentAmount,
  }) {
    final encodedAsset = base64Url.encode(utf8.encode(assetType.trim()));
    return [
      dateKey,
      encodedAsset,
      previousAmount.round().toString(),
      currentAmount.round().toString(),
    ].join(':');
  }

  Future<bool> _autoRecordUnknownExpenseFromAssetDrop({
    required String assetType,
    required String dateKey,
    required double previousAmount,
    required double currentAmount,
  }) async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null ||
        !AssetUnknownExpenseRuleService.shouldAutoRecordFromAssetDrop(
          assetType: assetType,
          previousAmount: previousAmount,
          currentAmount: currentAmount,
        )) {
      return false;
    }

    final markerKey = _autoAssetDeltaKey(
      dateKey: dateKey,
      assetType: assetType,
      previousAmount: previousAmount,
      currentAmount: currentAmount,
    );
    final alreadyExists = _recentFlows.any(
      (flow) =>
          _extractAutoAssetDeltaKey(flow['description']?.toString() ?? '') ==
          markerKey,
    );
    if (alreadyExists) {
      return false;
    }

    final amount = previousAmount - currentAmount;
    final source = _flowSourceForAssetType(assetType);
    final occurredAt = DateTime.tryParse(dateKey) ?? DateTime.now();
    await _supabase.from('wealth_struggles').insert({
      'user_id': userId,
      'action_type': 'expense',
      'amount': amount.round(),
      'description': _withFlowAutoAssetDeltaMarker(
        _composeFlowDescription(
          flowType: '支出',
          source: source,
          memo: '使途不明金（残高差分から自動記録）',
          wasteCategory: null,
        ),
        markerKey,
      ),
      'occurred_at': occurredAt.toUtc().toIso8601String(),
    });

    if (mounted && !_sourceOptions.contains(source)) {
      setState(() {
        _sourceOptions = [..._sourceOptions, source];
      });
    }
    return true;
  }

  String _composeFlowDescription({
    required String flowType,
    required String source,
    required String memo,
    String? destination,
    String? wasteCategory,
  }) {
    final normalizedSource = source.trim();
    final normalizedMemo = memo.trim();
    final String description;
    if (flowType == '振替') {
      final normalizedDestination = (destination ?? '').trim();
      final route = '$normalizedSource -> $normalizedDestination';
      if (normalizedMemo.isEmpty) {
        return route;
      }
      return '$route $normalizedMemo';
    }
    if (normalizedMemo.isEmpty) {
      description = normalizedSource;
    } else {
      description = '$normalizedSource $normalizedMemo';
    }
    if (flowType != '支出') {
      return description;
    }
    return WasteTrackingService.attachWasteCategory(description, wasteCategory);
  }

  FlowDescriptionParts _parseFlowDescription(
    String description, {
    String? actionType,
  }) {
    // メタデータマーカー除去だけページ固有正規表現に依存するため残し、
    // パース本体は純関数サービスへ委譲する(振る舞い不変)。
    final normalizedDescription = _stripFlowMetadataMarkers(description.trim());
    return AssetFlowDescriptionService.parse(
      normalizedDescription,
      actionType: actionType,
    );
  }

  String _flowDisplayTitle(Map<String, dynamic> flow) {
    return AssetFlowDescriptionService.displayTitle(
      _parseFlowDescription(
        flow['description']?.toString() ?? '',
        actionType: flow['action_type']?.toString() ?? '',
      ),
    );
  }

  String _flowLabelToActionType(String label) {
    switch (label) {
      case '収入':
        return 'conquer';
      case '振替':
        return 'transfer';
      default:
        return 'expense';
    }
  }

  String _actionTypeToFlowLabel(String actionType) {
    switch (actionType) {
      case 'conquer':
        return '収入';
      case 'transfer':
        return '振替';
      default:
        return '支出';
    }
  }

  Future<void> _recordFlow() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) return;

    final memo = _flowMemoController.text.trim();
    final amountStr = _flowAmountController.text.replaceAll(',', '');
    final amount = int.tryParse(amountStr);
    final isTransfer = _selectedFlowType == '振替';

    if (amount == null || amount <= 0 || (!isTransfer && memo.isEmpty)) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            isTransfer ? '振替先と金額(1円以上)を正しく入力してください' : '内容と金額(1円以上)を正しく入力してください',
          ),
        ),
      );
      return;
    }

    if (isTransfer && _selectedSource == _selectedTransferDestination) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('振替元と振替先は別の口座を選択してください')));
      return;
    }

    final actionType = _flowLabelToActionType(_selectedFlowType);

    try {
      await _supabase.from('wealth_struggles').insert({
        'user_id': userId,
        'action_type': actionType,
        'amount': amount,
        'description': _composeFlowDescription(
          flowType: _selectedFlowType,
          source: _selectedSource,
          destination: isTransfer ? _selectedTransferDestination : null,
          memo: memo,
          wasteCategory: _isExpenseFlowSelected ? _selectedWasteCategory : null,
        ),
        'occurred_at': _selectedFlowDate.toUtc().toIso8601String(),
      });

      _flowMemoController.clear();
      _flowAmountController.clear();
      if (mounted) {
        setState(() {
          _selectedFlowHistoryMonth = _monthStart(_selectedFlowDate);
          _selectedWasteCategory = null;
        });
      }
      await _fetchRecentFlows();

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(isTransfer ? '振替を記録しました' : '収支を記録しました'),
            backgroundColor: Theme.of(context).colorScheme.onSurface,
          ),
        );
      }
      await _fetchTodayClosing();
    } catch (e) {
      debugPrint('Error recording flow: $e');
    }
  }

  Future<void> _editFlow(Map<String, dynamic> flow) async {
    final flowId = flow['id']?.toString();
    if (flowId == null || flowId.isEmpty) return;

    final currentActionType = flow['action_type']?.toString() ?? 'expense';
    final parsed = _parseFlowDescription(
      flow['description']?.toString() ?? '',
      actionType: currentActionType,
    );
    final availableSources = [..._sourceOptions];
    if (parsed.source.isNotEmpty && !availableSources.contains(parsed.source)) {
      availableSources.add(parsed.source);
    }
    if (parsed.destination.isNotEmpty &&
        !availableSources.contains(parsed.destination)) {
      availableSources.add(parsed.destination);
    }

    final memoController = TextEditingController(text: parsed.memo);
    final amountController = TextEditingController(
      text: ((flow['amount'] as num?)?.toInt() ?? 0).toString(),
    );
    var selectedSource =
        parsed.source.isNotEmpty ? parsed.source : _defaultFlowSource;
    if (!availableSources.contains(selectedSource)) {
      availableSources.add(selectedSource);
    }
    var selectedType = _actionTypeToFlowLabel(currentActionType);
    var selectedDestination = _resolvedTransferDestination(
      selectedSource,
      preferred: parsed.destination,
    );
    String? selectedWasteCategory = parsed.wasteCategory;
    var selectedDate =
        DateTime.tryParse(flow['occurred_at']?.toString() ?? '')?.toLocal() ??
            DateTime.now();

    try {
      final shouldSave = await showDialog<bool>(
        context: context,
        builder: (context) => StatefulBuilder(
          builder: (context, setDialogState) => AlertDialog(
            title: const Text('収支記録を編集'),
            content: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  DropdownButtonFormField<String>(
                    initialValue: selectedType,
                    decoration: const InputDecoration(
                      labelText: '種別',
                      border: OutlineInputBorder(),
                      isDense: true,
                    ),
                    items: _flowTypeOptions
                        .map(
                          (value) => DropdownMenuItem(
                            value: value,
                            child: Text(value),
                          ),
                        )
                        .toList(),
                    onChanged: (value) {
                      if (value == null) return;
                      setDialogState(() {
                        selectedType = value;
                        if (value == '振替') {
                          selectedDestination = _resolvedTransferDestination(
                            selectedSource,
                            preferred: selectedDestination,
                          );
                        }
                        if (value != '支出') {
                          selectedWasteCategory = null;
                        }
                      });
                    },
                  ),
                  const SizedBox(height: 12),
                  InkWell(
                    onTap: () async {
                      final picked = await showDatePicker(
                        context: context,
                        initialDate: selectedDate,
                        firstDate: DateTime(2020, 1, 1),
                        lastDate: DateTime.now(),
                      );
                      if (picked == null) return;
                      setDialogState(() => selectedDate = picked);
                    },
                    child: InputDecorator(
                      decoration: const InputDecoration(
                        labelText: '日付',
                        border: OutlineInputBorder(),
                        isDense: true,
                      ),
                      child: Row(
                        mainAxisAlignment: MainAxisAlignment.spaceBetween,
                        children: [
                          Text(DateFormat('yyyy/MM/dd').format(selectedDate)),
                          const Icon(Icons.calendar_today, size: 16),
                        ],
                      ),
                    ),
                  ),
                  const SizedBox(height: 12),
                  DropdownButtonFormField<String>(
                    initialValue: selectedSource,
                    decoration: InputDecoration(
                      labelText: selectedType == '振替' ? '振替元' : '入出金元',
                      border: const OutlineInputBorder(),
                      isDense: true,
                    ),
                    items: availableSources
                        .map(
                          (source) => DropdownMenuItem(
                            value: source,
                            child: Text(
                              source.replaceAll('[', '').replaceAll(']', ''),
                            ),
                          ),
                        )
                        .toList(),
                    onChanged: (value) {
                      if (value == null) return;
                      setDialogState(() {
                        selectedSource = value;
                        if (selectedType == '振替') {
                          selectedDestination = _resolvedTransferDestination(
                            value,
                            preferred: selectedDestination,
                          );
                        }
                      });
                    },
                  ),
                  if (selectedType == '振替') ...[
                    const SizedBox(height: 12),
                    DropdownButtonFormField<String>(
                      initialValue: selectedDestination,
                      decoration: const InputDecoration(
                        labelText: '振替先',
                        border: OutlineInputBorder(),
                        isDense: true,
                      ),
                      items: _transferDestinationOptions(
                        selectedSource,
                        include: selectedDestination,
                      )
                          .map(
                            (source) => DropdownMenuItem(
                              value: source,
                              child: Text(_sourceLabel(source)),
                            ),
                          )
                          .toList(),
                      onChanged: (value) {
                        if (value == null) return;
                        setDialogState(() => selectedDestination = value);
                      },
                    ),
                  ],
                  if (selectedType == '支出') ...[
                    const SizedBox(height: 12),
                    DropdownButtonFormField<String?>(
                      initialValue: selectedWasteCategory,
                      decoration: const InputDecoration(
                        labelText: '浪費カテゴリ',
                        border: OutlineInputBorder(),
                        isDense: true,
                      ),
                      items: <DropdownMenuItem<String?>>[
                        const DropdownMenuItem<String?>(
                          value: null,
                          child: Text('分類なし'),
                        ),
                        ...WasteTrackingService.categoryLabels.map(
                          (label) => DropdownMenuItem<String?>(
                            value: label,
                            child: Text(label),
                          ),
                        ),
                      ],
                      onChanged: (value) {
                        setDialogState(() {
                          selectedWasteCategory =
                              WasteTrackingService.normalizeCategory(value);
                        });
                      },
                    ),
                  ],
                  const SizedBox(height: 12),
                  TextField(
                    controller: memoController,
                    decoration: InputDecoration(
                      labelText: selectedType == '振替' ? 'メモ（任意）' : '内容',
                      border: const OutlineInputBorder(),
                      isDense: true,
                    ),
                  ),
                  const SizedBox(height: 12),
                  TextField(
                    controller: amountController,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(
                      labelText: '金額 (円)',
                      border: OutlineInputBorder(),
                      isDense: true,
                    ),
                  ),
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(context, false),
                child: const Text('キャンセル'),
              ),
              FilledButton(
                onPressed: () => Navigator.pop(context, true),
                child: const Text('保存'),
              ),
            ],
          ),
        ),
      );

      if (shouldSave != true) return;

      final memo = memoController.text.trim();
      final amount = int.tryParse(amountController.text.replaceAll(',', ''));
      final isTransfer = selectedType == '振替';
      if (amount == null || amount <= 0 || (!isTransfer && memo.isEmpty)) {
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              isTransfer ? '振替先と金額を正しく入力してください' : '内容と金額を正しく入力してください',
            ),
          ),
        );
        return;
      }
      if (isTransfer && selectedSource == selectedDestination) {
        if (!mounted) return;
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(const SnackBar(content: Text('振替元と振替先は別の口座を選択してください')));
        return;
      }

      await _supabase.from('wealth_struggles').update({
        'action_type': _flowLabelToActionType(selectedType),
        'amount': amount,
        'description': _composeFlowDescription(
          flowType: selectedType,
          source: selectedSource,
          destination: isTransfer ? selectedDestination : null,
          memo: memo,
          wasteCategory: selectedType == '支出' ? selectedWasteCategory : null,
        ),
        'occurred_at': selectedDate.toUtc().toIso8601String(),
      }).eq('id', flowId);

      if (mounted) {
        setState(() {
          _selectedFlowHistoryMonth = _monthStart(selectedDate);
        });
      }

      await _fetchRecentFlows();
      await _fetchTodayClosing();

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(isTransfer ? '振替記録を更新しました' : '収支記録を更新しました'),
          backgroundColor: Theme.of(context).colorScheme.onSurface,
        ),
      );
    } catch (e) {
      debugPrint('Error editing flow: $e');
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('収支記録の更新に失敗しました: $e')));
    } finally {
      memoController.dispose();
      amountController.dispose();
    }
  }

  // ==========================================
  // 5. 必須タスクの記録と把握
  // ==========================================
  Future<bool> _confirmDeleteFlow(Map<String, dynamic> flow) async {
    final actionType = flow['action_type']?.toString() ?? 'expense';
    final parsed = _parseFlowDescription(
      flow['description']?.toString() ?? '',
      actionType: actionType,
    );
    final title = _flowDisplayTitle(flow).trim().isNotEmpty
        ? _flowDisplayTitle(flow)
        : (parsed.memo.isNotEmpty ? parsed.memo : 'この収支記録');
    final amount = (flow['amount'] as num?)?.toInt() ?? 0;
    final date =
        DateTime.tryParse(flow['occurred_at']?.toString() ?? '')?.toLocal() ??
            DateTime.now();
    final typeLabel = _actionTypeToFlowLabel(actionType);

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('削除の確認'),
        content: Text(
          '${DateFormat('yyyy/MM/dd').format(date)} の$typeLabel「$title」（¥${NumberFormat('#,###').format(amount)}）を削除しますか？',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('キャンセル'),
          ),
          TextButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text(
              '削除',
              style: TextStyle(color: Color(0xFFB91C1C), height: 1.5),
            ),
          ),
        ],
      ),
    );

    return confirmed ?? false;
  }

  Future<void> _deleteFlow(Map<String, dynamic> flow) async {
    final userId = _supabase.auth.currentUser?.id;
    final flowId = flow['id']?.toString();
    if (userId == null || flowId == null || flowId.isEmpty) return;

    final shouldDelete = await _confirmDeleteFlow(flow);
    if (!shouldDelete) return;

    try {
      await _supabase
          .from('wealth_struggles')
          .delete()
          .eq('id', flowId)
          .eq('user_id', userId);

      await _fetchRecentFlows();
      await _fetchTodayClosing();

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: const Text('収支記録を削除しました'),
          backgroundColor: Theme.of(context).colorScheme.onSurface,
        ),
      );
    } catch (e) {
      debugPrint('Error deleting flow: $e');
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('収支記録の削除に失敗しました: $e')));
    }
  }

  // ===== 「今日やること」ToDo =====
  //
  // 思想: やらずに寝たタスクは翌日の借金。未完了で予定日を過ぎたタスクは
  // 「繰り越し(借金)」として日数付きで重く表示し、完遂ログは細木数子AIへ渡す。
  // 永続化はローカル(SharedPreferences)+ asset_pref_mirror(pref_key='daily_todo')の
  // 軽量ミラーで、DBマイグレーション不要・端末跨ぎ同期。

  static const String _dailyTodoMirrorKey = 'daily_todo';

  Future<void> _loadDailyTodos() async {
    if (mounted) {
      setState(() => _isLoadingDailyTodos = true);
    }
    try {
      final snapshot = await _dailyTodoStore.load();
      if (mounted) {
        setState(() {
          _dailyTodos = _orderedDailyTodos(snapshot.tasks);
          _dailyTodoLog = snapshot.log;
          _isLoadingDailyTodos = false;
        });
      }
    } catch (_) {
      if (mounted) {
        setState(() => _isLoadingDailyTodos = false);
      }
    }
    // ローカル反映後に他端末のミラーを取り込む(空でも実行してリモートを拾う)。
    unawaited(_restoreDailyTodosFromMirror());
  }

  /// 予定日の古い順→未完了を先に、という並びに整える(繰り越し借金を上へ)。
  List<DailyTodoTask> _orderedDailyTodos(List<DailyTodoTask> tasks) {
    final ordered = List<DailyTodoTask>.from(tasks);
    ordered.sort((a, b) {
      if (a.completed != b.completed) {
        return a.completed ? 1 : -1;
      }
      final byDate = a.plannedDate.compareTo(b.plannedDate);
      if (byDate != 0) {
        return byDate;
      }
      return a.title.compareTo(b.title);
    });
    return ordered;
  }

  /// ローカルへ保存し、ミラーへ退避する(端末跨ぎ同期)。
  Future<void> _persistDailyTodos() async {
    await _dailyTodoStore.save(
      tasks: _dailyTodos,
      log: _dailyTodoLog,
      updatedAt: _now,
    );
    unawaited(_mirrorDailyTodos());
  }

  Future<void> _mirrorDailyTodos() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      return;
    }
    try {
      final value = await _dailyTodoStore.encodeMirror();
      if (value == null) {
        return;
      }
      await _supabase.from('asset_pref_mirror').upsert(<String, dynamic>{
        'user_id': userId,
        'pref_key': _dailyTodoMirrorKey,
        'value': value,
        'updated_at': DateTime.now().toUtc().toIso8601String(),
      });
    } catch (e) {
      debugPrint('daily todo mirror upsert failed: $e');
    }
  }

  Future<void> _restoreDailyTodosFromMirror() async {
    if (_supabase.auth.currentUser == null) {
      return;
    }
    try {
      final rows = await _supabase
          .from('asset_pref_mirror')
          .select()
          .eq('pref_key', _dailyTodoMirrorKey);
      if (rows.isEmpty) {
        return;
      }
      final result = await _dailyTodoStore.mergeRemote(rows.first['value']);
      if (!result.changed || !mounted) {
        return;
      }
      setState(() {
        _dailyTodos = _orderedDailyTodos(result.snapshot.tasks);
        _dailyTodoLog = result.snapshot.log;
      });
    } catch (e) {
      debugPrint('daily todo mirror restore failed: $e');
    }
  }

  Future<void> _addDailyTodo() async {
    final titleController = TextEditingController();
    var plannedDate = DateTime(_now.year, _now.month, _now.day);
    final added = await showDialog<bool>(
      context: context,
      builder: (context) => StatefulBuilder(
        builder: (context, setDialogState) {
          return AlertDialog(
            title: const Text('今日やることを追加'),
            content: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(
                  controller: titleController,
                  autofocus: true,
                  decoration: const InputDecoration(
                    labelText: 'やること (例: 請求書の確認・30分運動)',
                  ),
                  onSubmitted: (_) => Navigator.pop(context, true),
                ),
                const SizedBox(height: 16),
                InkWell(
                  onTap: () async {
                    final date = await showDatePicker(
                      context: context,
                      initialDate: plannedDate,
                      firstDate: DateTime(_now.year - 1),
                      lastDate: DateTime(_now.year + 2),
                    );
                    if (date != null) {
                      setDialogState(() => plannedDate = date);
                    }
                  },
                  child: Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 12,
                      vertical: 12,
                    ),
                    decoration: BoxDecoration(
                      border: Border.all(
                        color: Theme.of(context).colorScheme.onSurfaceVariant,
                      ),
                      borderRadius: BorderRadius.circular(4),
                    ),
                    child: Row(
                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      children: [
                        Text(
                          '予定日: ${DateFormat('yyyy/MM/dd').format(plannedDate)}',
                        ),
                        Icon(
                          Icons.calendar_today,
                          size: 16,
                          color: Theme.of(context).colorScheme.onSurfaceVariant,
                        ),
                      ],
                    ),
                  ),
                ),
              ],
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(context, false),
                child: const Text('キャンセル'),
              ),
              ElevatedButton(
                onPressed: () => Navigator.pop(context, true),
                child: const Text('追加'),
              ),
            ],
          );
        },
      ),
    );
    if (added != true) {
      return;
    }
    final title = titleController.text.trim();
    if (title.isEmpty) {
      return;
    }
    final task = DailyTodoTask(
      id: 'todo_${DateTime.now().microsecondsSinceEpoch}',
      title: title,
      plannedDate: plannedDate,
    );
    setState(() {
      _dailyTodos = _orderedDailyTodos(<DailyTodoTask>[..._dailyTodos, task]);
    });
    await _persistDailyTodos();
  }

  Future<void> _toggleDailyTodo(DailyTodoTask task, bool completed) async {
    final now = DateTime.now();
    final previousCompletedAt = task.completedAt;
    final updated = task.copyWith(
      completed: completed,
      completedAt: completed ? now : null,
    );
    final nextLog = List<DailyTodoCompletionLogEntry>.from(_dailyTodoLog);
    if (completed) {
      nextLog.add(
        DailyTodoCompletionLogEntry(
          dateKey: dailyTodoDateKey(now),
          title: task.title,
          completedAt: now,
        ),
      );
    } else if (previousCompletedAt != null) {
      // 完了取り消しは、その完了で積んだログ行だけ取り除く(実績の捏造/残留を防ぐ)。
      final removeDateKey = dailyTodoDateKey(previousCompletedAt);
      nextLog.removeWhere(
        (entry) => entry.title == task.title && entry.dateKey == removeDateKey,
      );
    }
    setState(() {
      _dailyTodos = _orderedDailyTodos(
        _dailyTodos
            .map((t) => t.id == task.id ? updated : t)
            .toList(growable: false),
      );
      _dailyTodoLog = nextLog;
    });
    await _persistDailyTodos();
  }

  Future<void> _deleteDailyTodo(DailyTodoTask task) async {
    setState(() {
      _dailyTodos =
          _dailyTodos.where((t) => t.id != task.id).toList(growable: false);
    });
    await _persistDailyTodos();
  }

  /// 現在のタスク・完遂ログから細木数子AI/UI用の要約を算出する。
  DailyTodoDigest _currentDailyTodoDigest() {
    return DailyTodoDigest.fromState(
      tasks: _dailyTodos,
      log: _dailyTodoLog,
      now: _now,
    );
  }

  // 「今日やること」カード。やらずに寝たタスクは翌日の借金、という思想を
  // 繰り越し日数で可視化し、こなした実績は細木数子AIの行動アドバイス材料にする。
  Widget _buildDailyTodoCard() {
    final digest = _currentDailyTodoDigest();
    final today = DateTime(_now.year, _now.month, _now.day);
    return Card(
      elevation: 2,
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Row(
              children: [
                Icon(Icons.event_available, color: Color(0xFF4F46E5)),
                SizedBox(width: 8),
                Expanded(
                  child: Text(
                    '今日やること',
                    style: TextStyle(
                      fontSize: 18,
                      fontWeight: FontWeight.bold,
                      height: 1.4,
                    ),
                  ),
                ),
              ],
            ),
            const Text(
              'やらずに寝たタスクは、明日への借金。今日のうちにチェックを入れて片づけよ。'
              '日々こなした実績は細木数子AIの行動アドバイスに使われる。',
              style: TextStyle(
                fontSize: 11,
                color: Color(0xFF9CA3AF),
                height: 1.5,
              ),
            ),
            const SizedBox(height: 12),
            _buildDailyTodoSummaryChips(digest),
            const SizedBox(height: 8),
            if (_isLoadingDailyTodos)
              const Padding(
                padding: EdgeInsets.all(16),
                child: Center(child: CircularProgressIndicator()),
              )
            else if (_dailyTodos.isEmpty)
              const Padding(
                padding: EdgeInsets.symmetric(vertical: 16),
                child: Text(
                  'まだ登録がありません。まず今日やることを1つ登録して、'
                  'やり切ってから寝ましょう。',
                  style: TextStyle(color: Color(0xFF9CA3AF), height: 1.5),
                ),
              )
            else
              ListView.builder(
                shrinkWrap: true,
                physics: const NeverScrollableScrollPhysics(),
                itemCount: _dailyTodos.length,
                itemBuilder: (context, index) =>
                    _buildDailyTodoRow(_dailyTodos[index], today),
              ),
            TextButton.icon(
              onPressed: _addDailyTodo,
              icon: const Icon(Icons.add),
              label: const Text('今日やることを追加'),
              style: TextButton.styleFrom(
                foregroundColor: const Color(0xFF4F46E5),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildDailyTodoSummaryChips(DailyTodoDigest digest) {
    Widget chip(String label, Color color) {
      return Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
        decoration: BoxDecoration(
          color: color.withValues(alpha: 0.12),
          borderRadius: BorderRadius.circular(8),
          border: Border.all(color: color.withValues(alpha: 0.4)),
        ),
        child: Text(
          label,
          style: TextStyle(
            fontSize: 11,
            fontWeight: FontWeight.w600,
            color: color,
            height: 1.4,
          ),
        ),
      );
    }

    return Wrap(
      spacing: 8,
      runSpacing: 8,
      children: [
        chip(
          '本日 ${digest.todayCompleted}/${digest.todayTotal} 完了',
          const Color(0xFF0D9488),
        ),
        if (digest.carriedOverCount > 0)
          chip(
            '繰り越し(借金) ${digest.carriedOverCount}件・最長${digest.maxCarryOverDays}日',
            const Color(0xFFB91C1C),
          )
        else
          chip('繰り越しの借金なし', const Color(0xFF0D9488)),
        if (digest.activeStreakDays > 0)
          chip('連続${digest.activeStreakDays}日実行中', const Color(0xFFFF6B35)),
        chip('直近7日 ${digest.completedLast7Days}件完了', const Color(0xFF4F46E5)),
      ],
    );
  }

  Widget _buildDailyTodoRow(DailyTodoTask task, DateTime today) {
    final isCarriedOver = task.isCarriedOverAsOf(today);
    final carryDays = task.carryOverDaysAsOf(today);
    final String subtitle;
    final Color subtitleColor;
    if (task.completed) {
      final at = task.completedAt;
      subtitle = at == null
          ? '完了'
          : '完了: ${DateFormat('M/d HH:mm').format(at.toLocal())}';
      subtitleColor = const Color(0xFF0D9488);
    } else if (isCarriedOver) {
      subtitle = '$carryDays日前から繰り越し(借金) '
          '・予定日 ${DateFormat('M/d').format(task.plannedDate)}';
      subtitleColor = const Color(0xFFB91C1C);
    } else if (task.isForToday(today)) {
      subtitle = '今日やること';
      subtitleColor = const Color(0xFF9CA3AF);
    } else {
      subtitle = '予定日 ${DateFormat('yyyy/M/d').format(task.plannedDate)}';
      subtitleColor = const Color(0xFF9CA3AF);
    }
    return CheckboxListTile(
      value: task.completed,
      onChanged: (value) => _toggleDailyTodo(task, value ?? false),
      title: Text(
        task.title,
        style: TextStyle(
          decoration: task.completed ? TextDecoration.lineThrough : null,
          height: 1.5,
          fontWeight: isCarriedOver ? FontWeight.w600 : FontWeight.normal,
        ),
      ),
      subtitle: Text(
        subtitle,
        style: TextStyle(color: subtitleColor, fontSize: 12, height: 1.5),
      ),
      secondary: IconButton(
        icon: const Icon(Icons.delete_outline, size: 20),
        color: const Color(0xFF9CA3AF),
        tooltip: '削除',
        onPressed: () => _deleteDailyTodo(task),
      ),
      controlAffinity: ListTileControlAffinity.leading,
      contentPadding: EdgeInsets.zero,
      dense: true,
    );
  }

  Future<void> _fetchMustTasks() async {
    setState(() => _isLoadingTasks = true);
    try {
      final userId = _supabase.auth.currentUser?.id;
      if (userId == null) return;
      final data = await _supabase
          .from('must_tasks')
          .select()
          .eq('user_id', userId)
          .order('deadline', ascending: true);

      if (mounted) {
        setState(() {
          _mustTasks = List<Map<String, dynamic>>.from(data);
          _isLoadingTasks = false;
        });
      }
    } catch (e) {
      if (mounted) {
        setState(() {
          _mustTasks = [];
          _isLoadingTasks = false;
        });
      }
    }
  }

  Future<void> _addMustTask() async {
    final titleController = TextEditingController();
    DateTime selectedDeadline = DateTime.now();

    await showDialog(
      context: context,
      builder: (context) => StatefulBuilder(
        builder: (context, setDialogState) {
          return AlertDialog(
            title: const Text('必須タスクを追加'),
            content: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(
                  controller: titleController,
                  decoration: const InputDecoration(
                    labelText: 'タスク内容 (例: 確定申告)',
                  ),
                ),
                const SizedBox(height: 16),
                InkWell(
                  onTap: () async {
                    final date = await showDatePicker(
                      context: context,
                      initialDate: selectedDeadline,
                      firstDate: DateTime.now(),
                      lastDate: DateTime(2030),
                    );
                    if (date != null) {
                      setDialogState(() => selectedDeadline = date);
                    }
                  },
                  child: Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 12,
                      vertical: 12,
                    ),
                    decoration: BoxDecoration(
                      border: Border.all(
                        color: Theme.of(context).colorScheme.onSurfaceVariant,
                      ),
                      borderRadius: BorderRadius.circular(4),
                    ),
                    child: Row(
                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      children: [
                        Text(
                          '締切: ${DateFormat('yyyy/MM/dd').format(selectedDeadline)}',
                        ),
                        Icon(
                          Icons.calendar_today,
                          size: 16,
                          color: Theme.of(context).colorScheme.onSurfaceVariant,
                        ),
                      ],
                    ),
                  ),
                ),
              ],
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(context),
                child: const Text('キャンセル'),
              ),
              ElevatedButton(
                onPressed: () async {
                  final title = titleController.text.trim();
                  if (title.isEmpty) return;
                  final userId = _supabase.auth.currentUser?.id;
                  if (userId != null) {
                    try {
                      await _supabase.from('must_tasks').insert({
                        'user_id': userId,
                        'title': title,
                        'deadline': selectedDeadline.toUtc().toIso8601String(),
                        'is_completed': false,
                      });
                      if (context.mounted) Navigator.pop(context);
                      _fetchMustTasks();
                    } catch (e) {
                      debugPrint('Error adding task: $e');
                      setState(() {
                        _mustTasks.add({
                          'id': 'temp_${DateTime.now().millisecondsSinceEpoch}',
                          'title': title,
                          'deadline':
                              selectedDeadline.toUtc().toIso8601String(),
                          'is_completed': false,
                        });
                      });
                      if (context.mounted) Navigator.pop(context);
                    }
                  }
                },
                child: const Text('追加'),
              ),
            ],
          );
        },
      ),
    );
    await _fetchTodayClosing();
  }

  Future<void> _toggleTaskStatus(String id, bool currentStatus) async {
    try {
      await _supabase
          .from('must_tasks')
          .update({'is_completed': !currentStatus}).eq('id', id);
      _fetchMustTasks();
    } catch (e) {
      if (!mounted) return;
      setState(() {
        final index = _mustTasks.indexWhere((t) => t['id'] == id);
        if (index != -1) _mustTasks[index]['is_completed'] = !currentStatus;
      });
    }
    await _fetchTodayClosing();
  }

  Future<void> _editSubscriptionDueDate(Map<String, dynamic> item) async {
    final String id = item['id']?.toString() ?? '';
    if (id.isEmpty) return;

    // due_date は "YYYY-MM-DD" が来る想定
    final dueStr = item['due_date'] as String?;
    DateTime initial = DateTime.now();
    if (dueStr != null && dueStr.isNotEmpty) {
      final parsed = DateTime.tryParse(dueStr);
      if (parsed != null) {
        // 日付だけに丸める（タイムゾーン事故防止）
        initial = DateTime(parsed.year, parsed.month, parsed.day);
      }
    }

    final picked = await showDatePicker(
      context: context,
      initialDate: initial,
      firstDate: DateTime(DateTime.now().year - 1, 1, 1),
      lastDate: DateTime(DateTime.now().year + 5, 12, 31),
    );

    if (picked == null) return;

    final dueDateStr = DateFormat('yyyy-MM-dd').format(picked);

    try {
      await _supabase
          .from('subscriptions')
          .update({'due_date': dueDateStr}).eq('id', id);

      await _fetchSubscriptions();
      await _fetchTodayClosing();

      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('支払日を更新しました: $dueDateStr')));
    } catch (e) {
      debugPrint('edit due_date error: $e');
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('支払日の更新に失敗: $e'),
          backgroundColor: const Color(0xFFB91C1C),
        ),
      );
    }
  }

  Future<void> _editSubscriptionPaymentSource(Map<String, dynamic> item) async {
    final id = item['id']?.toString() ?? '';
    if (id.isEmpty) return;

    final candidates = _paymentSourceCandidates();

    final current = (item['payment_source']?.toString() ?? '').trim();
    String selected = current.isEmpty
        ? '（未設定）'
        : (candidates.contains(current) ? current : 'その他');

    final custom = TextEditingController(
      text: selected == 'その他' ? current : '',
    );

    final ok = await showDialog<bool>(
      context: context,
      builder: (context) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          title: const Text('引落先を編集'),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              DropdownButtonFormField<String>(
                initialValue: selected,
                decoration: const InputDecoration(
                  labelText: '引落先（資産・負債から選択）',
                  border: OutlineInputBorder(),
                  isDense: true,
                ),
                items: candidates
                    .map((s) => DropdownMenuItem(value: s, child: Text(s)))
                    .toList(),
                onChanged: (v) {
                  if (v == null) return;
                  setDialogState(() => selected = v);
                },
              ),
              const SizedBox(height: 8),
              if (selected == 'その他')
                TextField(
                  controller: custom,
                  decoration: const InputDecoration(
                    labelText: '引落先（自由入力）',
                    border: OutlineInputBorder(),
                    isDense: true,
                  ),
                ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context, false),
              child: const Text('キャンセル'),
            ),
            ElevatedButton(
              onPressed: () => Navigator.pop(context, true),
              child: const Text('保存'),
            ),
          ],
        ),
      ),
    );

    if (ok != true) {
      custom.dispose();
      return;
    }

    final sourceText = selected == '（未設定）'
        ? null
        : (selected == 'その他' ? custom.text.trim() : selected);

    custom.dispose();

    try {
      await _supabase.from('subscriptions').update({
        'payment_source':
            (sourceText == null || sourceText.isEmpty) ? null : sourceText,
      }).eq('id', id);

      await _fetchSubscriptions();
      await _fetchTodayClosing();
    } catch (e) {
      debugPrint('edit payment_source error: $e');
    }
  }

  // ==========================================
  // グラフ描画ロジック
  // ==========================================
  void _updateChartData() {
    // NOTE: Builds UI-only complemented snapshots for charts/tooltips.
    // Never mutate _assetData here; it is the source of truth persisted to Supabase.
    _sortedDates = _assetData.keys.toList()..sort();
    _effectiveAssetDataByDate = {};
    if (_sortedDates.isEmpty) {
      _lineChartBars = [];
      _barChartGroups = [];
      return;
    }
    final Map<String, List<FlSpot>> spotsData = {
      for (var type in _assetTypes) type: [],
    };
    final lastKnownValues = <String, double>{
      for (var type in _assetTypes) type: 0,
    };
    final initializedTypes = <String>{};
    final dailyTotals = <double>[];

    for (int i = 0; i < _sortedDates.length; i++) {
      final String date = _sortedDates[i];
      final rawOnDate = _assetData[date] ?? const <String, double>{};
      final snapshotOnDate = <String, double>{};
      double currentDayTotal = 0;
      double cumulativeValue = 0;

      for (var type in _assetTypes) {
        if (rawOnDate.containsKey(type)) {
          lastKnownValues[type] = rawOnDate[type]!;
          initializedTypes.add(type);
        }
        final double value = initializedTypes.contains(type)
            ? (lastKnownValues[type] ?? 0.0)
            : 0.0;
        snapshotOnDate[type] = value;
        currentDayTotal += value;
        if (_isStacked) {
          cumulativeValue += value;
          spotsData[type]!.add(FlSpot(i.toDouble(), cumulativeValue));
        } else {
          spotsData[type]!.add(FlSpot(i.toDouble(), value));
        }
      }
      _effectiveAssetDataByDate[date] = snapshotOnDate;
      dailyTotals.add(currentDayTotal);
    }

    _lineChartBars = _assetTypes
        .asMap()
        .entries
        .map((entry) {
          final index = entry.key;
          final type = entry.value;
          final color = _colors[index % _colors.length];
          final spots = spotsData[type] ?? [];
          if (spots.isEmpty) return null;
          return LineChartBarData(
            spots: spots,
            isCurved: false,
            color: color,
            barWidth: 2,
            isStrokeCapRound: true,
            dotData: const FlDotData(show: false),
            belowBarData: BarAreaData(
              show: _isStacked,
              color: color.withValues(alpha: 0.5),
            ),
          );
        })
        .whereType<LineChartBarData>()
        .toList();

    if (_isStacked) _lineChartBars = _lineChartBars.reversed.toList();

    _barChartGroups = [];
    _maxDailyChange = 0;
    for (int i = 0; i < dailyTotals.length; i++) {
      double diff = 0;
      if (i > 0) diff = dailyTotals[i] - dailyTotals[i - 1];
      if (diff.abs() > _maxDailyChange) _maxDailyChange = diff.abs();
      final color =
          diff >= 0 ? const Color(0xFF0D9488) : const Color(0xFFB91C1C);
      _barChartGroups.add(
        BarChartGroupData(
          x: i,
          barRods: [
            BarChartRodData(
              toY: diff,
              color: color,
              width: 12,
              borderRadius: const BorderRadius.only(
                topLeft: Radius.circular(4),
                topRight: Radius.circular(4),
              ),
            ),
          ],
        ),
      );
    }
    if (_maxDailyChange == 0) _maxDailyChange = 1000;
    _maxDailyChange *= 1.2;
  }

  // ==========================================
  // UI構築 (エラーが起きていた箇所)
  // ==========================================
  AssetLiabilityWorkbook? _buildCurrentAssetLiabilityWorkbook() {
    final latestSnapshot = _latestSnapshotForDisplay();
    if (latestSnapshot.isEmpty) {
      return null;
    }

    return _assetLiabilityPlanner.buildWorkbook(
      latestSnapshot: latestSnapshot,
      baseDate: _now,
      monthlyPaymentOverrides: _monthlyPaymentOverrides,
      actualPaymentAmounts: _actualPaymentAmounts,
      paymentDifferenceReasons: _paymentDifferenceReasons,
      annualRateOverrides: _annualRateOverrides,
      paymentDayOverrides: _debtPaymentDayOverrides,
      paidAccountNames: _monthlyPaidAccountNames,
      billingConfirmedAccountIds: _billingConfirmedAccountIds,
      paymentSourceAccountIds: _paymentSourceAccountIds,
      defaultPaymentSourceAccountIds: _defaultPaymentSourceAccountIds,
      defaultCardBillingAccountIds: _defaultCardBillingAccountIds,
      cardBillingAccountIds: _cardBillingAccountIds,
      revolvingConfigs: _revolvingConfigs,
      cardUsagePolicies: _cardUsagePolicies,
      incomePlans: _monthlyIncomePlans,
      cardStatementLines: _cardStatementLines,
      transferTasks: _transferTasks,
      recurringFixedCosts: _recurringFixedCosts,
      includeDefaultFixedPayments: true,
      salaryDay: _salaryDay,
    );
  }

  /// 全体の同期ステータス バナー。未同期 (= この端末のみ) を可視化する。
  /// タップで未同期データの一覧ダイアログを開く。
  Widget _buildSyncStatusBanner() {
    final summary = _syncSummary;
    const warnBg = Color(0xFFFEF3C7);
    const warnFg = Color(0xFF92400E);
    const okBg = Color(0xFFDCFCE7);
    const okFg = Color(0xFF166534);

    late final Color background;
    late final Color foreground;
    late final IconData icon;
    late final String text;
    switch (summary.level) {
      case AssetSyncLevel.loggedOut:
        background = warnBg;
        foreground = warnFg;
        icon = Icons.cloud_off;
        text = '未ログイン：データはこの端末にのみ保存（他端末に出ません）';
      case AssetSyncLevel.partialLocal:
        background = warnBg;
        foreground = warnFg;
        icon = Icons.sync_problem;
        text = '未同期 ${summary.localOnlyCount} 項目（この端末のみ）';
      case AssetSyncLevel.allSynced:
        background = okBg;
        foreground = okFg;
        icon = Icons.cloud_done;
        text = 'サーバ同期済み';
    }
    final tappable = summary.level != AssetSyncLevel.allSynced;
    return InkWell(
      key: const Key('asset_sync_status_chip'),
      onTap: tappable ? _showSyncStatusDetails : null,
      borderRadius: BorderRadius.circular(10),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
        decoration: BoxDecoration(
          color: background,
          borderRadius: BorderRadius.circular(10),
          border: Border.all(color: foreground),
        ),
        child: Row(
          children: [
            Icon(icon, size: 18, color: foreground),
            const SizedBox(width: 8),
            Expanded(
              child: Text(
                text,
                style: TextStyle(
                  color: foreground,
                  fontSize: 12.5,
                  height: 1.3,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ),
            if (tappable)
              Icon(Icons.chevron_right, size: 18, color: foreground),
          ],
        ),
      ),
    );
  }

  /// 未同期データ領域を示すバッジ列。localOnly の領域ごとに「<領域> 未同期」チップを
  /// バナー直下に並べ、どのデータが他端末に出ないかを一目で分かるようにする。
  Widget _buildUnsyncedBadgeRow() {
    final domains = _syncSummary.localOnlyDomains;
    if (domains.isEmpty) {
      return const SizedBox.shrink();
    }
    return Padding(
      key: const Key('asset_unsynced_badge_row'),
      padding: const EdgeInsets.only(top: 8),
      child: Wrap(
        spacing: 6,
        runSpacing: 6,
        children: <Widget>[
          for (final domain in domains) _buildUnsyncedBadge(domain),
        ],
      ),
    );
  }

