  bool _isSectionShown(AssetManagementSectionId section) {
    final override = _sectionOverrides[section] ??
        AssetManagementSectionVisibilityOverride.auto;
    return AssetManagementDisplayModeStore.isSectionVisible(
      section: section,
      mode: _displayMode,
      override: override,
    );
  }

  /// 月次資産ダッシュボード内の個別パネルの可視性。
  ///
  /// 親セクション [AssetManagementSectionId.monthlyDashboard] のゲートを既に
  /// 通った後に呼ぶので、`auto` は「親の判断に従う」= 表示のままとし、ユーザーが
  /// 明示した「隠す」「常に表示」だけを反映する。[_isSectionShown] をそのまま
  /// 使うと、子パネルも親と同じ full tier のため、親を「常に表示」に固定した
  /// 標準モードで子が全部消えてしまう。
  bool _isDashboardPanelShown(AssetManagementSectionId section) {
    final override = _sectionOverrides[section] ??
        AssetManagementSectionVisibilityOverride.auto;
    return override != AssetManagementSectionVisibilityOverride.hidden;
  }

  /// メイン口座IDの集約ミラー pref_key (1 行 jsonb / MIRROR_PREF_SCHEMA.md)。
  static const String _mainAccountMirrorKey = 'main_account_id';

  Future<void> _loadMainAccount() async {
    try {
      final id = await _mainAccountStore.load();
      if (mounted && id != _assetManagementMainAccountId) {
        setState(() {
          _assetManagementMainAccountId = id;
        });
      }
    } catch (e) {
      debugPrint('Error loading main account: $e');
    }
    // ローカル読込後にサーバ集約ミラーから復元する (端末間同期 / 集約優先)。
    await _restoreMainAccountFromMirror();
    unawaited(_refreshSyncSources());
  }

  /// 給料日(月次サイクル基準日)を起動時にローカルから読み、サーバミラーで上書きする。
  Future<void> _loadSalaryDay() async {
    try {
      final results = await Future.wait<Object>([
        _salaryDayStore.load(),
        _salaryDayStore.isConfigured(),
      ]);
      final day = results[0] as int;
      final configured = results[1] as bool;
      if (mounted &&
          (day != _salaryDay || configured != _salaryDayConfigured)) {
        setState(() {
          _salaryDay = day;
          _salaryDayConfigured = configured;
        });
      }
    } catch (e) {
      debugPrint('Error loading salary day: $e');
    }
    await _restoreSalaryDayFromMirror();
  }

  /// サーバミラー (pref_key: salary_day) があれば採用する(設定は稀更新 +
  /// AI 計算へは毎回 payload で渡すため scalar は集約優先で実害小)。
  Future<void> _restoreSalaryDayFromMirror() async {
    if (_supabase.auth.currentUser == null) {
      return;
    }
    try {
      final rows = await _bootSelectPrefMirror(_salaryDayMirrorKey);
      if (rows.isEmpty) {
        return;
      }
      final restored = AssetSalaryDayStore.decodeMirrorValue(
        rows.first['value'],
      );
      if (!mounted) {
        return;
      }
      final changed = restored != _salaryDay || !_salaryDayConfigured;
      if (changed) {
        setState(() {
          _salaryDay = restored;
          _salaryDayConfigured = true;
        });
      }
      _persistInBackground(
        _salaryDayStore.save(restored),
        'salary day restore save',
      );
      // サイクル基準が変わったときだけ月次stateを読み直す。ミラー値が現在値と
      // 同じなら同一サイクル月の同一データで、起動毎に7往復のフルバッチが余分に
      // 走るだけだった (兄弟の _restoreSalaryAmountFromMirror は同値なら早期
      // return しており、そちらに揃える)。
    } catch (e) {
      debugPrint('salary day mirror restore failed: $e');
    }
  }

  /// 給料日を `asset_pref_mirror` (pref_key: salary_day) へ 1 行 upsert する。
  Future<void> _mirrorSalaryDay() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      return;
    }
    try {
      await _supabase.from('asset_pref_mirror').upsert(<String, dynamic>{
        'user_id': userId,
        'pref_key': _salaryDayMirrorKey,
        'value': AssetSalaryDayStore.encodeMirrorValue(_salaryDay),
        'updated_at': DateTime.now().toUtc().toIso8601String(),
      });
    } catch (e) {
      debugPrint('salary day mirror upsert failed: $e');
    }
  }

  /// 想定給料額を起動時にローカルから読み、サーバミラーで上書きする。
  Future<void> _loadSalaryAmount() async {
    try {
      final amount = await _salaryAmountStore.load();
      if (mounted && amount != _salaryAmount) {
        setState(() => _salaryAmount = amount);
      }
    } catch (e) {
      debugPrint('Error loading salary amount: $e');
    }
    await _restoreSalaryAmountFromMirror();
  }

  /// サーバミラー (pref_key: salary_amount) があれば採用する(設定は稀更新 +
  /// AI 計算へは毎回 payload で渡すため scalar は集約優先で実害小)。
  Future<void> _restoreSalaryAmountFromMirror() async {
    if (_supabase.auth.currentUser == null) {
      return;
    }
    try {
      final rows = await _bootSelectPrefMirror(_salaryAmountMirrorKey);
      if (rows.isEmpty) {
        return;
      }
      final restored = AssetSalaryAmountStore.decodeMirrorValue(
        rows.first['value'],
      );
      if (!mounted || restored == _salaryAmount) {
        return;
      }
      setState(() => _salaryAmount = restored);
      _persistInBackground(
        _salaryAmountStore.save(restored),
        'salary amount restore save',
      );
    } catch (e) {
      debugPrint('salary amount mirror restore failed: $e');
    }
  }

  /// 想定給料額を `asset_pref_mirror` (pref_key: salary_amount) へ 1 行 upsert する。
  /// 未登録 (null) のときは upsert しない(削除は稀なので明示クリア時のみ反映)。
  Future<void> _mirrorSalaryAmount() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      return;
    }
    final amount = _salaryAmount;
    if (amount == null) {
      return;
    }
    try {
      await _supabase.from('asset_pref_mirror').upsert(<String, dynamic>{
        'user_id': userId,
        'pref_key': _salaryAmountMirrorKey,
        'value': AssetSalaryAmountStore.encodeMirrorValue(amount),
        'updated_at': DateTime.now().toUtc().toIso8601String(),
      });
    } catch (e) {
      debugPrint('salary amount mirror upsert failed: $e');
    }
  }

  /// 給料リセット承認マーカーをローカル + サーバミラーから読み込む。初回(未設定)は
  /// 当日サイクルを承認済みにして、以後のサイクル遷移だけを gating 対象にする
  /// (機能投入直後にいきなり前サイクルへ退避させない)。
  Future<void> _loadSalaryResetMarker() async {
    try {
      final stored = await _salaryResetMarkerStore.load();
      if (mounted && stored != _ackedResetCycleKey) {
        setState(() => _ackedResetCycleKey = stored);
      } else {
        _ackedResetCycleKey = stored;
      }
    } catch (e) {
      debugPrint('Error loading salary reset marker: $e');
    }
    await _restoreSalaryResetMarkerFromMirror();
    if (_ackedResetCycleKey == null) {
      await _acknowledgeSalaryReset(
        _currentSalaryCycleKey(),
        reloadMonthlyState: false,
      );
    }
  }

  /// サーバミラー (pref_key: salary_reset_ack_cycle) を max-merge で採用する。
  /// 古い端末がマーカーを巻き戻さないよう、常に新しいサイクルキーを優先する。
  Future<void> _restoreSalaryResetMarkerFromMirror() async {
    if (_supabase.auth.currentUser == null) {
      return;
    }
    try {
      final rows = await _supabase
          .from('asset_pref_mirror')
          .select()
          .eq('pref_key', _salaryResetMarkerMirrorKey);
      if (rows.isEmpty) {
        return;
      }
      final restored = AssetSalaryResetMarkerStore.decodeMirrorValue(
        rows.first['value'],
      );
      final merged = AssetSalaryResetMarkerStore.mergeLater(
        _ackedResetCycleKey,
        restored,
      );
      if (!mounted || merged == _ackedResetCycleKey) {
        return;
      }
      setState(() => _ackedResetCycleKey = merged);
      _persistInBackground(
        _salaryResetMarkerStore.save(merged),
        'salary reset marker restore save',
      );
    } catch (e) {
      debugPrint('salary reset marker mirror restore failed: $e');
    }
  }

  /// 給料リセット承認マーカーを `asset_pref_mirror` へ 1 行 upsert する。
  Future<void> _mirrorSalaryResetMarker() async {
    final userId = _supabase.auth.currentUser?.id;
    final marker = _ackedResetCycleKey;
    if (userId == null || marker == null) {
      return;
    }
    try {
      await _supabase.from('asset_pref_mirror').upsert(<String, dynamic>{
        'user_id': userId,
        'pref_key': _salaryResetMarkerMirrorKey,
        'value': AssetSalaryResetMarkerStore.encodeMirrorValue(marker),
        'updated_at': DateTime.now().toUtc().toIso8601String(),
      });
    } catch (e) {
      debugPrint('salary reset marker mirror upsert failed: $e');
    }
  }

  /// 指定サイクルまでリセットを承認(=新サイクルへ切替)する。max-merge で前進のみ。
  /// 前進したら永続化 + ミラー + (必要なら)月次state再読込で支払済みチェックを
  /// 新サイクル(通常は空)へ切り替える。
  Future<void> _acknowledgeSalaryReset(
    String cycleKey, {
    bool reloadMonthlyState = true,
  }) async {
    final merged = AssetSalaryResetMarkerStore.mergeLater(
      _ackedResetCycleKey,
      cycleKey,
    );
    if (merged == _ackedResetCycleKey) {
      return;
    }
    if (mounted) {
      setState(() => _ackedResetCycleKey = merged);
    } else {
      _ackedResetCycleKey = merged;
    }
    _persistInBackground(
      _salaryResetMarkerStore.save(merged),
      'salary reset marker save',
    );
    unawaited(_mirrorSalaryResetMarker());
    if (reloadMonthlyState) {
      await _loadAssetLiabilityMonthlyState();
    }
  }

  /// 当日サイクルが未承認のときだけ給料振込を検知し、検知できたらリセットを承認する。
  /// build からではなくイベント(月次stateロード後 / フロー取得後 / 残高更新後 / 1秒
  /// タイマー)から呼ぶ。未承認でない通常時はワークブックも作らず即 return(軽量)。
  /// 冪等(承認後はマーカー一致でこの分岐に入らない / `_pendingSalaryResetAck` で多重防止)。
  void _maybeDetectSalaryDeposit() {
    if (!_salaryResetPending) {
      return;
    }
    final currentCycleKey = _currentSalaryCycleKey();
    if (_pendingSalaryResetAck == currentCycleKey) {
      return;
    }
    final workbook = _buildCurrentAssetLiabilityWorkbook();
    if (workbook == null) {
      return;
    }
    final detection = _computeSalaryDepositDetection(workbook);
    if (!detection.detected) {
      return;
    }
    _pendingSalaryResetAck = currentCycleKey;
    unawaited(
      _acknowledgeSalaryReset(currentCycleKey).whenComplete(() {
        _pendingSalaryResetAck = null;
      }),
    );
  }

  /// 現サイクルにメインバンクへの給料振込があったかを推定する。
  SalaryDepositDetection _computeSalaryDepositDetection(
    AssetLiabilityWorkbook workbook,
  ) {
    final incomeFlows = <SalaryDepositFlowObservation>[
      for (final flow in _flowsForCycle(_now))
        if (_isIncomeActionType(flow['action_type']?.toString() ?? ''))
          SalaryDepositFlowObservation(
            amount: ((flow['amount'] as num?)?.toDouble() ?? 0).abs(),
            occurredAt: DateTime.tryParse(
                  flow['occurred_at']?.toString() ?? '',
                )?.toLocal() ??
                _now,
          ),
    ];
    return AssetSalaryDepositDetector.detect(
      cycleIncomeFlows: incomeFlows,
      balances: _mainAccountBalanceWindow(workbook),
      expectedSalaryAmount: _registeredSalaryAmount(),
    );
  }

  /// メインバンク口座の「前サイクル末 → 現在」の残高窓。残高更新だけでは入金フローが
  /// 生成されないため(残高ドロップ時のみ自動記録)、給料反映の検知はこの残高増に依る。
  MainAccountBalanceWindow _mainAccountBalanceWindow(
    AssetLiabilityWorkbook workbook,
  ) {
    final mainAccount = _resolveMainAccountForDetection(workbook);
    if (mainAccount == null) {
      return MainAccountBalanceWindow.unknown;
    }
    final cycleStart = AssetLiabilityMonthlyStateStore.salaryCycleStart(
      _now,
      salaryDay: _salaryDay,
    );
    return MainAccountBalanceWindow(
      previousCycleEndBalance: _historicalAccountBalanceBefore(
        mainAccount.name,
        cycleStart,
      ),
      currentBalance: mainAccount.balance,
    );
  }

  /// メインバンク = メイン口座指定があればそれ、無ければ残高最大の非現金資産口座。
  /// `_buildMainAccountSelector` と同じ候補ロジック。
  AssetLiabilityAccount? _resolveMainAccountForDetection(
    AssetLiabilityWorkbook workbook,
  ) {
    final candidates = workbook.accounts
        .where(
          (account) =>
              account.kind != AssetLiabilityAccountKind.cash && account.isAsset,
        )
        .toList()
      ..sort((a, b) => b.balance.compareTo(a.balance));
    if (candidates.isEmpty) {
      return null;
    }
    for (final account in candidates) {
      if (account.id == _assetManagementMainAccountId) {
        return account;
      }
    }
    return candidates.first;
  }

  /// `_assetData` ({yyyy-MM-dd: {口座名: 残高}}) から [asOf] より厳密に前で最も新しい
  /// 日付の残高を返す(= 前サイクル末時点の残高)。記録が無ければ null。
  double? _historicalAccountBalanceBefore(String accountName, DateTime asOf) {
    final asOfKey = _dateOnly(asOf);
    String? bestKey;
    for (final entry in _assetData.entries) {
      if (!entry.value.containsKey(accountName)) {
        continue;
      }
      if (entry.key.compareTo(asOfKey) >= 0) {
        continue;
      }
      if (bestKey == null || entry.key.compareTo(bestKey) > 0) {
        bestKey = entry.key;
      }
    }
    return bestKey == null ? null : _assetData[bestKey]![accountName];
  }

  /// 自動検知に使う登録給料額。明示登録された想定給料額を最優先し、無ければ
  /// 繰り返し入金ルール / 収入予定の最大額で推定する。いずれも無ければ null
  /// (= ヒューリスティック検知へフォールバック)。
  double? _registeredSalaryAmount() {
    // 明示登録された想定給料額があれば最優先(検知精度が最も高い)。
    final explicit = _salaryAmount;
    if (explicit != null && explicit > 0) {
      return explicit;
    }
    var maxAmount = 0.0;
    for (final rule in _expectedInflowRules) {
      if (rule.amount > maxAmount) {
        maxAmount = rule.amount;
      }
    }
    for (final plan in _monthlyIncomePlans) {
      if (plan.amount > maxAmount) {
        maxAmount = plan.amount;
      }
    }
    return maxAmount > 0 ? maxAmount : null;
  }

  /// 手動で「給料を受け取った」=支払済みチェックを新サイクルへリセットする。
  Future<void> _confirmManualSalaryReset() async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('給料を受け取った'),
        content: const Text(
          '支払済みチェックを新しい給料サイクルへリセットします。'
          '前サイクルのチェックは消えます。よろしいですか?',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(false),
            child: const Text('キャンセル'),
          ),
          FilledButton(
            onPressed: () => Navigator.of(dialogContext).pop(true),
            child: const Text('リセット'),
          ),
        ],
      ),
    );
    if (confirmed != true || !mounted) {
      return;
    }
    await _acknowledgeSalaryReset(_currentSalaryCycleKey());
  }

  /// 給料日を更新して永続化 + ミラー + 月次state再読込(サイクル基準が変わる)。
  Future<void> _setSalaryDay(int day) async {
    final clamped = AssetSalaryDayStore.clampDay(day);
    if (clamped == _salaryDay && _salaryDayConfigured) {
      return;
    }
    setState(() {
      _salaryDay = clamped;
      _salaryDayConfigured = true;
    });
    _persistInBackground(_salaryDayStore.save(clamped), 'salary day save');
    unawaited(_mirrorSalaryDay());
    unawaited(_loadAssetLiabilityMonthlyState());
  }

  /// 給料日(月次サイクル基準日)を設定するダイアログ。
  Future<void> _showSalaryDayDialog() async {
    final controller = TextEditingController(text: _salaryDay.toString());
    await showDialog<void>(
      context: context,
      builder: (dialogContext) {
        String? errorText;
        return StatefulBuilder(
          builder: (context, setDialogState) {
            return AlertDialog(
              title: const Text('給料日(月次サイクル基準)'),
              content: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Text(
                    '資産管理は給料日から翌給料日の前日までを1サイクルとして集計します'
                    '(支払済みチェックは給料の振込を検知して新サイクルへ切り替え)。',
                    style: TextStyle(fontSize: 12, height: 1.5),
                  ),
                  const SizedBox(height: 12),
                  TextField(
                    controller: controller,
                    keyboardType: TextInputType.number,
                    inputFormatters: [FilteringTextInputFormatter.digitsOnly],
                    decoration: InputDecoration(
                      labelText: '給料日 (1〜28)',
                      errorText: errorText,
                    ),
                  ),
                  const SizedBox(height: 8),
                  const Text(
                    '※ 給料日を変えると当月の支払済みチェックが新しいサイクル基準で'
                    '読み直されます。',
                    style: TextStyle(fontSize: 11, height: 1.4),
                  ),
                ],
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.of(dialogContext).pop(),
                  child: const Text('キャンセル'),
                ),
                FilledButton(
                  onPressed: () {
                    final day = int.tryParse(controller.text.trim());
                    if (day == null ||
                        day < AssetSalaryDayStore.minSalaryDay ||
                        day > AssetSalaryDayStore.maxSalaryDay) {
                      setDialogState(() => errorText = '1〜28 の日付を入力してください');
                      return;
                    }
                    Navigator.of(dialogContext).pop();
                    unawaited(_setSalaryDay(day));
                  },
                  child: const Text('保存'),
                ),
              ],
            );
          },
        );
      },
    );
  }

  /// 想定給料額を更新して永続化 + ミラーする。null/0 以下はクリア(未登録)。
  Future<void> _setSalaryAmount(double? amount) async {
    final normalized = AssetSalaryAmountStore.normalize(amount);
    if (normalized == _salaryAmount) {
      return;
    }
    setState(() => _salaryAmount = normalized);
    _persistInBackground(
      _salaryAmountStore.save(normalized),
      'salary amount save',
    );
    unawaited(_mirrorSalaryAmount());
  }

  /// 想定給料額(自動検知の精度を上げる手取りの目安)を設定するダイアログ。
