  /// メイン口座IDを `asset_pref_mirror` (pref_key: main_account_id) へ
  /// 1 行 upsert する (リボ設定と同じ集約方針 / #3352)。
  Future<void> _mirrorMainAccount() async {
    unawaited(_syncTimestampStore.markChanged(_mainAccountMirrorKey));
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      return;
    }
    try {
      await _supabase.from('asset_pref_mirror').upsert(<String, dynamic>{
        'user_id': userId,
        'pref_key': _mainAccountMirrorKey,
        'value': AssetManagementMainAccountStore.encodeMirrorValue(
          _assetManagementMainAccountId,
        ),
        'updated_at': DateTime.now().toUtc().toIso8601String(),
      });
    } catch (e) {
      debugPrint('main account mirror upsert failed: $e');
    }
    unawaited(_refreshSyncSources());
  }

  /// サーバ集約ミラーからメイン口座IDを復元する (集約優先 + legacy local fallback)。
  /// ローカルに既に設定がある場合は上書きしない (オフライン編集を握り潰さない安全側)。
  Future<void> _restoreMainAccountFromMirror() async {
    final debugMirror = widget.debugMainAccountMirror;
    if (debugMirror == null && _supabase.auth.currentUser == null) {
      return;
    }
    final hasLocal = _assetManagementMainAccountId != null;
    // フラグ OFF + ローカル値あり: サーバに無ければ初回バックフィルして終了。
    if (!_mirrorReadsAuthoritative && hasLocal && debugMirror == null) {
      unawaited(
        _backfillPrefIfServerMissing(_mainAccountMirrorKey, _mirrorMainAccount),
      );
      return;
    }
    try {
      final dynamic value;
      final DateTime? mirrorUpdatedAt;
      if (debugMirror != null) {
        value = debugMirror;
        mirrorUpdatedAt = DateTime.now().toUtc();
      } else {
        final rows = await _bootSelectPrefMirror(_mainAccountMirrorKey);
        if (rows.isEmpty) {
          return;
        }
        value = rows.first['value'];
        mirrorUpdatedAt = DateTime.tryParse(
          rows.first['updated_at']?.toString() ?? '',
        );
      }
      final restored = AssetManagementMainAccountStore.decodeMirrorValue(value);
      if (restored == null || !mounted) {
        return;
      }
      final adopt = await _shouldAdoptMirror(
        prefKey: _mainAccountMirrorKey,
        hasLocal: hasLocal,
        mirrorUpdatedAt: mirrorUpdatedAt,
      );
      if (!adopt || !mounted) {
        return;
      }
      setState(() {
        _assetManagementMainAccountId = restored;
      });
      // オフライン参照用にローカルへ書き戻し、ローカル更新時刻をミラーへ揃える。
      _persistInBackground(
        _mainAccountStore.save(restored),
        'main account restore save',
      );
      _persistInBackground(
        _syncTimestampStore.markChanged(
          _mainAccountMirrorKey,
          at: mirrorUpdatedAt,
        ),
        'main account timestamp',
      );
    } catch (e) {
      debugPrint('main account mirror restore failed: $e');
    }
  }

  /// 各データ領域の同期出所を再計算する。サーバに該当データがあれば synced、
  /// ローカルのみなら localOnly、何も無ければ empty。未ログイン時は同期されない
  /// ため、データのある領域はすべて localOnly になる。
  ///
  /// 起動時の複数ロードや保存後から繰り返し呼ばれるため、再入は 1 回に集約する。
  Future<void> _refreshSyncSources() async {
    if (_syncRefreshInFlight) {
      _syncRefreshDirty = true;
      return;
    }
    _syncRefreshInFlight = true;
    try {
      final user = _supabase.auth.currentUser;
      final presentPrefKeys = <String>{};
      var hasInflowOnServer = false;
      if (user != null) {
        try {
          final boot = _bootPrefMirrorFuture;
          if (boot != null) {
            presentPrefKeys.addAll((await boot).keys);
          } else {
            final rows = await _supabase
                .from('asset_pref_mirror')
                .select('pref_key')
                .eq('user_id', user.id);
            for (final row in rows) {
              final key = row['pref_key'];
              if (key is String) {
                presentPrefKeys.add(key);
              }
            }
          }
        } catch (e) {
          debugPrint('sync sources: pref mirror fetch failed: $e');
        }
        try {
          final inflowRows = await _supabase
              .from('asset_expected_inflow_items')
              .select('id')
              .eq('user_id', user.id)
              .limit(1);
          hasInflowOnServer = inflowRows.isNotEmpty;
        } catch (e) {
          debugPrint('sync sources: inflow items fetch failed: $e');
        }
      }

      AssetSyncSource prefSource(String prefKey, {required bool hasLocal}) {
        if (user != null && presentPrefKeys.contains(prefKey)) {
          return AssetSyncSource.synced;
        }
        return hasLocal ? AssetSyncSource.localOnly : AssetSyncSource.empty;
      }

      final next = <AssetSyncDomain, AssetSyncSource>{
        AssetSyncDomain.mainAccount: prefSource(
          'main_account_id',
          hasLocal: _assetManagementMainAccountId != null,
        ),
        AssetSyncDomain.watchlist: prefSource(
          'watchlist_entries',
          hasLocal: _watchlistByType.isNotEmpty,
        ),
        AssetSyncDomain.revolving: prefSource(
          'revolving_credit_configs',
          hasLocal: _revolvingConfigs.isNotEmpty,
        ),
        AssetSyncDomain.debtOverrides: prefSource(
          'debt_payment_day_overrides',
          hasLocal: _debtPaymentDayOverrides.isNotEmpty,
        ),
        AssetSyncDomain.inflow: _inflowSyncSource(
          loggedIn: user != null,
          hasInflowOnServer: hasInflowOnServer,
        ),
        AssetSyncDomain.monthlyState: _monthlyStateSyncSource(
          loggedIn: user != null,
        ),
      };

      if (!mounted) {
        return;
      }
      setState(() {
        _syncSources
          ..clear()
          ..addAll(next);
      });
    } finally {
      _syncRefreshInFlight = false;
      if (_syncRefreshDirty) {
        _syncRefreshDirty = false;
        unawaited(_refreshSyncSources());
      }
    }
  }

  AssetSyncSource _inflowSyncSource({
    required bool loggedIn,
    required bool hasInflowOnServer,
  }) {
    final hasLocal =
        _expectedInflows.isNotEmpty || _expectedInflowRules.isNotEmpty;
    if (loggedIn && hasInflowOnServer) {
      return AssetSyncSource.synced;
    }
    return hasLocal ? AssetSyncSource.localOnly : AssetSyncSource.empty;
  }

  AssetSyncSource _monthlyStateSyncSource({required bool loggedIn}) {
    final hasLocal = !_currentAssetLiabilityMonthlyState().isEmpty;
    if (!hasLocal) {
      return AssetSyncSource.empty;
    }
    // リモート書込が無効 / 未ログイン / 直近同期が失敗ならローカルのみ。
    if (!loggedIn ||
        !_assetLiabilityRepository.supabaseWritesEnabled ||
        _assetLiabilitySyncStatus == AssetLiabilityManualSyncStatus.failure) {
      return AssetSyncSource.localOnly;
    }
    return AssetSyncSource.synced;
  }

  Future<void> _setMainAccount(String? accountId) async {
    setState(() {
      _assetManagementMainAccountId = accountId;
    });
    try {
      await _mainAccountStore.save(accountId);
    } catch (e) {
      debugPrint('Error saving main account: $e');
    }
    unawaited(_mirrorMainAccount());
  }

  /// リボ設定の集約ミラー pref_key (1 行 jsonb / MIRROR_PREF_SCHEMA.md)。
  static const String _revolvingConfigsMirrorKey = 'revolving_credit_configs';
  static const String _categoryBudgetsMirrorKey = 'category_budgets';

  Future<void> _loadCategoryBudgets() async {
    try {
      final budgets = await _categoryBudgetStore.load();
      if (mounted && budgets.isNotEmpty) {
        setState(() {
          _categoryBudgets = budgets;
        });
      }
    } catch (e) {
      debugPrint('Error loading category budgets: $e');
    }
    await _restoreCategoryBudgetsFromMirror();
  }

  /// カテゴリ別予算を `asset_pref_mirror` (pref_key: category_budgets) へ
  /// 1 行 upsert する (revolving_credit_configs と同じ集約方針 / 削除は空 map で表現)。
  Future<void> _mirrorCategoryBudgets() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      return;
    }
    try {
      await _supabase.from('asset_pref_mirror').upsert(<String, dynamic>{
        'user_id': userId,
        'pref_key': _categoryBudgetsMirrorKey,
        'value': AssetCategoryBudgetStore.encodeMirrorValue(_categoryBudgets),
        'updated_at': DateTime.now().toUtc().toIso8601String(),
      });
    } catch (e) {
      debugPrint('category budget mirror upsert failed: $e');
    }
  }

  /// サーバ集約ミラーからカテゴリ別予算を復元する。ローカルに既に設定がある場合は
  /// 上書きしない (オフライン編集を握り潰さない安全側)。サーバ行が無ければ初回
  /// バックフィルする。設定の有無は map のキー有無で表すため削除トゥームストーン不要。
  Future<void> _restoreCategoryBudgetsFromMirror() async {
    if (_supabase.auth.currentUser == null) {
      return;
    }
    final hasLocal = _categoryBudgets.isNotEmpty;
    try {
      final rows = await _bootSelectPrefMirror(_categoryBudgetsMirrorKey);
      if (rows.isEmpty) {
        if (hasLocal) {
          unawaited(_mirrorCategoryBudgets());
        }
        return;
      }
      if (hasLocal) {
        return;
      }
      final serverBudgets = AssetCategoryBudgetStore.decodeMirrorValue(
        rows.first['value'],
      );
      if (serverBudgets.isEmpty || !mounted) {
        return;
      }
      setState(() {
        _categoryBudgets = serverBudgets;
      });
      unawaited(_categoryBudgetStore.save(serverBudgets));
    } catch (e) {
      debugPrint('category budget mirror restore failed: $e');
    }
  }

  Future<void> _saveCategoryBudgets(Map<String, double> budgets) async {
    setState(() {
      _categoryBudgets = budgets;
    });
    await _categoryBudgetStore.save(budgets);
    unawaited(_mirrorCategoryBudgets());
  }

  Future<void> _loadRevolvingConfigs() async {
    try {
      final configs = await _revolvingConfigStore.load();
      if (mounted && configs.isNotEmpty) {
        setState(() {
          _revolvingConfigs = configs;
        });
      }
    } catch (e) {
      debugPrint('Error loading revolving credit configs: $e');
    }
    // 先に他端末の削除トゥームストーンを取込んでから復元する (review #1 直列化)。
    await _pullRevolvingDeleted();
    // ローカル読込後にサーバ集約ミラーから復元する (端末間同期 / 集約優先)。
    await _restoreRevolvingConfigsFromMirror();
    unawaited(_refreshSyncSources());
  }

  Future<void> _loadCardUsagePolicies() async {
    try {
      final policies = await _cardUsagePolicyStore.load();
      if (mounted && policies.isNotEmpty) {
        setState(() {
          _cardUsagePolicies = policies;
        });
      }
    } catch (e) {
      debugPrint('Error loading card usage policies: $e');
    }
    await _restoreCardUsagePoliciesFromMirror();
  }

  /// カード利用方針を 1 行 JSON としてミラーする。SharedPreferences は
  /// 未ログイン・オフライン時も一次ストアとして残す。
  Future<void> _mirrorCardUsagePolicies() async {
    unawaited(_syncTimestampStore.markChanged(_cardUsagePoliciesMirrorKey));
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      return;
    }
    try {
      await _supabase.from('asset_pref_mirror').upsert(<String, dynamic>{
        'user_id': userId,
        'pref_key': _cardUsagePoliciesMirrorKey,
        'value': AssetCardUsagePolicyStore.encodeMirrorValue(
          _cardUsagePolicies,
        ),
        'updated_at': DateTime.now().toUtc().toIso8601String(),
      });
      await _syncDirtyKeysStore.clearDomain(_cardUsagePoliciesMirrorKey);
    } catch (e) {
      debugPrint('card usage policy mirror upsert failed: $e');
    }
  }

  /// サーバにしかないカードは追加し、同一カードの衝突は既存の LWW 方針に従う。
  Future<void> _restoreCardUsagePoliciesFromMirror() async {
    if (_supabase.auth.currentUser == null) {
      return;
    }
    final localBefore = Map<String, AssetCardUsagePolicy>.from(
      _cardUsagePolicies,
    );
    final hasLocal = localBefore.isNotEmpty;
    try {
      final rows = await _bootSelectPrefMirror(_cardUsagePoliciesMirrorKey);
      if (rows.isEmpty) {
        if (hasLocal) {
          unawaited(_mirrorCardUsagePolicies());
        }
        return;
      }
      final serverPolicies = AssetCardUsagePolicyStore.decodeMirrorValue(
        rows.first['value'],
      );
      final mirrorUpdatedAt = DateTime.tryParse(
        rows.first['updated_at']?.toString() ?? '',
      );
      final adoptConflicts = await _shouldAdoptMirror(
        prefKey: _cardUsagePoliciesMirrorKey,
        hasLocal: hasLocal,
        mirrorUpdatedAt: mirrorUpdatedAt,
      );
      final dirtyKeys = await _syncDirtyKeysStore.loadDirty(
        _cardUsagePoliciesMirrorKey,
      );
      final merged = Map<String, AssetCardUsagePolicy>.from(localBefore);
      var changed = false;
      serverPolicies.forEach((key, policy) {
        if (!merged.containsKey(key) ||
            (adoptConflicts && !dirtyKeys.contains(key))) {
          merged[key] = policy;
          changed = true;
        }
      });
      if (changed && mounted) {
        setState(() {
          _cardUsagePolicies = merged;
        });
        _persistInBackground(
          _cardUsagePolicyStore.save(merged),
          'card usage policy restore save',
        );
        unawaited(
          _realignMirrorTimestamp(_cardUsagePoliciesMirrorKey, mirrorUpdatedAt),
        );
      }
      final localHasExtra = localBefore.keys.any(
        (key) => !serverPolicies.containsKey(key),
      );
      if (localHasExtra) {
        unawaited(_mirrorCardUsagePolicies());
      }
    } catch (e) {
      debugPrint('card usage policy mirror restore failed: $e');
    }
  }

  void _persistCardUsagePolicy(String cardId, AssetCardUsagePolicy policy) {
    setState(() {
      _cardUsagePolicies = <String, AssetCardUsagePolicy>{
        ..._cardUsagePolicies,
        cardId: policy,
      };
    });
    _persistInBackground(
      _cardUsagePolicyStore.save(_cardUsagePolicies),
      'card usage policy save',
    );
    unawaited(
      _syncDirtyKeysStore.markDirty(_cardUsagePoliciesMirrorKey, cardId),
    );
    unawaited(_mirrorCardUsagePolicies());
  }

  void _toggleCardOneShotCompleted(String cardId, bool completed) {
    final current = _cardUsagePolicies[cardId];
    _persistCardUsagePolicy(
      cardId,
      AssetCardUsagePolicy(
        enforceOneShot: completed,
        changedAt: completed ? DateTime.now().toUtc() : current?.changedAt,
        memo: current?.memo ?? '',
      ),
    );
  }

  /// メモはローカルへ即時保存し、ネットワーク upsert だけをデバウンスする。
  void _updateCardUsagePolicyMemo(String cardId, String memo) {
    final current = _cardUsagePolicies[cardId];
    if (current == null) {
      return;
    }
    _cardUsagePolicies = <String, AssetCardUsagePolicy>{
      ..._cardUsagePolicies,
      cardId: current.copyWith(memo: memo),
    };
    _persistInBackground(
      _cardUsagePolicyStore.save(_cardUsagePolicies),
      'card usage policy memo save',
    );
    unawaited(
      _syncDirtyKeysStore.markDirty(_cardUsagePoliciesMirrorKey, cardId),
    );
    _cardUsagePolicyMemoSaveTimer?.cancel();
    _cardUsagePolicyMemoSaveTimer = Timer(
      const Duration(milliseconds: 600),
      () {
        unawaited(_mirrorCardUsagePolicies());
      },
    );
  }

  // --- 定期固定費 (UI 登録) の読み書き・端末間同期 ---

  /// 起動時にローカルから読み、空ならサーバ集約ミラーから復元する。
  Future<void> _loadRecurringFixedCosts() async {
    if (widget.debugInitialRecurringFixedCosts == null) {
      try {
        final costs = await _recurringFixedCostStore.load();
        if (mounted && costs.isNotEmpty) {
          setState(() => _recurringFixedCosts = costs);
        }
      } catch (e) {
        debugPrint('Error loading recurring fixed costs: $e');
      }
    }
    // 先に他端末の削除トゥームストーンを取込んでから復元する (review #1 直列化)。
    await _pullRecurringFixedCostDeleted();
    await _restoreRecurringFixedCostsFromMirror();
  }

  /// サーバ集約ミラー (pref_key: recurring_fixed_costs) から復元する。リボ設定と
  /// 同じ tombstone-aware union マージ: ローカルに無い id はサーバから追加 (additive)、
  /// 削除トゥームストーン済み id は復活させず、衝突 id はフラグ既定 OFF ならローカル
  /// 優先 (LWW フラグ ON 時のみサーバ採用・dirty キーは保護)。
  Future<void> _restoreRecurringFixedCostsFromMirror() async {
    final debugMirror = widget.debugRecurringFixedCostsMirror;
    if (debugMirror == null && _supabase.auth.currentUser == null) {
      return;
    }
    final localBefore = <String, AssetRecurringFixedCost>{
      for (final cost in _recurringFixedCosts) cost.id: cost,
    };
    final hasLocal = localBefore.isNotEmpty;
    // 削除トゥームストーン: 復活させない / バックフィルしない。
    final tombstoned = _recurringFixedCostTombstones.activeIds(
      await SharedPreferences.getInstance(),
    );
    try {
      final List<AssetRecurringFixedCost> serverList;
      final DateTime? mirrorUpdatedAt;
      if (debugMirror != null) {
        serverList = AssetRecurringFixedCostStore.decodeMirrorValue(
          debugMirror,
        );
        mirrorUpdatedAt = DateTime.now().toUtc();
      } else {
        final rows = await _bootSelectPrefMirror(_recurringFixedCostsMirrorKey);
        if (rows.isEmpty) {
          // サーバ行が無い: ローカルにあれば初回バックフィル (他端末へ同期させる)。
          if (hasLocal) {
            unawaited(_mirrorRecurringFixedCosts());
          }
          return;
        }
        serverList = AssetRecurringFixedCostStore.decodeMirrorValue(
          rows.first['value'],
        );
        mirrorUpdatedAt = DateTime.tryParse(
          rows.first['updated_at']?.toString() ?? '',
        );
      }
      if (!mounted) {
        return;
      }
      final serverConfigs = <String, AssetRecurringFixedCost>{
        for (final cost in serverList) cost.id: cost,
      };
      final adoptConflicts = await _shouldAdoptMirror(
        prefKey: _recurringFixedCostsMirrorKey,
        hasLocal: hasLocal,
        mirrorUpdatedAt: mirrorUpdatedAt,
      );
      final merged = Map<String, AssetRecurringFixedCost>.from(localBefore);
      var changed = false;
      // 削除トゥームストーン済み id はローカルからも除く (clear 伝播 / 復活防止)。
      merged.removeWhere((key, _) {
        if (tombstoned.contains(key)) {
          changed = true;
          return true;
        }
        return false;
      });
      final dirtyKeys = await _syncDirtyKeysStore.loadDirty(
        _recurringFixedCostsMirrorKey,
      );
      serverConfigs.forEach((key, cost) {
        if (tombstoned.contains(key)) {
          return;
        }
        // #3415 保守的 per-key ガード: ローカル編集済み (dirty) id は、ドメイン全体
        // adopt の巻き添えで上書きしない (同一 id 衝突はローカル優先)。フラグ OFF は
        // merged が local 由来なので !containsKey が先に成立し no-op (本番無変更)。
        if (!merged.containsKey(key) ||
            (adoptConflicts && !dirtyKeys.contains(key))) {
          merged[key] = cost;
          changed = true;
        }
      });
      if (changed && mounted) {
        final nextList = merged.values.toList()
          ..sort(_compareRecurringFixedCostsByPaymentDay);
        setState(() {
          _recurringFixedCosts = nextList;
        });
        _persistInBackground(
          _recurringFixedCostStore.save(nextList),
          'recurring fixed cost restore save',
        );
        // additive 追加 / tombstone 除去でも時刻を整合 (ローカルが新しければ退行なし)。
        unawaited(
          _realignMirrorTimestamp(
            _recurringFixedCostsMirrorKey,
            mirrorUpdatedAt,
          ),
        );
      }
      // ローカルにあってサーバに無い id は、マージ結果をサーバへバックフィルし、
      // サーバを全端末の和集合に保つ。
      final localHasExtra = localBefore.keys.any(
        (key) => !tombstoned.contains(key) && !serverConfigs.containsKey(key),
      );
      final serverHasTombstoned = serverConfigs.keys.any(tombstoned.contains);
      if ((localHasExtra || serverHasTombstoned) && debugMirror == null) {
        unawaited(_mirrorRecurringFixedCosts());
      }
    } catch (e) {
      debugPrint('recurring fixed cost mirror restore failed: $e');
    }
  }

  /// 定期固定費の全量を `asset_pref_mirror` へ 1 行 upsert する。
  Future<void> _mirrorRecurringFixedCosts({bool throwOnFailure = false}) {
    return _recurringTombstoneSyncService.runSerialized(
      () => _mirrorRecurringFixedCostsNow(throwOnFailure: throwOnFailure),
    );
  }

  Future<void> _mirrorRecurringFixedCostsNow({
    bool throwOnFailure = false,
  }) async {
    unawaited(_syncTimestampStore.markChanged(_recurringFixedCostsMirrorKey));
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      return;
    }
    try {
      await _supabase.from('asset_pref_mirror').upsert(<String, dynamic>{
        'user_id': userId,
        'pref_key': _recurringFixedCostsMirrorKey,
        'value': AssetRecurringFixedCostStore.encodeMirrorValue(
          _recurringFixedCosts,
        ),
        'updated_at': DateTime.now().toUtc().toIso8601String(),
      });
      // 全量 upsert 成功 = 全 id 同期済み → dirty クリア。
      await _syncDirtyKeysStore.clearDomain(_recurringFixedCostsMirrorKey);
    } catch (e, stackTrace) {
      debugPrint('recurring fixed cost mirror upsert failed: $e');
      if (throwOnFailure) {
        Error.throwWithStackTrace(e, stackTrace);
      }
    }
  }

  // --- サブスク棚卸し (支払い元ごとの確認状況) ---

  Future<void> _loadSubscriptionAudit() async {
    try {
      final state = await _subscriptionAuditStore.load();
      final unconfirmed = await _subscriptionAuditStore.loadUnconfirmed();
      if (mounted && (state.isNotEmpty || unconfirmed.isNotEmpty)) {
        setState(() {
          _subscriptionAuditState = state;
          _subscriptionAuditUnconfirmed = unconfirmed;
        });
      }
    } catch (e) {
      debugPrint('Error loading subscription audit: $e');
    }
    await _restoreSubscriptionAuditFromMirror();
  }

  /// サーバ集約ミラー (pref_key: subscription_audit_state) から復元する。
  /// 確認 (checked) と取り消し (unconfirmed = tombstone) を独立に MAX マージして統合する。
  /// 新しい方の操作が勝つので誤復活せず、確認の取り消しも端末間で伝播する。
  Future<void> _restoreSubscriptionAuditFromMirror() async {
    final debugMirror = widget.debugSubscriptionAuditMirror;
    if (debugMirror == null && _supabase.auth.currentUser == null) {
      return;
    }
    final localCheckedBefore = Map<String, DateTime>.from(
      _subscriptionAuditState,
    );
    final localUnconfirmedBefore = Map<String, DateTime>.from(
      _subscriptionAuditUnconfirmed,
    );
    try {
      final dynamic serverValue;
      final DateTime? mirrorUpdatedAt;
      if (debugMirror != null) {
        serverValue = debugMirror;
        mirrorUpdatedAt = DateTime.now().toUtc();
      } else {
        final rows = await _bootSelectPrefMirror(_subscriptionAuditMirrorKey);
        if (rows.isEmpty) {
          // サーバ行無し: ローカルにあれば初回バックフィル。
          if (localCheckedBefore.isNotEmpty ||
              localUnconfirmedBefore.isNotEmpty) {
            unawaited(_mirrorSubscriptionAudit());
          }
          return;
        }
        serverValue = rows.first['value'];
        mirrorUpdatedAt = DateTime.tryParse(
          rows.first['updated_at']?.toString() ?? '',
        );
      }
      if (!mounted) {
        return;
      }
      final serverState = AssetSubscriptionAuditStore.decodeMirrorPayload(
        serverValue,
      );
      // 取込み中に確認/取り消しが入っても失わないよう、現在の in-memory state と
      // マージする (MAX は単調なので新しい操作を消さない)。
      final currentChecked = _subscriptionAuditState;
      final currentUnconfirmed = _subscriptionAuditUnconfirmed;
      final mergedChecked = AssetSubscriptionAuditStore.mergeMax(
        currentChecked,
        serverState.checked,
      );
      final mergedUnconfirmed = AssetSubscriptionAuditStore.mergeMax(
        currentUnconfirmed,
        serverState.unconfirmed,
      );
      final checkedChanged = !_sameSubscriptionAuditState(
        currentChecked,
        mergedChecked,
      );
      final unconfirmedChanged = !_sameSubscriptionAuditState(
        currentUnconfirmed,
        mergedUnconfirmed,
      );
      if (checkedChanged || unconfirmedChanged) {
        setState(() {
          _subscriptionAuditState = mergedChecked;
          _subscriptionAuditUnconfirmed = mergedUnconfirmed;
        });
        _persistInBackground(
          _subscriptionAuditStore.save(mergedChecked),
          'subscription audit restore save',
        );
        _persistInBackground(
          _subscriptionAuditStore.saveUnconfirmed(mergedUnconfirmed),
          'subscription audit restore save (unconfirmed)',
        );
        unawaited(
          _realignMirrorTimestamp(_subscriptionAuditMirrorKey, mirrorUpdatedAt),
        );
      }
      // ローカルにサーバより新しい確認/取り消しがあればサーバへ反映 (和集合維持)。
      final checkedNewer = _subscriptionAuditLocalHasNewer(
        localCheckedBefore,
        serverState.checked,
      );
      final unconfirmedNewer = _subscriptionAuditLocalHasNewer(
        localUnconfirmedBefore,
        serverState.unconfirmed,
      );
      if ((checkedNewer || unconfirmedNewer) && debugMirror == null) {
        unawaited(_mirrorSubscriptionAudit());
      }
    } catch (e) {
      debugPrint('subscription audit mirror restore failed: $e');
    }
  }

  /// local に server より新しい (= server に無いか後の) 時刻があれば true。
  bool _subscriptionAuditLocalHasNewer(
    Map<String, DateTime> local,
    Map<String, DateTime> server,
  ) {
    return local.entries.any((entry) {
      final remote = server[entry.key];
      return remote == null || entry.value.isAfter(remote);
    });
  }

  bool _sameSubscriptionAuditState(
    Map<String, DateTime> a,
    Map<String, DateTime> b,
  ) {
    if (a.length != b.length) {
      return false;
    }
    for (final entry in a.entries) {
      if (b[entry.key] != entry.value) {
        return false;
      }
    }
    return true;
  }

  /// 確認状況の全量 (確認 + 取り消し) を `asset_pref_mirror` へ 1 行 upsert する。
  Future<void> _mirrorSubscriptionAudit() async {
    unawaited(_syncTimestampStore.markChanged(_subscriptionAuditMirrorKey));
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      return;
    }
    try {
      await _supabase.from('asset_pref_mirror').upsert(<String, dynamic>{
        'user_id': userId,
        'pref_key': _subscriptionAuditMirrorKey,
        'value': AssetSubscriptionAuditStore.encodeMirrorPayload(
          _subscriptionAuditState,
          _subscriptionAuditUnconfirmed,
        ),
        'updated_at': DateTime.now().toUtc().toIso8601String(),
      });
    } catch (e) {
      debugPrint('subscription audit mirror upsert failed: $e');
    }
  }

  void _markSubscriptionSourceChecked(SubscriptionAuditSource source) {
    final next = Map<String, DateTime>.from(_subscriptionAuditState);
    next[source.id] = DateTime.now().toUtc();
    setState(() => _subscriptionAuditState = next);
    _persistInBackground(
      _subscriptionAuditStore.save(next),
      'subscription audit save',
    );
    unawaited(_mirrorSubscriptionAudit());
    // 誤クリック救済: 直後に「元に戻す」で未確認へ戻せる SnackBar を出す。
    if (!mounted) {
      return;
    }
    final messenger = ScaffoldMessenger.of(context);
    messenger.clearSnackBars();
    messenger.showSnackBar(
      SnackBar(
        content: Text('「${source.name}」を確認済みにしました'),
        action: SnackBarAction(
          label: '元に戻す',
          onPressed: () => _unmarkSubscriptionSourceChecked(source),
        ),
      ),
    );
  }

  /// 確認を取り消して当該ソースを未確認へ戻す (常設「確認を取り消す」/ SnackBar の
  /// 「元に戻す」の共通経路)。確認時刻は履歴として残し、取り消し時刻 (tombstone) を now で
  /// 記録する。effective 判定で「取り消し > 確認」となり未確認表示になり、端末間も MAX
  /// マージで誤復活しない (キー削除と違い、最後の操作が確実に勝つ)。
  void _unmarkSubscriptionSourceChecked(SubscriptionAuditSource source) {
    final next = Map<String, DateTime>.from(_subscriptionAuditUnconfirmed);
    next[source.id] = DateTime.now().toUtc();
    setState(() => _subscriptionAuditUnconfirmed = next);
    _persistInBackground(
      _subscriptionAuditStore.saveUnconfirmed(next),
      'subscription audit unconfirm save',
    );
    unawaited(_mirrorSubscriptionAudit());
    if (!mounted) {
      return;
    }
    final messenger = ScaffoldMessenger.of(context);
    messenger.clearSnackBars();
    messenger.showSnackBar(const SnackBar(content: Text('確認を取り消しました')));
  }

  /// 棚卸し対象の支払い元: manual (Apple/au/Google) + 銀行 + カード別 (口座から導出)。
  /// カード別はクレジットカードに加え、サブスクの請求先になりうるショッピング枠
  /// (アコムショッピング枠など shoppingDebt) も含める (定期固定費エディタの請求先と同じ集合)。
  List<SubscriptionAuditSource> _subscriptionAuditSources(
    AssetLiabilityWorkbook? workbook,
  ) {
    final sources = <SubscriptionAuditSource>[
      ...AssetSubscriptionAuditCatalog.manualSources,
      AssetSubscriptionAuditCatalog.bankSource,
    ];
    if (workbook != null) {
      final cardOptions = _cardBillingAccountOptions(
        workbook,
        includeShoppingDebt: true,
      );
      for (final account in cardOptions) {
        sources.add(
          SubscriptionAuditSource(
            id: AssetSubscriptionAuditCatalog.cardSourceId(account.id),
            name: account.name,
            kind: SubscriptionAuditSourceKind.autoAssisted,
          ),
        );
      }
    }
    return sources;
  }

  /// 未登録の定期支出を支払い元 (sourceId) ごとに集計する。検出は登録済み・無視済みを
  /// 減算済みの `_detectRecurringTransactions()` を流用 (提案カードと二重計上しない)。
  Map<String, int> _unregisteredCountBySourceId(
    AssetLiabilityWorkbook? workbook,
  ) {
    final detected = _detectRecurringTransactions();
    if (detected.isEmpty) {
      return const <String, int>{};
    }
    final accounts = workbook?.accounts ?? const <AssetLiabilityAccount>[];
    return AssetSubscriptionAuditCatalog.bucketUnregisteredCounts(
      accounts: accounts.map(
        (account) => (id: account.id, name: account.name, kind: account.kind),
      ),
      suggestedSourceNames: detected.map((item) => item.suggestedSourceName),
    );
  }

  Widget _buildSubscriptionAuditCard(AssetLiabilityWorkbook? workbook) {
    final accounts = workbook?.accounts ?? const <AssetLiabilityAccount>[];
    // サブスクはカード (ファミペイ等) へ請求されることが多いため、残高<=0 のカードも
    // 請求先として選べるようにする。
    final sourceOptions = recurringFixedCostSourceOptions(
      accounts,
      includeCards: true,
      includeCarrierBilling: true,
    );
    final gatewayTotals = AssetSubscriptionAuditCatalog.gatewayTotalsBySourceId(
      subscriptions: [
        for (final cost in _recurringFixedCosts)
          if (cost.category == AssetRecurringFixedCostCategory.subscription)
            (gateway: cost.billingGateway, amount: cost.amount),
      ],
    );
    return SubscriptionAuditCard(
      sources: _subscriptionAuditSources(workbook),
      lastCheckedAt: AssetSubscriptionAuditStore.effectiveCheckedAt(
        _subscriptionAuditState,
        _subscriptionAuditUnconfirmed,
      ),
      unregisteredCountBySourceId: _unregisteredCountBySourceId(workbook),
      registeredByGatewaySourceId: gatewayTotals,
      cardBreakdownBySourceId: _subscriptionGatewayCardBreakdown(accounts),
      now: _now,
      onMarkChecked: _markSubscriptionSourceChecked,
      onUnmarkChecked: _unmarkSubscriptionSourceChecked,
      onRegisterSubscription: (source) => unawaited(
        _openRecurringFixedCostEditor(
          sourceOptions: sourceOptions,
          category: AssetRecurringFixedCostCategory.subscription,
          // Apple/au/Google 行から登録するときは請求経路を既定で合わせる。
          gateway:
              AssetSubscriptionAuditCatalog.gatewayForSourceId(source.id) ??
                  AssetSubscriptionBillingGateway.direct,
        ),
      ),
    );
  }

  /// 登録済みサブスクを「経由ソース × 請求先カード」で集計し、カード名ラベルへ解決する。
  /// 同じ Apple経由でも請求先カードが分かれる場合に、各カードの集約請求と突き合わせる。
  Map<String, List<GatewayCardBreakdownLine>> _subscriptionGatewayCardBreakdown(
    List<AssetLiabilityAccount> accounts,
  ) {
    final accountNames = <String, String>{
      for (final account in accounts) account.id: account.name,
    };
    final knownIds = accountNames.keys.toSet();
    final inputs = <SubscriptionGatewayInput>[];
    for (final cost in _recurringFixedCosts) {
      if (cost.category != AssetRecurringFixedCostCategory.subscription) {
        continue;
      }
      // 未知/削除済みカードは未設定 (null) へ寄せ、内訳の重複表示を防ぐ。
      final fundingCard = AssetSubscriptionAuditCatalog.normalizeFundingCard(
        cost.sourceAccountId,
        knownIds,
      );
      inputs.add((
        gateway: cost.billingGateway,
        amount: cost.amount,
        sourceAccountId: fundingCard,
      ));
    }
    final raw = AssetSubscriptionAuditCatalog.gatewayCardBreakdownBySourceId(
      subscriptions: inputs,
    );
    final result = <String, List<GatewayCardBreakdownLine>>{};
    raw.forEach((sourceId, cards) {
      result[sourceId] = <GatewayCardBreakdownLine>[
        for (final card in cards)
          (
            label: _fundingCardLabel(card.fundingAccountId, accountNames),
            count: card.count,
            total: card.total,
          ),
      ];
    });
    return result;
  }

  String _fundingCardLabel(String? id, Map<String, String> accountNames) {
    if (id == null) {
      return '請求先カード未設定';
    }
    return accountNames[id] ?? '請求先カード未設定';
  }

  /// 削除した定期固定費のトゥームストーン。union マージ/backfill での復活を防ぎ、
  /// 他端末へ削除を伝播する (リボ設定と同じパターン)。
  static const MirrorTombstoneStore _recurringFixedCostTombstones =
      MirrorTombstoneStore(storageKey: 'recurring_fixed_costs_deleted_v1');
  static const String _recurringTombstoneLegacyMigrationKey =
      'recurring_fixed_cost_tombstone_pending_v2_migrated';

  String _recurringTombstoneOperation(String id, {required bool deleted}) =>
      AssetRecurringTombstoneSyncService.operation(id, deleted: deleted);

  Set<String> _recurringTombstoneOperationIds(
    Set<String> operations,
    String prefix,
  ) =>
      AssetRecurringTombstoneSyncService.operationIds(operations, prefix);

  Future<void> _queueRecurringFixedCostTombstoneOperation(
    SharedPreferences store,
    String id, {
    required bool deleted,
  }) {
    return _recurringTombstoneSyncService.queue(
      _recurringFixedCostsDeletedMirrorKey,
      id,
      deleted: deleted,
      prefs: store,
    );
  }

  /// 定期固定費の削除トゥームストーンを DB 側の atomic union/remove RPC で
  /// サーバへ反映する。whole-blob upsert による端末間 lost-update を避ける。
  // ignore: unused_element
  Future<bool> _mirrorRecurringFixedCostsDeleted({
    bool mirrorCurrentOnSuccess = false,
  }) {
    return _recurringTombstoneSyncService.runSerialized(
      () => _mirrorRecurringFixedCostsDeletedNow(
        mirrorCurrentOnSuccess: mirrorCurrentOnSuccess,
      ),
    );
  }

  Future<bool> _mirrorRecurringFixedCostsDeletedNow({
    bool mirrorCurrentOnSuccess = false,
  }) async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      return true;
    }
    final store = await SharedPreferences.getInstance();
    return _recurringTombstoneSyncService.syncNow(
      prefKey: _recurringFixedCostsDeletedMirrorKey,
      prefs: store,
      rpc: (additions, removals) async {
        await _supabase.rpc(
          'apply_recurring_fixed_cost_tombstones',
          params: {'p_add_ids': additions, 'p_remove_ids': removals},
        );
      },
      afterSync: mirrorCurrentOnSuccess
          ? () => _mirrorRecurringFixedCostsNow(throwOnFailure: true)
          : null,
    );
  }

  /// 他端末で削除された定期固定費を取り込み、ローカルからも除去する。
  Future<void> _pullRecurringFixedCostDeleted() {
    return _recurringTombstoneSyncService.runSerialized(
      _pullRecurringFixedCostDeletedNow,
    );
  }

  Future<void> _pullRecurringFixedCostDeletedNow() async {
    final debugMirror = widget.debugRecurringFixedCostsDeletedMirror;
    if (debugMirror == null && _supabase.auth.currentUser == null) {
      return;
    }
    try {
      final store = await SharedPreferences.getInstance();
      Map<String, dynamic>? value = debugMirror;
      var remoteExists = debugMirror != null;
      if (value == null) {
        final rows = await _bootSelectPrefMirror(
          _recurringFixedCostsDeletedMirrorKey,
        );
        if (rows.isNotEmpty) {
          remoteExists = true;
          final raw = rows.first['value'];
          if (raw is! Map || raw['ids'] is! List) {
            throw const FormatException(
              'recurring fixed cost tombstone mirror is malformed',
            );
          }
          value = Map<String, dynamic>.from(raw);
        }
      }
      final remoteIds = MirrorTombstoneStore.decodeMirror(value).toSet();
      var pending = await _syncDirtyKeysStore.loadDirty(
        _recurringFixedCostsDeletedMirrorKey,
        prefs: store,
      );
      final localIds = _recurringFixedCostTombstones.activeIds(store);
      final pendingRemovals = _recurringTombstoneOperationIds(
        pending,
        AssetRecurringTombstoneSyncService.removePrefix,
      );
      final needsLegacyMigration =
          !(store.getBool(_recurringTombstoneLegacyMigrationKey) ?? false);
      if (needsLegacyMigration && localIds.isNotEmpty) {
        final legacyAdds = localIds.difference(pendingRemovals);
        await _syncDirtyKeysStore.updateDirty(
          _recurringFixedCostsDeletedMirrorKey,
          addKeys: <String>[
            for (final id in legacyAdds)
              _recurringTombstoneOperation(id, deleted: true),
          ],
          prefs: store,
        );
        await store.setBool(_recurringTombstoneLegacyMigrationKey, true);
        pending = await _syncDirtyKeysStore.loadDirty(
          _recurringFixedCostsDeletedMirrorKey,
          prefs: store,
        );
      } else if (needsLegacyMigration) {
        await store.setBool(_recurringTombstoneLegacyMigrationKey, true);
      }

      final desiredIds = remoteExists
          ? Set<String>.from(remoteIds)
          : Set<String>.from(localIds);
      desiredIds.addAll(
        _recurringTombstoneOperationIds(
          pending,
          AssetRecurringTombstoneSyncService.addPrefix,
        ),
      );
      desiredIds.removeAll(
        _recurringTombstoneOperationIds(
          pending,
          AssetRecurringTombstoneSyncService.removePrefix,
        ),
      );
      for (final id in localIds.difference(desiredIds)) {
        await _recurringFixedCostTombstones.removeId(store, id);
      }
      for (final id in desiredIds.difference(localIds)) {
        await _recurringFixedCostTombstones.addId(store, id);
      }
      final next = _recurringFixedCosts
          .where((cost) => !desiredIds.contains(cost.id))
          .toList();
      if (!mounted) return;
      if (next.length != _recurringFixedCosts.length) {
        setState(() {
          _recurringFixedCosts = next;
        });
        await _recurringFixedCostStore.save(next, prefs: store);
      }
      if (debugMirror == null && pending.isNotEmpty) {
        await _mirrorRecurringFixedCostsDeletedNow(
          mirrorCurrentOnSuccess: true,
        );
      }
    } catch (e) {
      debugPrint('recurring fixed cost tombstone pull failed: $e');
    }
  }

  /// 起動時に「無視」集合をローカルから読み、サーバミラーと union する。
  Future<void> _loadRecurringIgnored() async {
    try {
      final ignored = await _recurringIgnoreStore.load();
      if (mounted && ignored.isNotEmpty) {
        setState(() => _ignoredRecurringLabels = ignored);
      }
    } catch (e) {
      debugPrint('Error loading recurring ignored: $e');
    }
    await _restoreRecurringIgnoredFromMirror();
  }

  /// サーバミラー (pref_key: recurring_suggestion_ignored) を取り込み、ローカル集合と
  /// union する(無視は単調増加なので union が安全)。
  Future<void> _restoreRecurringIgnoredFromMirror() async {
    if (_supabase.auth.currentUser == null) {
      return;
    }
    try {
      final rows = await _bootSelectPrefMirror(_recurringIgnoredMirrorKey);
      if (rows.isEmpty) {
        return;
      }
      final serverIgnored =
          AssetRecurringSuggestionIgnoreStore.decodeMirrorValue(
        rows.first['value'],
      );
      if (!mounted || serverIgnored.isEmpty) {
        return;
      }
      final merged = <String>{..._ignoredRecurringLabels, ...serverIgnored};
      if (merged.length == _ignoredRecurringLabels.length) {
        return; // サーバに新規無視なし。
      }
      setState(() => _ignoredRecurringLabels = merged);
      _persistInBackground(
        _recurringIgnoreStore.save(merged),
        'recurring ignored restore save',
      );
    } catch (e) {
      debugPrint('recurring ignored mirror restore failed: $e');
    }
  }

  /// 「無視」集合の全量を `asset_pref_mirror` へ 1 行 upsert する。
  Future<void> _mirrorRecurringIgnored() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      return;
    }
    try {
      await _supabase.from('asset_pref_mirror').upsert(<String, dynamic>{
        'user_id': userId,
        'pref_key': _recurringIgnoredMirrorKey,
        'value': AssetRecurringSuggestionIgnoreStore.encodeMirrorValue(
          _ignoredRecurringLabels,
        ),
        'updated_at': DateTime.now().toUtc().toIso8601String(),
      });
    } catch (e) {
      debugPrint('recurring ignored mirror upsert failed: $e');
    }
  }

  /// 検出候補を「無視」集合へ追加して再提案を止める(永続化 + ミラー)。
  void _ignoreDetectedRecurringTransaction(
    DetectedRecurringTransaction detected,
  ) {
    final label = _normalizeRecurringLabel(detected.label);
    if (label.isEmpty || _ignoredRecurringLabels.contains(label)) {
      return;
    }
    setState(() {
      _ignoredRecurringLabels = <String>{..._ignoredRecurringLabels, label};
    });
    _persistInBackground(
      _recurringIgnoreStore.save(_ignoredRecurringLabels),
      'recurring ignored save',
    );
    unawaited(_mirrorRecurringIgnored());
  }

  /// 起動時に「重複ではない」とした提供元集合をローカルから読み、ミラーと union する。
  Future<void> _loadDuplicateIgnored() async {
    try {
      final ignored = await _duplicateIgnoreStore.load();
      if (mounted && ignored.isNotEmpty) {
        setState(() => _ignoredDuplicateProviders = ignored);
      }
    } catch (e) {
      debugPrint('Error loading duplicate ignored: $e');
    }
    await _restoreDuplicateIgnoredFromMirror();
  }

  /// サーバミラー (pref_key: subscription_duplicate_ignored) を取り込み、ローカル集合と
  /// union する(無視は単調増加なので union が安全)。
  Future<void> _restoreDuplicateIgnoredFromMirror() async {
    if (_supabase.auth.currentUser == null) {
      return;
    }
    try {
      final rows = await _bootSelectPrefMirror(_duplicateIgnoredMirrorKey);
      if (rows.isEmpty) {
        return;
      }
      final serverIgnored =
          AssetRecurringSuggestionIgnoreStore.decodeMirrorValue(
        rows.first['value'],
      );
      if (!mounted || serverIgnored.isEmpty) {
        return;
      }
      final merged = <String>{..._ignoredDuplicateProviders, ...serverIgnored};
      if (merged.length == _ignoredDuplicateProviders.length) {
        return; // サーバに新規無視なし。
      }
      setState(() => _ignoredDuplicateProviders = merged);
      _persistInBackground(
        _duplicateIgnoreStore.save(merged),
        'duplicate ignored restore save',
      );
    } catch (e) {
      debugPrint('duplicate ignored mirror restore failed: $e');
    }
  }

  /// 「重複ではない」集合の全量を `asset_pref_mirror` へ 1 行 upsert する。
  Future<void> _mirrorDuplicateIgnored() async {
    final userId = _supabase.auth.currentUser?.id;
    if (userId == null) {
      return;
    }
    try {
      await _supabase.from('asset_pref_mirror').upsert(<String, dynamic>{
        'user_id': userId,
        'pref_key': _duplicateIgnoredMirrorKey,
        'value': AssetRecurringSuggestionIgnoreStore.encodeMirrorValue(
          _ignoredDuplicateProviders,
        ),
        'updated_at': DateTime.now().toUtc().toIso8601String(),
      });
    } catch (e) {
      debugPrint('duplicate ignored mirror upsert failed: $e');
    }
  }

  /// 提供元グループを「重複ではない」として今後の提示から除外する(永続化 + ミラー)。
  void _ignoreDuplicateGroup(SubscriptionDuplicateGroup group) {
    final key = group.providerKey;
    if (key.isEmpty || _ignoredDuplicateProviders.contains(key)) {
      return;
    }
    setState(() {
      _ignoredDuplicateProviders = <String>{..._ignoredDuplicateProviders, key};
    });
    _persistInBackground(
      _duplicateIgnoreStore.save(_ignoredDuplicateProviders),
      'duplicate ignored save',
    );
    unawaited(_mirrorDuplicateIgnored());
  }

  /// 登録済みサブスクから「同じ提供元の複数契約 = 重複の可能性」を検出する。
  List<SubscriptionDuplicateGroup> _detectSubscriptionDuplicates() {
    return AssetSubscriptionDuplicateDetector.detect(
      <SubscriptionDuplicateMember>[
        for (final cost in _recurringFixedCosts)
          if (cost.category == AssetRecurringFixedCostCategory.subscription)
            (
              id: cost.id,
              name: cost.name,
              amount: cost.amount,
              gateway: cost.billingGateway,
            ),
      ],
      ignoredProviderKeys: _ignoredDuplicateProviders,
    );
  }

