  /// USD/JPY レートを取得し、ドル建てサブスクの円額を最新レートで再計算する。
  Future<void> _loadUsdJpyRate() async {
    try {
      // まずキャッシュで即時反映 → 次にネットワークで鮮度を更新。
      final cached = await _fxRateService.cachedUsdJpy();
      if (cached != null && mounted) {
        _applyUsdJpyRate(cached);
      }
      final fresh = await _fxRateService.getUsdJpy();
      if (fresh != null && mounted) {
        _applyUsdJpyRate(fresh);
      }
    } catch (e) {
      debugPrint('Error loading USD/JPY rate: $e');
    }
  }

  /// 取得したレートを保持し、ドル建てサブスクの円額 (amount) を再計算する。
  /// 円額が変わったものだけ差し替えて永続化する (レート変動を自動追随)。
  void _applyUsdJpyRate(FxRate rate) {
    final recomputed = <AssetRecurringFixedCost>[];
    var changed = false;
    for (final cost in _recurringFixedCosts) {
      if (!cost.isUsd || cost.usdAmount == null) {
        recomputed.add(cost);
        continue;
      }
      final jpy = cost.resolveJpyAmount(rate.jpyPerUnit);
      if (jpy > 0 && jpy != cost.amount) {
        recomputed.add(cost.copyWith(amount: jpy));
        changed = true;
      } else {
        recomputed.add(cost);
      }
    }
    setState(() {
      _usdJpyRate = rate;
      if (changed) {
        _recurringFixedCosts = recomputed;
      }
    });
    if (changed) {
      _persistInBackground(
        _recurringFixedCostStore.save(_recurringFixedCosts),
        'recurring fixed cost fx recompute',
      );
      unawaited(_mirrorRecurringFixedCosts());
    }
  }

  Future<bool> _commitRecurringFixedCostReadditionsNow({
    required List<AssetRecurringFixedCost> previous,
    required List<AssetRecurringFixedCost> next,
    required Set<String> ids,
  }) async {
    if (ids.isEmpty) return true;
    final store = await SharedPreferences.getInstance();
    final tombstonesBefore = _recurringFixedCostTombstones.activeIds(store);
    final pendingBefore = await _syncDirtyKeysStore.loadDirty(
      _recurringFixedCostsDeletedMirrorKey,
      prefs: store,
    );
    final currentDirtyBefore = await _syncDirtyKeysStore.loadDirty(
      _recurringFixedCostsMirrorKey,
      prefs: store,
    );
    final affectedOperations = <String>{
      for (final id in ids) _recurringTombstoneOperation(id, deleted: true),
      for (final id in ids) _recurringTombstoneOperation(id, deleted: false),
    };
    try {
      // Journal the re-add intent before publishing the new current list. The
      // whole sequence owns the shared FIFO, so boot/delete sync cannot consume
      // the intent between these writes.
      for (final id in ids) {
        await _queueRecurringFixedCostTombstoneOperation(
          store,
          id,
          deleted: false,
        );
      }
      await _recurringFixedCostStore.save(next, prefs: store);
      for (final id in ids) {
        await _recurringFixedCostTombstones.removeId(store, id);
        await _syncDirtyKeysStore.markDirty(
          _recurringFixedCostsMirrorKey,
          id,
          prefs: store,
        );
      }
    } catch (error, stackTrace) {
      try {
        await _syncDirtyKeysStore.updateDirty(
          _recurringFixedCostsDeletedMirrorKey,
          addKeys: pendingBefore.intersection(affectedOperations),
          removeKeys: affectedOperations,
          prefs: store,
        );
        await _syncDirtyKeysStore.updateDirty(
          _recurringFixedCostsMirrorKey,
          addKeys: currentDirtyBefore.intersection(ids),
          removeKeys: ids,
          prefs: store,
        );
      } catch (rollbackError) {
        debugPrint(
          'recurring fixed cost dirty rollback failed: $rollbackError',
        );
      }
      try {
        await _recurringFixedCostStore.save(previous, prefs: store);
      } catch (rollbackError) {
        debugPrint('recurring fixed cost data rollback failed: $rollbackError');
      }
      try {
        for (final id in ids) {
          if (tombstonesBefore.contains(id)) {
            await _recurringFixedCostTombstones.addId(store, id);
          } else {
            await _recurringFixedCostTombstones.removeId(store, id);
          }
        }
      } catch (rollbackError) {
        debugPrint(
          'recurring fixed cost tombstone rollback failed: $rollbackError',
        );
      }
      Error.throwWithStackTrace(error, stackTrace);
    }

    if (mounted) {
      setState(() => _recurringFixedCosts = next);
    } else {
      _recurringFixedCosts = next;
    }
    final synced = await _mirrorRecurringFixedCostsDeletedNow(
      mirrorCurrentOnSuccess: true,
    );
    if (!synced && mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('端末では保存済みです。サーバー同期は次回オンライン時に再試行します。'),
          backgroundColor: Color(0xFFB45309),
        ),
      );
    }
    return synced;
  }

  Future<void> _saveRecurringFixedCost(AssetRecurringFixedCost cost) async {
    try {
      await _recurringTombstoneSyncService.runSerialized(() async {
        final previous = List<AssetRecurringFixedCost>.from(
          _recurringFixedCosts,
        );
        final next = List<AssetRecurringFixedCost>.from(previous);
        final index = next.indexWhere((existing) => existing.id == cost.id);
        if (index >= 0) {
          next[index] = cost;
        } else {
          next.add(cost);
        }
        next.sort(_compareRecurringFixedCostsByPaymentDay);
        await _commitRecurringFixedCostReadditionsNow(
          previous: previous,
          next: next,
          ids: <String>{cost.id},
        );
      });
    } catch (error) {
      debugPrint('recurring fixed cost save failed: $error');
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('定期固定費を保存できませんでした。元の状態を保持しています。'),
            backgroundColor: Color(0xFFB91C1C),
          ),
        );
      }
    }
  }

  Future<void> _deleteRecurringFixedCosts(
    Iterable<AssetRecurringFixedCost> costs,
  ) {
    final ids =
        costs.map((cost) => cost.id).where((id) => id.isNotEmpty).toSet();
    if (ids.isEmpty) return Future<void>.value();
    return _recurringTombstoneSyncService.runSerialized(
      () => _deleteRecurringFixedCostsNow(ids),
    );
  }

  Future<void> _deleteRecurringFixedCostsNow(Set<String> ids) async {
    final next = _recurringFixedCosts
        .where((existing) => !ids.contains(existing.id))
        .toList(growable: false);
    if (next.length == _recurringFixedCosts.length) return;

    final store = await SharedPreferences.getInstance();
    final tombstonesBefore = _recurringFixedCostTombstones.activeIds(store);
    final addedTombstones = ids.difference(tombstonesBefore);
    final pendingBefore = await _syncDirtyKeysStore.loadDirty(
      _recurringFixedCostsDeletedMirrorKey,
      prefs: store,
    );
    final affectedOperations = <String>{
      for (final id in ids) _recurringTombstoneOperation(id, deleted: true),
      for (final id in ids) _recurringTombstoneOperation(id, deleted: false),
    };
    try {
      for (final id in ids) {
        await _queueRecurringFixedCostTombstoneOperation(
          store,
          id,
          deleted: true,
        );
        await _recurringFixedCostTombstones.addId(store, id);
      }
      await _recurringFixedCostStore.save(next);
    } catch (error, stackTrace) {
      await _syncDirtyKeysStore.updateDirty(
        _recurringFixedCostsDeletedMirrorKey,
        addKeys: pendingBefore.intersection(affectedOperations),
        removeKeys: affectedOperations,
        prefs: store,
      );
      for (final id in addedTombstones) {
        await _recurringFixedCostTombstones.removeId(store, id);
      }
      Error.throwWithStackTrace(error, stackTrace);
    }
    if (mounted) {
      setState(() => _recurringFixedCosts = next);
    } else {
      _recurringFixedCosts = next;
    }
    // サーバ同期が失敗しても dirty operation を保持し、次回bootで再試行する。
    // stale current mirror はtombstone同期成功後だけ更新する。
    final tombstonesSynced = await _mirrorRecurringFixedCostsDeletedNow(
      mirrorCurrentOnSuccess: true,
    );
    if (!tombstonesSynced && mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('端末では削除済みです。サーバー同期は次回オンライン時に再試行します。'),
          backgroundColor: Color(0xFFB45309),
        ),
      );
    }
  }

  Future<void> _deleteRecurringFixedCost(AssetRecurringFixedCost cost) {
    return _deleteRecurringFixedCosts(<AssetRecurringFixedCost>[cost]);
  }

  Future<void> _openRecurringFixedCostEditor({
    AssetRecurringFixedCost? existing,
    AssetRecurringFixedCost? prefill,
    required List<RecurringFixedCostSourceOption> sourceOptions,
    AssetRecurringFixedCostCategory category =
        AssetRecurringFixedCostCategory.utility,
    AssetSubscriptionBillingGateway gateway =
        AssetSubscriptionBillingGateway.direct,
  }) async {
    final result = await showRecurringFixedCostEditor(
      context,
      existing: existing,
      prefill: prefill,
      sourceAccounts: sourceOptions,
      category: category,
      gateway: gateway,
      usdJpyRate: _usdJpyRate?.jpyPerUnit,
      usdJpyRateAsOf: _usdJpyRate?.asOf,
    );
    if (result != null) {
      await _saveRecurringFixedCost(result);
    }
  }

  Future<void> _confirmDeleteRecurringFixedCost(
    AssetRecurringFixedCost cost,
  ) async {
    final isSubscription =
        cost.category == AssetRecurringFixedCostCategory.subscription;
    final formattedMonthlyAmount = NumberFormat(
      '#,##0',
    ).format(cost.amount.round());
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text(isSubscription ? 'サブスクを削除' : '定期固定費を削除'),
        content: Text(
          isSubscription
              ? '「${cost.name}」（月額 ¥$formattedMonthlyAmount）を現在のサブスクから'
                  '削除しますか？過去の月次履歴・取引履歴は残ります。'
              : '「${cost.name}」を削除しますか？',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(false),
            child: const Text('キャンセル'),
          ),
          FilledButton(
            onPressed: () => Navigator.of(dialogContext).pop(true),
            child: const Text('削除'),
          ),
        ],
      ),
    );
    if (confirmed == true) {
      await _deleteRecurringFixedCost(cost);
    }
  }

  Widget _buildRecurringFixedCostCard(AssetLiabilityWorkbook? workbook) {
    final accounts = workbook?.accounts ?? const <AssetLiabilityAccount>[];
    final sourceOptions = recurringFixedCostSourceOptions(accounts);
    final sourceNames = <String, String>{
      for (final account in accounts) account.id: account.name,
    };
    // サブスク区分は専用カードに分離し、ここでは従来の固定費 (utility) だけ表示する。
    final utilityCosts = <AssetRecurringFixedCost>[
      for (final cost in _recurringFixedCosts)
        if (cost.category == AssetRecurringFixedCostCategory.utility) cost,
    ]..sort(_compareRecurringFixedCostsByPaymentDay);
    return RecurringFixedCostCard(
      costs: utilityCosts,
      sourceAccountNames: sourceNames,
      onAdd: () => unawaited(
        _openRecurringFixedCostEditor(sourceOptions: sourceOptions),
      ),
      onEdit: (cost) => unawaited(
        _openRecurringFixedCostEditor(
          existing: cost,
          sourceOptions: sourceOptions,
        ),
      ),
      onDelete: (cost) => unawaited(_confirmDeleteRecurringFixedCost(cost)),
    );
  }

  Widget _buildSubscriptionFixedCostCard(AssetLiabilityWorkbook? workbook) {
    final accounts = workbook?.accounts ?? const <AssetLiabilityAccount>[];
    // サブスクはカード (ファミペイ等) へ請求されることが多いため、残高<=0 のカードも
    // 請求先として選べるようにする。
    final sourceOptions = recurringFixedCostSourceOptions(
      accounts,
      includeCards: true,
      includeCarrierBilling: true,
    );
    final sourceNames = <String, String>{
      for (final account in accounts) account.id: account.name,
    };
    final subscriptionCosts = <AssetRecurringFixedCost>[
      for (final cost in _recurringFixedCosts)
        if (cost.category == AssetRecurringFixedCostCategory.subscription) cost,
    ]..sort(_compareRecurringFixedCostsByPaymentDay);
    return SubscriptionFixedCostCard(
      costs: subscriptionCosts,
      sourceAccountNames: sourceNames,
      onScanStatement: () => unawaited(
        _openSubscriptionStatementScanDialog(subscriptionCosts, sourceNames),
      ),
      onAddPreset: (preset) => unawaited(
        _openRecurringFixedCostEditor(
          prefill: preset.toPrefill(
            paymentDay: AssetSubscriptionCatalog.defaultPaymentDay,
          ),
          sourceOptions: sourceOptions,
          category: AssetRecurringFixedCostCategory.subscription,
        ),
      ),
      onAddCustom: () => unawaited(
        _openRecurringFixedCostEditor(
          sourceOptions: sourceOptions,
          category: AssetRecurringFixedCostCategory.subscription,
        ),
      ),
      onEdit: (cost) => unawaited(
        _openRecurringFixedCostEditor(
          existing: cost,
          sourceOptions: sourceOptions,
        ),
      ),
      onDelete: (cost) => unawaited(_confirmDeleteRecurringFixedCost(cost)),
      onReviewDecisionChanged: (cost, decision) => _saveRecurringFixedCost(
        cost.copyWith(subscriptionReviewDecision: decision),
      ),
    );
  }

  Future<void> _openSubscriptionStatementScanDialog(
    List<AssetRecurringFixedCost> existingSubscriptions,
    Map<String, String> sourceAccountNames,
  ) async {
    final viewModel = AssetSubscriptionStatementScanViewModel(
      imagePicker: const FilePickerAssetSubscriptionStatementImagePicker(),
      analyzer: const AssetSubscriptionStatementScanService(),
      existingSubscriptions: existingSubscriptions,
    );
    await showDialog<bool>(
      context: context,
      barrierDismissible: false,
      builder: (context) => AssetSubscriptionStatementScanDialog(
        viewModel: viewModel,
        sourceAccountNames: sourceAccountNames,
        onImport: _importSubscriptionStatementCosts,
        onLogin: _openAssetSubscriptionLoginDialog,
      ),
    );
  }

  Future<bool> _openAssetSubscriptionLoginDialog() async {
    return await showDialog<bool>(
          context: context,
          barrierDismissible: false,
          builder: (context) => const AssetSubscriptionLoginDialog(),
        ) ??
        false;
  }

  Future<void> _importSubscriptionStatementCosts(
    List<AssetRecurringFixedCost> importedCosts,
  ) async {
    if (importedCosts.isEmpty) return;
    final addedCount = await _recurringTombstoneSyncService.runSerialized(
      () async {
        final previous = List<AssetRecurringFixedCost>.from(
          _recurringFixedCosts,
        );
        final next = List<AssetRecurringFixedCost>.from(previous);
        final existingNames = <String>{
          for (final cost in next) _normalizeSubscriptionName(cost.name),
        };
        final added = <AssetRecurringFixedCost>[];
        for (final cost in importedCosts) {
          final normalized = _normalizeSubscriptionName(cost.name);
          if (normalized.isEmpty || existingNames.contains(normalized)) {
            continue;
          }
          next.add(cost);
          added.add(cost);
          existingNames.add(normalized);
        }
        if (added.isEmpty) return 0;
        next.sort(_compareRecurringFixedCostsByPaymentDay);
        await _commitRecurringFixedCostReadditionsNow(
          previous: previous,
          next: next,
          ids: added.map((cost) => cost.id).toSet(),
        );
        return added.length;
      },
    );
    if (!mounted) return;
    if (addedCount == 0) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('追加できる新しいサブスクはありませんでした。')));
      return;
    }
    ScaffoldMessenger.of(
      context,
    ).showSnackBar(SnackBar(content: Text('$addedCount件のサブスクを棚卸しに追加しました。')));
  }

  String _normalizeSubscriptionName(String value) {
    return value.toLowerCase().replaceAll(RegExp(r'[\s\-_./・（）()]+'), '');
  }

  /// `_recentFlows`(複数月分の収支履歴)から、支出のみを description パースして
  /// 定期取引検出用の観測列を作る。
  List<RecurringTransactionObservation>
      _buildRecurringTransactionObservations() {
    final observations = <RecurringTransactionObservation>[];
    for (final flow in _recentFlows) {
      final actionType = flow['action_type']?.toString() ?? '';
      if (!_isExpenseActionType(actionType)) {
        continue;
      }
      final occurredAt = DateTime.tryParse(
        flow['occurred_at']?.toString() ?? '',
      )?.toLocal();
      if (occurredAt == null) {
        continue;
      }
      final amount = ((flow['amount'] as num?)?.toDouble() ?? 0).abs().round();
      if (amount <= 0) {
        continue;
      }
      final parsed = _parseFlowDescription(
        flow['description']?.toString() ?? '',
        actionType: actionType,
      );
      final label = AssetRecurringTransactionDetector.buildLabel(
        source: parsed.source,
        memo: parsed.memo,
      );
      if (label.isEmpty) {
        continue;
      }
      observations.add(
        RecurringTransactionObservation(
          label: label,
          amount: amount,
          occurredAt: occurredAt,
          sourceName: AssetRecurringTransactionDetector.stripAccountBrackets(
            parsed.source,
          ),
        ),
      );
    }
    return observations;
  }

  /// 定期取引を検出し、登録済み固定費と「無視」した候補を除外する。
  List<DetectedRecurringTransaction> _detectRecurringTransactions() {
    final detected = AssetRecurringTransactionDetector.detect(
      observations: _buildRecurringTransactionObservations(),
      asOf: _now,
    );
    if (detected.isEmpty) {
      return detected;
    }
    final registered = <String>{
      for (final cost in _recurringFixedCosts)
        _normalizeRecurringLabel(cost.name),
    }..removeWhere((name) => name.isEmpty);
    return detected.where((item) {
      final label = _normalizeRecurringLabel(item.label);
      if (label.isEmpty) {
        return true;
      }
      if (_ignoredRecurringLabels.contains(label)) {
        return false;
      }
      for (final name in registered) {
        if (label.contains(name) || name.contains(label)) {
          return false;
        }
      }
      return true;
    }).toList();
  }

  String _normalizeRecurringLabel(String value) =>
      value.replaceAll(RegExp(r'\s+'), '').toLowerCase();

  /// 検出された定期取引を `prefill` として固定費登録ダイアログを開く。
  /// 周期(毎月/隔月)と最頻の引落元口座も初期値に反映する。
  Future<void> _registerDetectedRecurringTransaction(
    DetectedRecurringTransaction detected, {
    required List<RecurringFixedCostSourceOption> sourceOptions,
  }) {
    final suggestedSource = detected.suggestedSourceName;
    String? sourceAccountId;
    if (suggestedSource != null) {
      for (final option in sourceOptions) {
        if (option.name == suggestedSource) {
          sourceAccountId = option.id;
          break;
        }
      }
    }
    final draft = AssetRecurringFixedCost(
      id: 'fc_suggestion',
      name: detected.label,
      amount: detected.typicalAmount.toDouble(),
      paymentDay: detected.typicalPaymentDay,
      cadence: detected.cadence,
      sourceAccountId: sourceAccountId,
    );
    return _openRecurringFixedCostEditor(
      prefill: draft,
      sourceOptions: sourceOptions,
    );
  }

  Widget _buildRecurringTransactionSuggestionCard(
    AssetLiabilityWorkbook? workbook,
  ) {
    final accounts = workbook?.accounts ?? const <AssetLiabilityAccount>[];
    final sourceOptions = recurringFixedCostSourceOptions(accounts);
    return AssetRecurringTransactionSuggestionCard(
      suggestions: _detectRecurringTransactions(),
      currencyFormatter: _formatYen,
      onRegister: (detected) => unawaited(
        _registerDetectedRecurringTransaction(
          detected,
          sourceOptions: sourceOptions,
        ),
      ),
      onIgnore: _ignoreDetectedRecurringTransaction,
    );
  }

  /// `_recentFlows` の入金(action_type == 'conquer')を定期取引検出用の観測列にする。
  List<RecurringTransactionObservation> _buildRecurringIncomeObservations() {
    final observations = <RecurringTransactionObservation>[];
    for (final flow in _recentFlows) {
      final actionType = flow['action_type']?.toString() ?? '';
      if (!_isIncomeActionType(actionType)) {
        continue;
      }
      final occurredAt = DateTime.tryParse(
        flow['occurred_at']?.toString() ?? '',
      )?.toLocal();
      if (occurredAt == null) {
        continue;
      }
      final amount = ((flow['amount'] as num?)?.toDouble() ?? 0).abs().round();
      if (amount <= 0) {
        continue;
      }
      final parsed = _parseFlowDescription(
        flow['description']?.toString() ?? '',
        actionType: actionType,
      );
      final label = AssetRecurringTransactionDetector.buildLabel(
        source: parsed.source,
        memo: parsed.memo,
      );
      if (label.isEmpty) {
        continue;
      }
      observations.add(
        RecurringTransactionObservation(
          label: label,
          amount: amount,
          occurredAt: occurredAt,
          // 入金の `[口座名]` は入金先口座 → destination prefill に使う。
          sourceName: AssetRecurringTransactionDetector.stripAccountBrackets(
            parsed.source,
          ),
        ),
      );
    }
    return observations;
  }

  /// 定期入金を検出し、登録済みの定期収入テンプレと一致するものは除外する。
  List<DetectedRecurringTransaction> _detectRecurringIncome() {
    final detected = AssetRecurringTransactionDetector.detect(
      observations: _buildRecurringIncomeObservations(),
      asOf: _now,
    );
    if (detected.isEmpty) {
      return detected;
    }
    final registered = <String>{
      for (final template in _recurringIncomeTemplates)
        _normalizeRecurringLabel(template.name),
    }..removeWhere((name) => name.isEmpty);
    return detected.where((item) {
      final label = _normalizeRecurringLabel(item.label);
      if (label.isEmpty) {
        return true;
      }
      if (_ignoredRecurringIncomeLabels.contains(label)) {
        return false;
      }
      for (final name in registered) {
        if (label.contains(name) || name.contains(label)) {
          return false;
        }
      }
      return true;
    }).toList();
  }

  /// 検出された定期入金を `prefill` として定期収入テンプレ追加ダイアログを開く。
  /// 最頻の入金先口座を destination に反映する。
  Future<void> _registerDetectedRecurringIncome(
    DetectedRecurringTransaction detected,
    AssetLiabilityWorkbook workbook,
  ) {
    final suggestedSource = detected.suggestedSourceName;
    String? destinationAccountId;
    String? destinationAccountName;
    if (suggestedSource != null) {
      final options = incomeDestinationAccountOptions(workbook.accounts);
      for (final account in options) {
        if (account.name == suggestedSource) {
          destinationAccountId = account.id;
          destinationAccountName = account.name;
          break;
        }
      }
    }
    final draft = AssetLiabilityRecurringIncomeTemplate(
      id: 'income_template_suggestion',
      dayOfMonth: detected.typicalPaymentDay,
      name: detected.label,
      amount: detected.typicalAmount.toDouble(),
      destinationAccountId: destinationAccountId,
      destinationAccountName: destinationAccountName,
    );
    return _showRecurringIncomeTemplateDialog(workbook, prefill: draft);
  }

  Widget _buildRecurringIncomeSuggestionCard(AssetLiabilityWorkbook? workbook) {
    if (workbook == null) {
      return const SizedBox.shrink();
    }
    return AssetRecurringTransactionSuggestionCard(
      keyPrefix: 'asset_recurring_income',
      title: '定期収入の自動検出',
      description: '過去の入金から繰り返しを検出しました。定期収入に登録すると将来予測に反映されます。',
      registerLabel: '定期収入に登録',
      suggestions: _detectRecurringIncome(),
      currencyFormatter: _formatYen,
      onRegister: (detected) =>
          unawaited(_registerDetectedRecurringIncome(detected, workbook)),
      onIgnore: _ignoreDetectedRecurringIncome,
    );
  }

