  Widget _buildAssetLiabilityConflictResolutionSection(
    AssetLiabilitySyncPreviewResult preview,
  ) {
    final conflictItems =
        preview.items.where((item) => item.conflict).toList(growable: false);
    if (conflictItems.isEmpty) {
      return const SizedBox.shrink();
    }

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: const Color(0xFFFFFBEB),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(
          color: const Color(0xFFF59E0B).withValues(alpha: 0.35),
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Icon(
                Icons.rule_folder_outlined,
                size: 16,
                color: Color(0xFFD97706),
              ),
              const SizedBox(width: 6),
              const Expanded(
                child: Text(
                  '同期競合の解決',
                  style: TextStyle(fontWeight: FontWeight.w700, height: 1.4),
                ),
              ),
              if (_isResolvingAssetLiabilityConflict)
                const SizedBox(
                  width: 16,
                  height: 16,
                  child: CircularProgressIndicator(strokeWidth: 2),
                ),
            ],
          ),
          const SizedBox(height: 8),
          const Text(
            'ローカルとSupabaseの両方にデータがある項目は自動上書きしません。'
            'どちらを優先するか明示的に選んだ項目だけRepository経由で反映します。',
            style: TextStyle(fontSize: 12, height: 1.5),
          ),
          const SizedBox(height: 8),
          for (final item in conflictItems) ...[
            _buildAssetLiabilityConflictResolutionTile(item),
            if (item != conflictItems.last) const SizedBox(height: 8),
          ],
        ],
      ),
    );
  }

  Widget _buildAssetLiabilityConflictResolutionTile(
    AssetLiabilitySyncPreviewItem item,
  ) {
    final disabled = _isResolvingAssetLiabilityConflict ||
        _isRunningAssetLiabilitySync ||
        _isPreviewingAssetLiabilitySync;

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(8),
      decoration: BoxDecoration(
        color: Theme.of(context).colorScheme.surface,
        borderRadius: BorderRadius.circular(8),
        border: Border.all(
          color: const Color(0xFFF59E0B).withValues(alpha: 0.28),
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Wrap(
            spacing: 6,
            runSpacing: 6,
            crossAxisAlignment: WrapCrossAlignment.center,
            children: [
              _buildAssetLiabilitySyncChip(
                label: '対象',
                value: item.targetName,
                color: const Color(0xFFD97706),
              ),
              _buildAssetLiabilitySyncChip(
                label: 'ローカル',
                value: '${item.localCount}件',
                color: const Color(0xFF475569),
              ),
              _buildAssetLiabilitySyncChip(
                label: 'Supabase',
                value: '${item.remoteCount}件',
                color: const Color(0xFF475569),
              ),
            ],
          ),
          const SizedBox(height: 8),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              OutlinedButton.icon(
                onPressed: disabled
                    ? null
                    : () => _resolveAssetLiabilitySyncConflict(
                          item: item,
                          choice:
                              AssetLiabilityConflictResolutionChoice.localWins,
                        ),
                icon: const Icon(Icons.upload_file_outlined),
                label: const Text('ローカル優先'),
              ),
              OutlinedButton.icon(
                onPressed: disabled
                    ? null
                    : () => _resolveAssetLiabilitySyncConflict(
                          item: item,
                          choice: AssetLiabilityConflictResolutionChoice
                              .supabaseWins,
                        ),
                icon: const Icon(Icons.cloud_download_outlined),
                label: const Text('Supabase優先'),
              ),
              TextButton.icon(
                onPressed: disabled
                    ? null
                    : () => _resolveAssetLiabilitySyncConflict(
                          item: item,
                          choice: AssetLiabilityConflictResolutionChoice.skip,
                        ),
                icon: const Icon(Icons.block_outlined),
                label: const Text('今回はスキップ'),
              ),
            ],
          ),
        ],
      ),
    );
  }

  String _assetLiabilitySyncPreviewItemLabel(
    AssetLiabilitySyncPreviewItem item,
  ) {
    if (item.conflict) {
      return '競合';
    }
    if (item.uploadCandidate) {
      return 'アップロード候補';
    }
    if (item.downloadCandidate) {
      return 'ダウンロード候補';
    }
    return '差分なし';
  }

  Color _assetLiabilitySyncPreviewItemColor(
    AssetLiabilitySyncPreviewItem item,
  ) {
    if (item.conflict) {
      return const Color(0xFFD97706);
    }
    if (item.uploadCandidate) {
      return const Color(0xFF2563EB);
    }
    if (item.downloadCandidate) {
      return const Color(0xFF0D9488);
    }
    return Theme.of(context).colorScheme.outline;
  }

  Widget _buildAssetLiabilitySyncChip({
    required String label,
    required String value,
    required Color color,
  }) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.10),
        borderRadius: BorderRadius.circular(999),
        border: Border.all(color: color.withValues(alpha: 0.32)),
      ),
      child: Text(
        '$label: $value',
        style: TextStyle(
          color: color,
          fontSize: 12,
          fontWeight: FontWeight.w700,
          height: 1.2,
        ),
      ),
    );
  }

  Widget _buildDrinkChallengeCard(AssetLiabilityWorkbook workbook) {
    const service = DrinkChallengeService();
    final stats = service.computeStats(
      records: _drinkRecords,
      totalDebtYen: workbook.liabilityTotal,
      baseDate: _now,
    );
    final occasions = service.occasionsBetween(
      _now.subtract(const Duration(days: 7)),
      _now.add(const Duration(days: 21)),
    );
    final projected = stats.projectedCompletionDate;

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: const Color(0xFFF8FAFC),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(
          color: const Color(0xFF7C3AED).withValues(alpha: 0.24),
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Row(
            children: [
              Icon(
                Icons.no_drinks_outlined,
                color: Color(0xFF7C3AED),
                size: 20,
              ),
              SizedBox(width: 8),
              Expanded(
                child: Text(
                  '禁酒で借金完済チャレンジ',
                  style: TextStyle(fontWeight: FontWeight.bold, height: 1.4),
                ),
              ),
            ],
          ),
          const SizedBox(height: 4),
          Text(
            '金土日の夜・祝前日・祝日に飲みを我慢するたびに'
            ' ${_formatManagementYen(stats.perSessionYen)} 節約。'
            '${stats.targetCount}回我慢すれば完済です。',
            style: TextStyle(
              fontSize: 11,
              color: Theme.of(context).colorScheme.onSurfaceVariant,
              height: 1.5,
            ),
          ),
          const SizedBox(height: 10),
          ClipRRect(
            borderRadius: BorderRadius.circular(6),
            child: LinearProgressIndicator(
              value: stats.progressRatio,
              minHeight: 10,
              backgroundColor: const Color(0xFFE2E8F0),
              valueColor: const AlwaysStoppedAnimation<Color>(
                Color(0xFF7C3AED),
              ),
            ),
          ),
          const SizedBox(height: 10),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              _buildOverviewStatChip(
                label: '我慢した回数',
                value: '${stats.abstainedCount} / ${stats.targetCount}回',
                color: const Color(0xFF7C3AED),
              ),
              _buildOverviewStatChip(
                label: '節約できた額',
                value: _formatManagementYen(stats.savedYen),
                color: const Color(0xFF0D9488),
              ),
              _buildOverviewStatChip(
                label: '完済まで残り',
                value: '${stats.remainingCount}回',
                color: const Color(0xFFB91C1C),
              ),
              if (projected != null)
                _buildOverviewStatChip(
                  label: '全部我慢すれば',
                  value: '${projected.year}年${projected.month}月頃',
                  color: const Color(0xFF2563EB),
                ),
              if (stats.drankCount > 0)
                _buildOverviewStatChip(
                  label: '我慢率',
                  value: _formatManagementPercent(stats.abstentionRate),
                  color: const Color(0xFF64748B),
                ),
            ],
          ),
          const SizedBox(height: 12),
          Text(
            '飲み機会（直近1週間〜今後3週間）— 各回をタップして記録',
            style: TextStyle(
              fontSize: 11,
              fontWeight: FontWeight.w600,
              color: Theme.of(context).colorScheme.onSurfaceVariant,
            ),
          ),
          const SizedBox(height: 6),
          for (final occasion in occasions) _buildDrinkOccasionRow(occasion),
        ],
      ),
    );
  }

  Widget _buildDrinkOccasionRow(DrinkOccasion occasion) {
    final key = DrinkChallengeService.dateKey(occasion.date);
    final status = _drinkRecords[key];
    const weekdays = ['月', '火', '水', '木', '金', '土', '日'];
    final weekday = weekdays[occasion.date.weekday - 1];
    final isToday = occasion.date.year == _now.year &&
        occasion.date.month == _now.month &&
        occasion.date.day == _now.day;
    final isHoliday = occasion.reasons.contains(DrinkOccasionReason.holiday);
    final isHolidayEve = occasion.reasons.contains(
      DrinkOccasionReason.holidayEve,
    );
    final badge = isHoliday ? '祝' : (isHolidayEve ? '祝前' : '');

    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 3),
      child: Row(
        children: [
          Text(
            '${occasion.date.month}/${occasion.date.day}($weekday)',
            style: TextStyle(
              fontSize: 12,
              fontWeight: isToday ? FontWeight.bold : FontWeight.normal,
              color: isToday ? const Color(0xFF7C3AED) : null,
            ),
          ),
          if (badge.isNotEmpty) ...[
            const SizedBox(width: 4),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 1),
              decoration: BoxDecoration(
                color: const Color(0xFFB91C1C).withValues(alpha: 0.12),
                borderRadius: BorderRadius.circular(4),
              ),
              child: Text(
                badge,
                style: const TextStyle(fontSize: 10, color: Color(0xFFB91C1C)),
              ),
            ),
          ],
          const Spacer(),
          _buildDrinkChoiceButton(
            label: '我慢した',
            selected: status == DrinkRecordStatus.abstained,
            selectedColor: const Color(0xFF0D9488),
            onTap: () => _setDrinkRecord(
              occasion.date,
              status == DrinkRecordStatus.abstained
                  ? null
                  : DrinkRecordStatus.abstained,
            ),
          ),
          const SizedBox(width: 6),
          _buildDrinkChoiceButton(
            label: '飲んだ',
            selected: status == DrinkRecordStatus.drank,
            selectedColor: const Color(0xFFB91C1C),
            onTap: () => _setDrinkRecord(
              occasion.date,
              status == DrinkRecordStatus.drank
                  ? null
                  : DrinkRecordStatus.drank,
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildDrinkChoiceButton({
    required String label,
    required bool selected,
    required Color selectedColor,
    required VoidCallback onTap,
  }) {
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(6),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
        decoration: BoxDecoration(
          color: selected ? selectedColor : Colors.transparent,
          borderRadius: BorderRadius.circular(6),
          border: Border.all(
            color: selected ? selectedColor : const Color(0xFFCBD5E1),
          ),
        ),
        child: Text(
          label,
          style: TextStyle(
            fontSize: 11,
            fontWeight: FontWeight.w600,
            color: selected ? Colors.white : const Color(0xFF64748B),
          ),
        ),
      ),
    );
  }

