  Widget _buildAssetManagementAiSummaryPanel(
    AssetManagementInsightReport report,
  ) {
    final enabled = _assetManagementAiSummaryService.aiEnabled;
    if (enabled) {
      _requestAssetManagementAiSummaryIfNeeded(report);
    }
    final developerRequests = _combinedDeveloperRequests(report);
    _requestExistingDeveloperIssuesIfNeeded(developerRequests);
    final result = _assetManagementAiSummaryResult ??
        (enabled
            ? _assetManagementAiSummaryService.buildWaitingForAiResult(report)
            : _assetManagementAiSummaryService.buildDisabledResult(report));
    final color = switch (result.status) {
      AssetManagementAiSummaryStatus.aiGenerated => const Color(0xFF0D9488),
      AssetManagementAiSummaryStatus.fallback => const Color(0xFFD97706),
      AssetManagementAiSummaryStatus.disabled => const Color(0xFF475569),
    };
    final statusLabel = switch (result.status) {
      AssetManagementAiSummaryStatus.aiGenerated => 'AI要約',
      AssetManagementAiSummaryStatus.fallback => '定型要約',
      AssetManagementAiSummaryStatus.disabled => 'AI無効',
    };
    final issueableDeveloperRequests = _issueableDeveloperRequests(
      developerRequests,
    );
    final canCopySummary = result.text.trim().isNotEmpty;

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.08),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: color.withValues(alpha: 0.24)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Icon(Icons.psychology_alt_outlined, color: color, size: 18),
              const SizedBox(width: 8),
              Expanded(
                child: _buildAssetManagementAiSummaryMarkdown(
                  result.text,
                  color,
                ),
              ),
            ],
          ),
          if (result.errorMessage != null) ...[
            const SizedBox(height: 6),
            Text(
              result.errorMessage!,
              style: TextStyle(
                color: Theme.of(context).colorScheme.error,
                fontSize: 11,
                height: 1.4,
              ),
            ),
          ],
          const SizedBox(height: 8),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            crossAxisAlignment: WrapCrossAlignment.center,
            children: [
              _buildAssetLiabilitySyncChip(
                label: 'AI',
                value: statusLabel,
                color: color,
              ),
              _buildAssetLiabilitySyncChip(
                label: 'ソース',
                value: _localizedAssetManagementAiSource(result.source),
                color: color,
              ),
              // 生成はページを止めずに裏で走り、完了時にカード本文が差し替わる。
              // 何の予告もなく本文が変わると戸惑うため、生成中であることと
              // 目安時間をカード内に明示する (ボタン内の小さなスピナーだけでは
              // 気づけない / 本文は今もルールベース要約として読める旨も伝える)。
              if (_isGeneratingAssetManagementAiSummary)
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 10,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    color: color.withValues(alpha: 0.10),
                    borderRadius: BorderRadius.circular(999),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      SizedBox(
                        width: 12,
                        height: 12,
                        child: CircularProgressIndicator(
                          strokeWidth: 2,
                          valueColor: AlwaysStoppedAnimation<Color>(color),
                        ),
                      ),
                      const SizedBox(width: 8),
                      Text(
                        'AI分析を生成中… (1分ほど) 完了すると上の要約が更新されます',
                        style: TextStyle(
                          color: color,
                          fontSize: 11,
                          fontWeight: FontWeight.w800,
                          height: 1.5,
                        ),
                      ),
                    ],
                  ),
                ),
              if (_assetManagementAiSummaryReferencedHistory.isNotEmpty)
                _buildAssetLiabilitySyncChip(
                  label: '履歴参照',
                  value:
                      '${_assetManagementAiSummaryReferencedHistory.length}件',
                  color: color,
                ),
              OutlinedButton.icon(
                onPressed: canCopySummary
                    ? () => _copyAssetManagementAiSummary(result)
                    : null,
                icon: const Icon(Icons.content_copy_outlined, size: 16),
                label: const Text('分析結果をコピー'),
              ),
              OutlinedButton.icon(
                onPressed: enabled && !_isGeneratingAssetManagementAiSummary
                    ? () =>
                        _generateAssetManagementAiSummary(report, force: true)
                    : null,
                icon: _isGeneratingAssetManagementAiSummary
                    ? const SizedBox(
                        width: 14,
                        height: 14,
                        child: CircularProgressIndicator(strokeWidth: 2),
                      )
                    : const Icon(Icons.auto_awesome_outlined, size: 16),
                label: Text(enabled ? 'AI要約を更新' : 'AI要約は機能フラグで無効です'),
              ),
              if (developerRequests.isNotEmpty)
                OutlinedButton.icon(
                  onPressed: _isSubmittingAllDeveloperIssues ||
                          _isCheckingExistingDeveloperRequestIssues ||
                          issueableDeveloperRequests.isEmpty
                      ? null
                      : () => _submitAssetManagementDeveloperIssues(
                            developerRequests,
                          ),
                  icon: _isSubmittingAllDeveloperIssues
                      ? const SizedBox(
                          width: 14,
                          height: 14,
                          child: CircularProgressIndicator(strokeWidth: 2),
                        )
                      : const Icon(Icons.add_task_outlined, size: 16),
                  label: Text(
                    _developerIssuesBulkButtonLabel(issueableDeveloperRequests),
                  ),
                ),
            ],
          ),
          const SizedBox(height: 6),
          Text(
            'AIにはプロフィール、口座名、残高、支払予定、支払原資、利率、月利息、負債割合、現実装コンテキストを含む詳細ペイロードを渡します。',
            style: TextStyle(
              color: Theme.of(context).colorScheme.onSurfaceVariant,
              fontSize: 11,
              height: 1.4,
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildAssetManagementAiSummaryMarkdown(String text, Color color) {
    final theme = Theme.of(context);
    final base = theme.textTheme.bodySmall?.copyWith(
          color: theme.colorScheme.onSurface,
          fontSize: 12,
          height: 1.5,
        ) ??
        const TextStyle(fontSize: 12, height: 1.5);
    final heading = base.copyWith(
      color: color,
      fontWeight: FontWeight.w800,
      fontSize: 13,
      height: 1.35,
    );

    return SelectionArea(
      child: MarkdownBody(
        data: text,
        softLineBreak: true,
        styleSheet: MarkdownStyleSheet.fromTheme(theme).copyWith(
          p: base,
          strong: base.copyWith(fontWeight: FontWeight.w800),
          h1: heading.copyWith(fontSize: 14),
          h2: heading,
          h3: heading.copyWith(fontSize: 12.5),
          listBullet: base.copyWith(color: color, fontWeight: FontWeight.w700),
          blockquote: base.copyWith(color: theme.colorScheme.onSurfaceVariant),
          blockquoteDecoration: BoxDecoration(
            border: Border(
              left: BorderSide(color: color.withValues(alpha: 0.45), width: 3),
            ),
          ),
          horizontalRuleDecoration: BoxDecoration(
            border: Border(
              top: BorderSide(
                color: theme.colorScheme.outlineVariant,
                width: 1,
              ),
            ),
          ),
        ),
      ),
    );
  }

  String _localizedAssetManagementAiSource(String source) {
    return switch (source) {
      'deterministic fallback / feature flag off' => 'ルールベース要約 / AI無効',
      'deterministic fallback / ai-hub failed' => 'ルールベース要約 / AI接続失敗',
      'deterministic fallback / grounding validation failed' =>
        'ルールベース要約 / AIデータ矛盾を検出',
      'deterministic fallback / waiting for ai-hub' => 'ルールベース要約 / AI応答待ち',
      _ => source
          .replaceAll('deterministic fallback', 'ルールベース要約')
          .replaceAll('feature flag off', 'AI無効')
          .replaceAll('ai-hub failed', 'AI接続失敗')
          .replaceAll('waiting for ai-hub', 'AI応答待ち'),
    };
  }

  Future<void> _copyAssetManagementAiSummary(
    AssetManagementAiSummaryResult result,
  ) async {
    final text = result.text.trim();
    if (text.isEmpty) {
      return;
    }
    await Clipboard.setData(ClipboardData(text: text));
    if (!mounted) {
      return;
    }
    ScaffoldMessenger.of(
      context,
    ).showSnackBar(const SnackBar(content: Text('AI分析結果をコピーしました')));
  }

  Future<void> _generateAssetManagementAiSummary(
    AssetManagementInsightReport report, {
    String? requestKey,
    bool force = false,
  }) async {
    final key = requestKey ?? _assetManagementAiSummaryKey(report);
    if (_assetManagementAiSummaryInFlightKey == key) {
      return;
    }
    if (!force &&
        !AssetManagementAiSummaryRefresh.isStale(
          currentKey: key,
          resultKey: _assetManagementAiSummaryResultKey,
          hasResult: _assetManagementAiSummaryResult != null,
        )) {
      return;
    }
    setState(() {
      _isGeneratingAssetManagementAiSummary = true;
      _assetManagementAiSummaryInFlightKey = key;
      _assetManagementAiSummaryRequestKey = key;
    });
    // 保存済み分析は指紋が完全一致するときだけ再利用する。基準日が同じでも
    // 支払済み・金利・残高・解約状態のどれかが変われば別の事実なので、生成時刻が
    // 新しいことを理由に古い本文を現在キーへ付け替えてはならない。
    // 手動の「AI要約を更新」(force) は常に再生成する。
    if (!force) {
      AssetManagementAiAnalysisHistoryEntry? reusable;
      try {
        final latest = await _latestAssetManagementAiAnalysisForBaseDate(
          report.workbook.baseDate,
        );
        if (latest != null &&
            AssetManagementAiSummaryRefresh.canReusePersisted(
              currentKey: key,
              cachedKey: latest.requestFingerprint,
            )) {
          reusable = latest;
        }
      } catch (_) {
        reusable = null;
      }
      if (!mounted || _assetManagementAiSummaryInFlightKey != key) {
        return;
      }
      if (reusable != null) {
        final cached = reusable;
        setState(() {
          _assetManagementAiSummaryResult = AssetManagementAiSummaryResult(
            status: AssetManagementAiSummaryStatus.aiGenerated,
            text: cached.summaryText,
            source: cached.source,
            errorMessage: null,
            generatedAt: cached.generatedAt,
            payload: const <String, dynamic>{},
            providerRoute:
                cached.providerRoute.isEmpty ? null : cached.providerRoute,
            providerChoiceReason: cached.providerChoiceReason,
          );
          _assetManagementAiSummaryResultKey = key;
          _isGeneratingAssetManagementAiSummary = false;
          _assetManagementAiSummaryInFlightKey = null;
          _assetManagementAiSummaryRequestKey = key;
        });
        return;
      }
      // 成功再利用が無くても、直近の試行 (失敗含む) からクールダウン内なら生成を
      // 見送る。500 等の失敗は履歴に保存されないため、これが無いと AI 障害中は
      // 毎ロード/編集で 1 分超の直列生成が走り続ける。見送り時は結果を空のままに
      // し、パネルは定型要約 (buildWaitingForAiResult) を表示する。
      final sinceLastAttempt = await _sinceLastAssetManagementAiSummaryAttempt(
        report.workbook.baseDate,
      );
      if (!mounted || _assetManagementAiSummaryInFlightKey != key) {
        return;
      }
      if (AssetManagementAiSummaryRefresh.shouldThrottleFailedRetry(
        force: force,
        sinceLastAttempt: sinceLastAttempt,
        cooldown: _assetManagementAiSummaryAutoRefreshCooldown,
      )) {
        setState(() {
          _isGeneratingAssetManagementAiSummary = false;
          _assetManagementAiSummaryInFlightKey = null;
          // requestKey は key のままにして同一指紋の再スケジュールを防ぐ。
        });
        return;
      }
    }
    var previousAnalyses = const <AssetManagementAiAnalysisHistoryEntry>[];
    try {
      previousAnalyses =
          await _assetManagementAiAnalysisHistoryService.loadRecent(limit: 5);
    } catch (_) {
      previousAnalyses = const <AssetManagementAiAnalysisHistoryEntry>[];
    }
    if (!mounted || _assetManagementAiSummaryInFlightKey != key) {
      return;
    }
    // 初回自動生成が既存Issue照合より先に走ると already_issued が
    // 空のままAIへ渡り再掲抑止が効かないため、照合完了を待つ。
    await _ensureExistingDeveloperIssuesLoaded(report.developerRequests);
    if (!mounted || _assetManagementAiSummaryInFlightKey != key) {
      return;
    }
    final existingIssuesByTitle = <String, Map<String, dynamic>>{};
    for (final request in report.developerRequests) {
      final existing =
          _developerRequestExistingIssueResults[_developerRequestIssueKey(
        request,
      )];
      if (existing != null) {
        existingIssuesByTitle[request.title] = Map<String, dynamic>.from(
          existing,
        );
      }
    }
    final result = await _assetManagementAiSummaryService.generateSummary(
      report: report,
      previousAnalyses: previousAnalyses,
      existingDeveloperIssuesByTitle: existingIssuesByTitle,
    );
    if (result.usedExternalAi) {
      // 成功は失敗リトライのクールダウン対象にしない。データ指紋が変わったら
      // 直ちに最新値で再生成できるよう、過去の失敗時刻も消す。
      unawaited(_clearAssetManagementAiSummaryAttempt());
      try {
        await _assetManagementAiAnalysisHistoryService.saveResult(
          result: result,
          report: report,
          requestFingerprint: key,
        );
        // 新しい分析を保存したので「同日最新」キャッシュを無効化する
        // (次回プローブが最新行を取り直し、再利用/クールダウン判定に反映)。
        _invalidateAssetManagementLatestForBaseDateCache();
      } catch (_) {
        // AI分析の表示を優先し、履歴保存失敗は次回の再試行に任せます。
      }
    } else {
      // AI接続失敗または整合性検証失敗だけを連続試行の抑止対象にする。
      unawaited(
        _recordAssetManagementAiSummaryAttempt(report.workbook.baseDate),
      );
    }
    if (!mounted) {
      return;
    }
    if (_assetManagementAiSummaryInFlightKey != key) {
      return;
    }
    setState(() {
      _assetManagementAiSummaryResult = result;
      _assetManagementAiSummaryResultKey = key;
      _assetManagementAiSummaryReferencedHistory = previousAnalyses;
      _isGeneratingAssetManagementAiSummary = false;
      _assetManagementAiSummaryInFlightKey = null;
      _assetManagementAiSummaryRequestKey = key;
    });
  }

  /// 同一基準日の「保存済み最新分析」を返す (セッション内キャッシュ優先)。
  /// 指紋が変わる度に呼ばれるが、同一基準日ではキャッシュを返して DB 往復を
  /// 省く。キャッシュ未ロード or 基準日変化時のみ実フェッチする。
  Future<AssetManagementAiAnalysisHistoryEntry?>
      _latestAssetManagementAiAnalysisForBaseDate(DateTime baseDate) async {
    final baseKey = AssetManagementAiAnalysisHistoryService.reportBaseDateKey(
      baseDate,
    );
    if (_assetManagementLatestForBaseDateCacheLoaded &&
        _assetManagementLatestForBaseDateCacheKey == baseKey) {
      return _assetManagementLatestForBaseDateCache;
    }
    final latest = await _assetManagementAiAnalysisHistoryService
        .loadLatestForBaseDate(reportBaseDate: baseKey);
    _assetManagementLatestForBaseDateCacheKey = baseKey;
    _assetManagementLatestForBaseDateCache = latest;
    _assetManagementLatestForBaseDateCacheLoaded = true;
    return latest;
  }

  void _invalidateAssetManagementLatestForBaseDateCache() {
    _assetManagementLatestForBaseDateCacheLoaded = false;
    _assetManagementLatestForBaseDateCache = null;
    _assetManagementLatestForBaseDateCacheKey = null;
  }

  /// 直近の AI 要約生成試行からの経過時間。基準日が変われば null を返し
  /// (別日は再試行可)、記録が無い場合も null。端末ローカルの best-effort。
  Future<Duration?> _sinceLastAssetManagementAiSummaryAttempt(
    DateTime baseDate,
  ) async {
    try {
      final store = await SharedPreferences.getInstance();
      final raw = store.getString(_assetManagementAiSummaryLastAttemptPrefKey);
      if (raw == null) {
        return null;
      }
      final sep = raw.indexOf('|');
      if (sep <= 0) {
        return null;
      }
      final storedBaseKey = raw.substring(0, sep);
      final currentBaseKey =
          AssetManagementAiAnalysisHistoryService.reportBaseDateKey(baseDate);
      if (storedBaseKey != currentBaseKey) {
        return null;
      }
      final at = DateTime.tryParse(raw.substring(sep + 1));
      if (at == null) {
        return null;
      }
      final delta = DateTime.now().difference(at);
      return delta.isNegative ? Duration.zero : delta;
    } catch (_) {
      return null;
    }
  }

  Future<void> _clearAssetManagementAiSummaryAttempt() async {
    try {
      final store = await SharedPreferences.getInstance();
      await store.remove(_assetManagementAiSummaryLastAttemptPrefKey);
    } catch (_) {
      // best-effort の失敗クールダウン用途のため、削除失敗は致命ではない。
    }
  }

  Future<void> _recordAssetManagementAiSummaryAttempt(DateTime baseDate) async {
    try {
      final store = await SharedPreferences.getInstance();
      final baseKey = AssetManagementAiAnalysisHistoryService.reportBaseDateKey(
        baseDate,
      );
      await store.setString(
        _assetManagementAiSummaryLastAttemptPrefKey,
        '$baseKey|${DateTime.now().toIso8601String()}',
      );
    } catch (_) {
      // best-effort のスロットリング用途のため、永続化失敗は致命ではない。
    }
  }

  void _requestAssetManagementAiSummaryIfNeeded(
    AssetManagementInsightReport report,
  ) {
    if (!_assetManagementAiSummaryService.aiEnabled ||
        _isGeneratingAssetManagementAiSummary) {
      return;
    }
    final key = _assetManagementAiSummaryKey(report);
    if (_assetManagementAiSummaryRequestKey == key ||
        _assetManagementAiSummaryInFlightKey == key) {
      return;
    }
    if (!AssetManagementAiSummaryRefresh.isStale(
      currentKey: key,
      resultKey: _assetManagementAiSummaryResultKey,
      hasResult: _assetManagementAiSummaryResult != null,
    )) {
      return;
    }
    // requestKey は即時に確定する。これにより同一 key の後続リビルドは冒頭の
    // 重複ガード (requestKey == key) で early-return し、デバウンスタイマーを
    // 際限なく再スケジュールして発火しない (starvation) のを防ぐ。
    _assetManagementAiSummaryRequestKey = key;
    // デバウンス: 初期化時の連続リビルド (フィンガープリント毎回変化) で ai-hub を
    // 連打しないよう、key が変わる度に前タイマーを取り消し、リビルドが静止した最後の
    // key の 1 回だけ実発行する。窓は初期データロード (~2s で収束) を上回る長さにして、
    // 部分データでの先行生成 → 完了後に完全データで再生成、という二重発行を避ける
    // (重い/低速な ai-hub を 1 回に集約する)。
    _assetManagementAiSummaryDebounce?.cancel();
    _assetManagementAiSummaryDebounce = Timer(
      const Duration(milliseconds: 2500),
      () {
        if (!mounted) {
          return;
        }
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted ||
              !_assetManagementAiSummaryService.aiEnabled ||
              _isGeneratingAssetManagementAiSummary ||
              _assetManagementAiSummaryInFlightKey == key ||
              _assetManagementAiSummaryRequestKey != key) {
            return;
          }
          unawaited(_generateAssetManagementAiSummary(report, requestKey: key));
        });
      },
    );
  }

  String _assetManagementAiSummaryKey(AssetManagementInsightReport report) {
    return _assetManagementAiSummaryService.buildRequestFingerprint(report);
  }

  void _requestExistingDeveloperIssuesIfNeeded(
    List<AssetManagementDeveloperRequest> requests,
  ) {
    if (_supabase.auth.currentUser == null || requests.isEmpty) {
      return;
    }
    final payload = requests
        .map(_developerRequestExistingIssuePayload)
        .toList(growable: false);
    final lookupKey = jsonEncode(payload);
    if (_developerRequestExistingIssueLookupKey == lookupKey) {
      return;
    }
    _developerRequestExistingIssueLookupKey = lookupKey;
    _isCheckingExistingDeveloperRequestIssues = true;
    // デバウンス: 初期化時の連続リビルド (developer requests 変化) で core-hub の
    // 既存Issue照合を連打しないよう、リビルドが静止した最後の 1 回だけ実行する。窓は
    // 初期データロード (~2s) を上回る長さにして、部分データでの先行実行を避ける。
    // AI 要約生成前は _ensureExistingDeveloperIssuesLoaded が必要時に強制ロードするため
    // 注釈整合は保たれる。
    _existingDeveloperIssueLookupDebounce?.cancel();
    _existingDeveloperIssueLookupDebounce = Timer(
      const Duration(milliseconds: 2500),
      () {
        if (!mounted) {
          return;
        }
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted ||
              _developerRequestExistingIssueLookupKey != lookupKey) {
            return;
          }
          unawaited(
            _loadExistingDeveloperIssues(
              lookupKey: lookupKey,
              requests: payload,
            ),
          );
        });
      },
    );
  }

  /// 既存Issue照合の完了を待つ。未取得・取得中の場合はその場で照合を実行する。
  /// AI要約生成前に already_issued 注釈を確実に揃えるために使う。
  Future<void> _ensureExistingDeveloperIssuesLoaded(
    List<AssetManagementDeveloperRequest> requests,
  ) async {
    if (_supabase.auth.currentUser == null || requests.isEmpty) {
      return;
    }
    final payload = requests
        .map(_developerRequestExistingIssuePayload)
        .toList(growable: false);
    final lookupKey = jsonEncode(payload);
    if (_developerRequestExistingIssueLookupKey == lookupKey &&
        !_isCheckingExistingDeveloperRequestIssues) {
      return;
    }
    _developerRequestExistingIssueLookupKey = lookupKey;
    _isCheckingExistingDeveloperRequestIssues = true;
    await _loadExistingDeveloperIssues(lookupKey: lookupKey, requests: payload);
  }

  Map<String, String> _developerRequestExistingIssuePayload(
    AssetManagementDeveloperRequest request,
  ) {
    return <String, String>{
      'key': _developerRequestIssueKey(request),
      'title': request.title,
      'description': request.description,
    };
  }

  Future<void> _loadExistingDeveloperIssues({
    required String lookupKey,
    required List<Map<String, String>> requests,
  }) async {
    try {
      final response = await _supabase.functions.invoke(
        'core-hub',
        body: {
          'action': 'feature_request.existing_issues',
          'source': 'asset_management_developer_request',
          'requests': requests,
        },
      );
      if (!mounted || _developerRequestExistingIssueLookupKey != lookupKey) {
        return;
      }
      final rawData = response.data;
      final existingByKey = <String, Map<String, dynamic>>{};
      if (rawData is Map) {
        final existingIssues = rawData['existingIssues'];
        if (existingIssues is List) {
          for (final item in existingIssues) {
            final issue = _assetManagementDynamicMap(item);
            final key = issue['key']?.toString() ?? '';
            if (key.isNotEmpty) {
              existingByKey[key] = issue;
            }
          }
        }
      }
      setState(() {
        _developerRequestExistingIssueResults
          ..clear()
          ..addAll(existingByKey);
        _isCheckingExistingDeveloperRequestIssues = false;
      });
    } catch (_) {
      if (!mounted || _developerRequestExistingIssueLookupKey != lookupKey) {
        return;
      }
      setState(() {
        _developerRequestExistingIssueResults.clear();
        _isCheckingExistingDeveloperRequestIssues = false;
      });
    }
  }

  /// 定型生成の改善提案に、AI要約が返した未起票の新規提案を合流させる。
  List<AssetManagementDeveloperRequest> _combinedDeveloperRequests(
    AssetManagementInsightReport report,
  ) {
    final aiRequests = _assetManagementAiSummaryResult?.aiDeveloperRequests ??
        const <AssetManagementDeveloperRequest>[];
    if (aiRequests.isEmpty) {
      return report.developerRequests;
    }
    final knownKeys =
        report.developerRequests.map(_developerRequestIssueKey).toSet();
    return <AssetManagementDeveloperRequest>[
      ...report.developerRequests,
      for (final request in aiRequests)
        if (knownKeys.add(_developerRequestIssueKey(request))) request,
    ];
  }

  bool _isAiGeneratedDeveloperRequest(AssetManagementDeveloperRequest request) {
    final aiRequests = _assetManagementAiSummaryResult?.aiDeveloperRequests ??
        const <AssetManagementDeveloperRequest>[];
    if (aiRequests.isEmpty) {
      return false;
    }
    final key = _developerRequestIssueKey(request);
    return aiRequests.any(
      (candidate) => _developerRequestIssueKey(candidate) == key,
    );
  }

  List<AssetManagementDeveloperRequest> _issueableDeveloperRequests(
    List<AssetManagementDeveloperRequest> requests,
  ) {
    return requests.where((request) {
      final issueKey = _developerRequestIssueKey(request);
      if (_developerRequestExistingIssueResults.containsKey(issueKey)) {
        return false;
      }
      final result = _developerRequestIssueResults[issueKey];
      final githubIssue = _assetManagementDynamicMap(
        result?['githubIssue'],
      );
      return (githubIssue['html_url']?.toString() ?? '').isEmpty;
    }).toList(growable: false);
  }

  Future<void> _submitAssetManagementDeveloperIssues(
    List<AssetManagementDeveloperRequest> requests,
  ) async {
    if (_supabase.auth.currentUser == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('GitHub Issueの発行にはログインが必要です')),
      );
      return;
    }

    final targets = _issueableDeveloperRequests(requests);
    if (targets.isEmpty) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('登録できる新規改善提案はありません')));
      return;
    }

    setState(() {
      _isSubmittingAllDeveloperIssues = true;
    });

    var createdCount = 0;
    for (final request in targets) {
      if (!mounted) {
        return;
      }
      final submitted = await _submitAssetManagementDeveloperIssue(
        request,
        showSnackBar: false,
      );
      if (submitted) {
        createdCount += 1;
      }
    }

    if (!mounted) {
      return;
    }
    setState(() {
      _isSubmittingAllDeveloperIssues = false;
    });
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          createdCount == targets.length
              ? '改善提案を $createdCount 件 GitHub Issuesへ登録しました'
              : '改善提案 $createdCount/${targets.length} 件を登録しました。未登録分は個別に再試行してください',
        ),
      ),
    );
  }

  Future<bool> _submitAssetManagementDeveloperIssue(
    AssetManagementDeveloperRequest request, {
    bool showSnackBar = true,
  }) async {
    if (_supabase.auth.currentUser == null) {
      if (showSnackBar) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('GitHub Issueの発行にはログインが必要です')),
        );
      }
      return false;
    }

    final issueKey = _developerRequestIssueKey(request);
    if (_developerRequestIssueSubmissionKeys.contains(issueKey)) {
      return false;
    }

    setState(() {
      _developerRequestIssueSubmissionKeys.add(issueKey);
    });

    try {
      final severityLabel = _assetManagementInsightSeverityLabel(
        request.severity,
      );
      final response = await _supabase.functions.invoke(
        'core-hub',
        body: {
          'action': 'feature_request.submit',
          'title': '[資産管理] ${request.title}',
          'description': _developerRequestIssueDescription(
            request,
            severityLabel,
          ),
          'expected_outcome':
              '資産管理画面の改善提案を開発ワークフローに乗せ、該当運用を画面上で確認・実行・監査できる状態にする。',
          'category': 'UX改善',
          'priority': _developerRequestIssuePriority(request.severity),
          'source': 'asset_management_developer_request',
          'dedupe_key': issueKey,
        },
      );

      final rawData = response.data;
      if (rawData is! Map) {
        throw const FormatException('Invalid feature request response');
      }

      final data = Map<String, dynamic>.from(rawData);
      final success = data['success'] == true;
      final partialSuccess = data['partialSuccess'] == true;
      if (!success && !partialSuccess) {
        throw Exception(data['error'] ?? 'GitHub Issueの発行に失敗しました');
      }

      if (!mounted) return false;
      setState(() {
        _developerRequestIssueResults[issueKey] = data;
      });

      final githubIssue = _assetManagementDynamicMap(data['githubIssue']);
      final wbsTask = _assetManagementDynamicMap(data['wbsTask']);
      final issueUrl = githubIssue['html_url']?.toString() ?? '';
      final issueNumber = githubIssue['number']?.toString() ?? '';
      final wbsCreated = wbsTask.isNotEmpty && !wbsTask.containsKey('error');
      if (showSnackBar) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              issueUrl.isEmpty
                  ? 'WBSに登録しました。GitHub Issue連携は設定確認が必要です'
                  : wbsCreated
                      ? 'GitHub Issue #$issueNumber を発行してWBSに登録しました'
                      : 'GitHub Issue #$issueNumber を発行しました。'
                          'WBS連携は設定確認が必要です',
            ),
            action: issueUrl.isEmpty
                ? null
                : SnackBarAction(
                    label: '開く',
                    onPressed: () => web.window.open(issueUrl, '_blank'),
                  ),
          ),
        );
      }
      return true;
    } catch (e) {
      if (!mounted) return false;
      if (showSnackBar) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('GitHub Issueの発行に失敗しました: $e'),
            backgroundColor: Theme.of(context).colorScheme.error,
          ),
        );
      }
      return false;
    } finally {
      if (mounted) {
        setState(() {
          _developerRequestIssueSubmissionKeys.remove(issueKey);
        });
      }
    }
  }

  String _developerRequestIssueKey(AssetManagementDeveloperRequest request) {
    return '${request.title}\n${request.description}\n${request.severity.name}';
  }

  String _developerRequestIssueDescription(
    AssetManagementDeveloperRequest request,
    String severityLabel,
  ) {
    final buffer = StringBuffer()
      ..writeln(request.description)
      ..writeln()
      ..writeln('発行元: 資産管理画面 > 開発者向け改善提案')
      ..writeln('重要度: $severityLabel')
      ..writeln('画面: /asset-management');
    _appendDeveloperIssueSection(buffer, '根拠データ', request.evidence);
    _appendDeveloperIssueSection(buffer, '変更候補ファイル', request.sourceReferences);
    _appendDeveloperIssueSection(buffer, '実装手順', request.implementationSteps);
    _appendDeveloperIssueSection(buffer, '受け入れ条件', request.acceptanceCriteria);
    return buffer.toString().trim();
  }

  void _appendDeveloperIssueSection(
    StringBuffer buffer,
    String title,
    List<String> items,
  ) {
    if (items.isEmpty) {
      return;
    }
    buffer
      ..writeln()
      ..writeln('## $title');
    for (final item in items) {
      buffer.writeln('- $item');
    }
  }

  String _developerRequestIssuePriority(
    AssetManagementInsightSeverity severity,
  ) {
    return switch (severity) {
      AssetManagementInsightSeverity.critical => 'high',
      AssetManagementInsightSeverity.warning => 'medium',
      AssetManagementInsightSeverity.info => 'low',
    };
  }

  Map<String, dynamic> _assetManagementDynamicMap(Object? value) {
    if (value is Map<String, dynamic>) {
      return value;
    }
    if (value is Map) {
      return value.map((key, value) => MapEntry(key.toString(), value));
    }
    return const <String, dynamic>{};
  }

  Widget _buildMainAccountSelector(AssetLiabilityWorkbook workbook) {
    // メインバンク候補 = 現金以外の口座(預金・証券・その他資産)。
    final candidates = workbook.accounts
        .where(
          (account) =>
              account.kind != AssetLiabilityAccountKind.cash && account.isAsset,
        )
        .toList()
      ..sort((a, b) => b.balance.compareTo(a.balance));
    if (candidates.isEmpty) {
      return const SizedBox.shrink();
    }
    final validSelected =
        candidates.any((account) => account.id == _assetManagementMainAccountId)
            ? _assetManagementMainAccountId
            : null;
    return Row(
      children: [
        Icon(
          Icons.account_balance_outlined,
          size: 16,
          color: Theme.of(context).colorScheme.onSurfaceVariant,
        ),
        const SizedBox(width: 6),
        Text(
          'メインバンク',
          style: TextStyle(
            color: Theme.of(context).colorScheme.onSurfaceVariant,
            fontSize: 12,
            fontWeight: FontWeight.w600,
            height: 1.3,
          ),
        ),
        const SizedBox(width: 8),
        Expanded(
          child: DropdownButton<String?>(
            value: validSelected,
            isExpanded: true,
            isDense: true,
            hint: const Text('既定（残高最大の口座）', style: TextStyle(fontSize: 12)),
            items: [
              const DropdownMenuItem<String?>(
                value: null,
                child: Text('既定（残高最大の口座）', style: TextStyle(fontSize: 12)),
              ),
              for (final account in candidates)
                DropdownMenuItem<String?>(
                  value: account.id,
                  child: Text(
                    '${account.name}（${_formatManagementYen(account.balance)}）',
                    style: const TextStyle(fontSize: 12),
                    overflow: TextOverflow.ellipsis,
                  ),
                ),
            ],
            onChanged: (value) => unawaited(_setMainAccount(value)),
          ),
        ),
      ],
    );
  }

