  /// 「まず、これだけ」段階別トリアージカード。数字の洪水で混乱している
  /// 利用者向けに、今日 (最大3件)→今週→今月の順で絞って提示する。
  /// 背景が固定の淡ティールのため、文字色も固定の濃ティール系にする。
  Widget _buildAssetTriageGuideCard(AssetTriagePlan plan) {
    var stepNumber = 0;
    Widget buildStage(String label, List<AssetTriageStep> steps) {
      if (steps.isEmpty) {
        return const SizedBox.shrink();
      }
      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const SizedBox(height: 8),
          Text(
            label,
            style: const TextStyle(
              fontSize: 12,
              fontWeight: FontWeight.w800,
              color: Color(0xFF0F766E),
              height: 1.4,
            ),
          ),
          for (final step in steps) ...[
            const SizedBox(height: 4),
            Text(
              '${++stepNumber}. ${step.title}',
              style: const TextStyle(
                fontSize: 12,
                fontWeight: FontWeight.w700,
                color: Color(0xFF134E4A),
                height: 1.4,
              ),
            ),
            Text(
              step.detail,
              style: const TextStyle(
                fontSize: 11,
                color: Color(0xFF115E59),
                height: 1.5,
              ),
            ),
          ],
        ],
      );
    }

    return Container(
      key: const Key('asset_triage_guide_card'),
      width: double.infinity,
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: const Color(0xFFF0FDFA),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: const Color(0xFF99F6E4)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Icon(
                Icons.checklist_rounded,
                size: 16,
                color: Color(0xFF0F766E),
              ),
              const SizedBox(width: 6),
              Expanded(
                child: Text(
                  plan.todaySteps.isEmpty
                      ? 'まず、これだけ'
                      : 'まず、これだけ（今日やること ${plan.todaySteps.length}つ）',
                  style: const TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w800,
                    color: Color(0xFF134E4A),
                    height: 1.4,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 2),
          const Text(
            AssetTriagePlan.disclaimer,
            style: TextStyle(
              fontSize: 10,
              color: Color(0xFF0F766E),
              height: 1.4,
            ),
          ),
          buildStage('今日やること（${plan.todaySteps.length}つだけ）', plan.todaySteps),
          if (plan.todaySteps.isNotEmpty) ...[
            const SizedBox(height: 6),
            const Text(
              AssetTriagePlan.todayClosingNote,
              style: TextStyle(
                fontSize: 12,
                fontWeight: FontWeight.w700,
                color: Color(0xFF0F766E),
                height: 1.4,
              ),
            ),
          ],
          buildStage('今週やること', plan.weekSteps),
          buildStage('今月〜来月やること', plan.monthSteps),
          if (plan.showConsultation && plan.consultationNote != null) ...[
            const SizedBox(height: 8),
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(8),
              decoration: BoxDecoration(
                color: const Color(0xFFEFF6FF),
                borderRadius: BorderRadius.circular(6),
                border: Border.all(color: const Color(0xFFBFDBFE)),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Text(
                    '一人で抱えないでください',
                    style: TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.w800,
                      color: Color(0xFF1E3A8A),
                      height: 1.4,
                    ),
                  ),
                  const SizedBox(height: 4),
                  Text(
                    plan.consultationNote!,
                    style: const TextStyle(
                      fontSize: 11,
                      color: Color(0xFF1E40AF),
                      height: 1.5,
                    ),
                  ),
                ],
              ),
            ),
          ],
        ],
      ),
    );
  }

  /// 「借金しない宣言」の遵守状況（達成は緑で称賛、違反は赤で具体指摘）を描画する。
  Widget _buildAssetManagementDisciplineCard(AssetDebtDisciplineReport report) {
    final compliant = report.isCompliant;
    // 一覧の打ち切り件数。ヘッダーのバッジは総数を出すので、超過分は
    // 姉妹カード (月次負債トレンド) と同じく「ほか N件」で必ず示す。
    // 同一負債行が誓約①と②の両方で違反しうるため、カード数枚でも超過する。
    const violationDisplayLimit = 6;
    final hiddenViolationCount =
        report.allViolations.length - violationDisplayLimit;
    final headerColor =
        compliant ? const Color(0xFF0D9488) : const Color(0xFFB91C1C);
    final bgColor =
        compliant ? const Color(0xFFECFDF5) : const Color(0xFFFFF1F2);
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: bgColor,
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: headerColor.withValues(alpha: 0.28)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(
                compliant ? Icons.verified_outlined : Icons.gpp_maybe_outlined,
                color: headerColor,
                size: 18,
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  '借金しない宣言モニター',
                  style: TextStyle(
                    color: headerColor,
                    fontWeight: FontWeight.bold,
                    height: 1.4,
                  ),
                ),
              ),
              if (!compliant)
                Container(
                  key: const Key('asset_discipline_violation_badge'),
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 2,
                  ),
                  decoration: BoxDecoration(
                    color: const Color(0xFFB91C1C),
                    borderRadius: BorderRadius.circular(999),
                  ),
                  child: Text(
                    '違反 ${report.allViolations.length}件',
                    style: const TextStyle(
                      color: Colors.white,
                      fontSize: 11,
                      fontWeight: FontWeight.w800,
                      height: 1.3,
                    ),
                  ),
                ),
            ],
          ),
          const SizedBox(height: 8),
          Wrap(
            spacing: 6,
            runSpacing: 6,
            children: [
              _buildAssetDisciplinePledgeChip(
                '① カード以外の追加借入ゼロ',
                achieved: report.zeroNewBorrowingAchieved,
                evaluated: report.hasPriorMonthData,
              ),
              _buildAssetDisciplinePledgeChip(
                '② 新規利用分は25日に全額返済',
                achieved: report.newUsageRepaymentAchieved,
                evaluated: true,
              ),
            ],
          ),
          const SizedBox(height: 8),
          if (compliant)
            Text(
              report.hasPriorMonthData
                  ? '🎉 今月は「カード以外の追加借入ゼロ」と「新規利用分を25日に全額返済」を達成しています。'
                      '既存残高は無理なく圧縮していきましょう。'
                  : 'カード新規利用分の25日返済ルールは守れています。'
                      'カード以外の追加借入判定は来月以降の履歴蓄積後に有効化されます。',
              style: const TextStyle(fontSize: 12, height: 1.5),
            )
          else
            for (final violation in report.allViolations.take(
              violationDisplayLimit,
            ))
              Padding(
                padding: const EdgeInsets.only(bottom: 8),
                child: _buildAssetDisciplineViolationTile(violation),
              ),
          if (!compliant && hiddenViolationCount > 0)
            Text(
              'ほか $hiddenViolationCount件',
              key: const Key('asset_discipline_violation_overflow'),
              style: TextStyle(
                color: Theme.of(context).colorScheme.onSurfaceVariant,
                fontSize: 12,
              ),
            ),
        ],
      ),
    );
  }

  Widget _buildAssetDisciplinePledgeChip(
    String label, {
    required bool achieved,
    required bool evaluated,
  }) {
    final color = !evaluated
        ? const Color(0xFF6B7280)
        : (achieved ? const Color(0xFF0D9488) : const Color(0xFFB91C1C));
    final status = !evaluated ? '判定保留' : (achieved ? '達成' : '違反');
    final icon = !evaluated
        ? Icons.hourglass_empty
        : (achieved ? Icons.check_circle_outline : Icons.cancel_outlined);
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.10),
        borderRadius: BorderRadius.circular(999),
        border: Border.all(color: color.withValues(alpha: 0.32)),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(icon, color: color, size: 14),
          const SizedBox(width: 4),
          Text(
            '$label: $status',
            style: TextStyle(
              color: color,
              fontSize: 12,
              fontWeight: FontWeight.w700,
              height: 1.2,
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildAssetDisciplineViolationTile(
    AssetDebtDisciplineViolation violation,
  ) {
    final color = _assetDebtTrendSeverityColor(violation.severity);
    final amountLabel =
        violation.type == AssetDebtDisciplineViolationType.newBorrowing
            ? '新規利用'
            : '繰越額';
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(8),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: color.withValues(alpha: 0.22)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            '${violation.accountName}（${_assetDisciplineTypeLabel(violation.type)}）',
            style: TextStyle(
              color: color,
              fontWeight: FontWeight.bold,
              height: 1.4,
            ),
          ),
          const SizedBox(height: 4),
          Text(
            violation.problem,
            // 背景が固定の白のため、ダークテーマの onSurfaceVariant(淡色)だと
            // 読めなくなる。文字色も固定の濃スレート系にする。
            style: const TextStyle(
              color: Color(0xFF475569),
              fontSize: 12,
              height: 1.5,
            ),
          ),
          const SizedBox(height: 6),
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(8),
            decoration: BoxDecoration(
              color: color.withValues(alpha: 0.08),
              borderRadius: BorderRadius.circular(6),
            ),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Icon(Icons.arrow_forward, color: color, size: 16),
                const SizedBox(width: 6),
                Expanded(
                  child: Text(
                    violation.action,
                    // 固定白タイル上のためテーマ色でなく固定の濃色にする。
                    style: const TextStyle(
                      color: Color(0xFF1F2937),
                      fontSize: 12,
                      height: 1.5,
                    ),
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(height: 6),
          Wrap(
            spacing: 6,
            runSpacing: 6,
            children: [
              _buildAssetLiabilitySyncChip(
                label: amountLabel,
                value: _formatManagementYen(violation.amount),
                color: color,
              ),
              _buildAssetLiabilitySyncChip(
                label: '残高',
                value: _formatManagementYen(violation.currentBalance),
                color: const Color(0xFF6B7280),
              ),
              if (violation.hasEscapePlan)
                _buildAssetLiabilitySyncChip(
                  label: '${violation.escapeMonths}ヶ月脱却の月額',
                  value: _formatManagementYen(violation.escapeMonthlyPayment!),
                  color: const Color(0xFF0D9488),
                ),
              if (violation.currentPlanPayoffMonths case final months?)
                _buildAssetLiabilitySyncChip(
                  label: '現状ペース完済',
                  value: '約$monthsヶ月',
                  color: const Color(0xFF6B7280),
                ),
            ],
          ),
        ],
      ),
    );
  }

  String _assetDebtTrendCategoryLabel(AssetDebtTrendCategory category) {
    return switch (category) {
      AssetDebtTrendCategory.negativeAmortization => 'リボ複利・返済が利息以下',
      AssetDebtTrendCategory.balanceIncreasing => '残高が先月より増加',
      AssetDebtTrendCategory.slowPayoff => '完済まで超長期',
    };
  }

  /// 今月の負債の問題点と「翌月こうしなさい」を、計算済みの具体額つきで描画する。
  bool _householdTrackerPosting = false;
  bool _householdTrackerScheduleAllowed = false;
  bool _householdTrackerAutoPostEnabled = false;
  bool _householdTrackerScheduleSaving = false;
  String? _householdTrackerSnapshotSyncSignature;
  Future<void> _householdTrackerMirrorWriteQueue = Future<void>.value();
  bool _advisoryBriefingPosting = false;

  HouseholdTrackerSnapshot _householdTrackerSnapshot(
    List<AssetDebtTrendInsight> insights, {
    DateTime? now,
  }) {
    return householdSnapshotFromInsights(
      insights,
      salaryDay: _salaryDay,
      salaryDayConfigured: _salaryDayConfigured,
      now: now ?? DateTime.now(),
    );
  }

  /// 参謀室ブリーフィング用の前方キャッシュフロー予測を組み立てる
  /// (_buildCashflowForecastCard と同じ入力導出。純サービスに委譲)。
  AssetCashflowForecast? _advisoryCashflowForecast(
    AssetLiabilityWorkbook? workbook,
  ) {
    if (workbook == null) return null;
    final inputs = AssetCashflowForecastInputs.fromAssetData(
      accounts: workbook.accounts,
      debtRows: workbook.debtMasterRows,
      recurringIncomeTemplates: _recurringIncomeTemplates,
      inflowRules: _expectedInflowRules,
      oneTimeInflows: _expectedInflows,
      subscriptions: _subscriptions,
    );
    if (!inputs.hasData) return null;
    return AssetCashflowForecastService.project(
      asOf: DateTime.now(),
      startingBalance: inputs.startingBalance,
      horizonMonths: _forecastHorizonMonths,
      recurringIncome: inputs.recurringIncome,
      recurringOutflow: inputs.recurringOutflow,
      oneTimeIncome: inputs.oneTimeIncome,
      safetyMargin: _assetForecastSafetyMargin,
    );
  }

  Color _advisorySeverityColor(AdvisorySeverity severity) {
    switch (severity) {
      case AdvisorySeverity.critical:
        return const Color(0xFFB91C1C);
      case AdvisorySeverity.warning:
        return const Color(0xFFD97706);
      case AdvisorySeverity.info:
        return const Color(0xFF0F766E);
    }
  }

