  Widget _buildAssetManagementMonthlyDebtTrendTile(
    AssetDebtTrendInsight insight,
  ) {
    final color = _assetDebtTrendSeverityColor(insight.severity);
    final payoffValue = insight.estimatedPayoffMonths == null
