  bool _shouldInsertTodayMarkerBeforeCardBillingItem(
    AssetLiabilityCardBillingReviewItem item,
  ) {
    final day = item.paymentDay;
    if (day == null) {
      return true;
    }
    final lastDay = DateTime(_now.year, _now.month + 1, 0).day;
    final resolvedDay = day.clamp(1, lastDay).toInt();
    return resolvedDay >= _now.day;
  }

  bool _isCardBillingReviewItemTodayOrLater(
    AssetLiabilityCardBillingReviewItem item,
  ) {
    final day = item.paymentDay;
    if (day == null) {
      return false;
    }
    final lastDay = DateTime(_now.year, _now.month + 1, 0).day;
    return day.clamp(1, lastDay).toInt() >= _now.day;
  }

  bool _isCardBillingReviewItemOverdue(
    AssetLiabilityCardBillingReviewItem item,
  ) {
    final day = item.paymentDay;
    if (item.paid || item.amount <= 0 || day == null) {
      return false;
    }
    final lastDay = DateTime(_now.year, _now.month + 1, 0).day;
    return day.clamp(1, lastDay).toInt() < _now.day;
  }

  String _cardBillingReviewItemStatusLabel(
    AssetLiabilityCardBillingReviewItem item,
  ) {
    if (item.paid) {
      return '支払済み';
    }
    if (item.amount <= 0) {
      return '確認のみ';
    }
    if (item.paymentDay == null) {
      return '支払日未設定';
    }
    final lastDay = DateTime(_now.year, _now.month + 1, 0).day;
    final day = item.paymentDay!.clamp(1, lastDay).toInt();
    if (day < _now.day) {
      return '期限超過';
    }
    if (day == _now.day) {
      return '今日';
    }
    return '今後';
  }

  Color _cardBillingReviewItemStatusColor(
    AssetLiabilityCardBillingReviewItem item,
  ) {
    if (item.paid) {
      return const Color(0xFF0D9488);
    }
    if (item.amount <= 0) {
      return const Color(0xFF64748B);
    }
    if (item.paymentDay == null) {
      return const Color(0xFF64748B);
    }
    final lastDay = DateTime(_now.year, _now.month + 1, 0).day;
    final day = item.paymentDay!.clamp(1, lastDay).toInt();
    if (day < _now.day) {
      return const Color(0xFFB91C1C);
    }
    if (day == _now.day) {
      return const Color(0xFFD97706);
    }
    return const Color(0xFF2563EB);
  }

  Widget _buildCardStatementReconciliationPanel(
    AssetLiabilityWorkbook workbook,
  ) {
    final reconciliation = workbook.cardStatementReconciliation;
    // 照合グループのホストは shoppingDebt も正当（planning service の
    // isCardBillingHostKind と同じ集合）。creditCard 限定だと解消アクション
    // からの選択がサイレントに別カードへフォールバックし誤取込を招く。
    final cardOptions = _cardBillingAccountOptions(
      workbook,
      includeShoppingDebt: true,
    );
    final selected = _selectedCardStatementBillingAccountId;
    final validSelected = selected != null &&
        cardOptions.any((account) => account.id == selected);
    final selectedValue = validSelected
        ? selected
        : (cardOptions.isEmpty ? null : cardOptions.first.id);

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: Theme.of(context).colorScheme.surface,
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: Theme.of(context).colorScheme.outlineVariant),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(
                reconciliation.hasNeedsReview
                    ? Icons.warning_amber_outlined
                    : Icons.receipt_long_outlined,
                color: reconciliation.hasNeedsReview
                    ? const Color(0xFFD97706)
                    : const Color(0xFF0D9488),
              ),
              const SizedBox(width: 8),
              const Expanded(
                child: Text(
                  'カード明細取り込み・照合',
                  style: TextStyle(fontWeight: FontWeight.bold, height: 1.4),
                ),
              ),
              _buildTextStatusChip(
                label: '${reconciliation.importedLineCount}行',
                color: const Color(0xFF2563EB),
              ),
            ],
          ),
          const SizedBox(height: 6),
          Text(
            'CSV/TSV行は「摘要,金額,日付」または「請求先ID,摘要,金額,日付」で貼り付けできます。auPAY等の明細表（タブ区切り・「利用日/利用店名/利用金額」等の見出し付き）もそのまま貼り付け可能です。取り込み合計をカード請求額と照合します。',
            style: TextStyle(
              color: Theme.of(context).colorScheme.onSurfaceVariant,
              fontSize: 12,
              height: 1.5,
            ),
          ),
          const SizedBox(height: 8),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            crossAxisAlignment: WrapCrossAlignment.center,
            children: [
              SizedBox(
                width: 260,
                child: DropdownButton<String>(
                  value: selectedValue,
                  isExpanded: true,
                  hint: const Text('請求先カード'),
                  items: [
                    for (final account in cardOptions)
                      DropdownMenuItem<String>(
                        value: account.id,
                        child: Text(account.name),
                      ),
                  ],
                  onChanged: (value) {
                    setState(() {
                      _selectedCardStatementBillingAccountId = value;
                    });
                  },
