  /// 修正アクション種別ごとの実行ハンドラ。導線を用意できない種別は null
  /// (説明文のみ表示)。
  VoidCallback? _cardStatementFixActionHandler(
    AssetLiabilityCardStatementReconciliationGroup group,
    AssetLiabilityCardStatementFixAction action,
    Set<String> selectableCardIds,
  ) {
    return switch (action.kind) {
      // 取り込み欄の請求先カードを該当カードへ切り替え、貼り付けを促す。
      // ドロップダウン候補に無いホストはサイレントに先頭カードへフォール
      // バックして誤取込を招くため、ボタン自体を出さない。
      AssetLiabilityCardStatementFixActionKind.importStatement
          when selectableCardIds.contains(group.billingAccountId) =>
        () {
          setState(() {
            _selectedCardStatementBillingAccountId = group.billingAccountId;
            _cardStatementImportMessage =
                '${group.billingAccountName}を選択しました。カード明細を貼り付けて「明細を取り込む」を押してください。';
          });
        },
      AssetLiabilityCardStatementFixActionKind.importStatement => null,
      AssetLiabilityCardStatementFixActionKind.adjustConfiguredBreakdown =>
        () => _jumpToDebtMasterCard(group.billingAccountId),
      AssetLiabilityCardStatementFixActionKind.reviewStatementLines => null,
      AssetLiabilityCardStatementFixActionKind.assignBillingAccount => null,
    };
  }

  /// 照合行の「確認事項」表示文。リボ払いカードは不一致アラートの代わりに
  /// 返済内訳 (最低返済額 + 新規利用額) と毎月25日のルールを説明する。
  String _cardReconciliationNote(
    AssetLiabilityCardStatementReconciliationGroup group,
  ) {
    final billing = group.revolvingBilling;
    if (billing != null) {
      return 'リボ返済ルール: 最低返済 ${_formatManagementYen(billing.monthlyAmount)}'
          ' ＋ 新規利用分の全額返済 ${_formatManagementYen(billing.newUsageAmount)}'
          ' ＝ 25日の返済予定 ${_formatManagementYen(billing.billedAmount)}。'
          '既存残高 ${_formatManagementYen(billing.existingBalanceAmount)}は'
          '一括返済せず、最低返済額で圧縮します。';
    }
    return group.alerts.isEmpty ? 'OK' : group.alerts.join(' / ');
  }

  Widget _buildCardStatementReconciliationTable(
    AssetLiabilityCardStatementReconciliationData reconciliation,
  ) {
    if (reconciliation.groups.isEmpty) {
      return Text(
        '照合できるカード請求内訳またはカード明細がまだありません。',
        style: TextStyle(
          color: Theme.of(context).colorScheme.onSurfaceVariant,
          fontSize: 12,
          height: 1.5,
        ),
      );
    }

    return SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      child: DataTable(
        headingRowHeight: 34,
        dataRowMinHeight: 46,
        // 確認事項は長文になり得るため行高さを可変にし、上限120pxでセル側で折り返す。
        dataRowMaxHeight: 120,
        columns: const [
          DataColumn(label: Text('請求先カード')),
          DataColumn(label: Text('請求額'), numeric: true),
          DataColumn(label: Text('明細合計'), numeric: true),
          DataColumn(label: Text('設定内訳合計'), numeric: true),
          DataColumn(label: Text('差額'), numeric: true),
          DataColumn(label: Text('確認事項')),
        ],
        rows: [
          for (final group in reconciliation.groups)
            DataRow(
              cells: [
                DataCell(Text(group.billingAccountName)),
                DataCell(Text(_formatManagementYen(group.billedAmount))),
                DataCell(Text(_formatManagementYen(group.statementLineTotal))),
                DataCell(
                  Text(
                    _formatManagementYen(group.configuredDetailTotal),
                    // 設定内訳のずれ（設定差分）は差額列(明細合計基準)に出ない
                    // ため、セル自体を強調して気付けるようにする。
                    style: group.hasConfiguredMismatchFix
                        ? const TextStyle(
                            color: Color(0xFFD97706),
                            fontWeight: FontWeight.bold,
                          )
                        : null,
                  ),
                ),
                DataCell(
                  group.isRevolving
                      ? const Text('—')
                      : Text(
                          _formatManagementYen(group.statementDifference),
                          style: TextStyle(
                            color: group.needsReview
                                ? const Color(0xFFD97706)
                                : const Color(0xFF0D9488),
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                ),
                DataCell(
                  ConstrainedBox(
                    constraints: const BoxConstraints(maxWidth: 280),
                    child: Padding(
                      padding: const EdgeInsets.symmetric(vertical: 6),
                      child: Text(
                        _cardReconciliationNote(group),
                        softWrap: true,
                        style: const TextStyle(height: 1.4),
                      ),
                    ),
                  ),
                ),
              ],
            ),
        ],
      ),
    );
  }

