  Color _paymentReminderStatusColor(
    AssetLiabilityPaymentReminderCandidate reminder,
  ) {
    if (reminder.hasShortageRisk ||
        reminder.status == AssetLiabilityPaymentReminderStatus.overdue) {
      return const Color(0xFFB91C1C);
    }
    if (reminder.status == AssetLiabilityPaymentReminderStatus.dueToday) {
      return const Color(0xFFD97706);
    }
    return const Color(0xFF2563EB);
  }

  String _paymentReminderStatusLabel(
    AssetLiabilityPaymentReminderCandidate reminder,
  ) {
    return switch (reminder.status) {
      AssetLiabilityPaymentReminderStatus.overdue => '超過',
      AssetLiabilityPaymentReminderStatus.dueToday => '今日',
      AssetLiabilityPaymentReminderStatus.dueTomorrow => '明日',
    };
  }

  Widget _buildAssetWorkbookPaymentList(AssetLiabilityWorkbook workbook) {
    if (workbook.paymentDayRisks.isEmpty) {
      return const SizedBox.shrink();
    }

    final actionRisks = workbook.paymentDayRisks
        .where((risk) => risk.requiresAction)
        .toList(growable: false);
    final reviewOnlyRisks = workbook.paymentDayRisks
        .where((risk) => !risk.requiresAction)
        .toList(growable: false);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        if (actionRisks.isNotEmpty)
          _buildPaymentRiskSection(
            key: const Key('asset_payment_risk_action_section'),
            title: '支払日別リスク（要対応）',
            risks: actionRisks,
          ),
        if (actionRisks.isNotEmpty && reviewOnlyRisks.isNotEmpty)
          const SizedBox(height: 12),
        if (reviewOnlyRisks.isNotEmpty)
          _buildPaymentRiskSection(
            key: const Key('asset_payment_risk_review_only_section'),
            title: '確認のみ',
            description: '今月支払予定額が0円のため、延滞ではなく確認対象として表示しています。',
            risks: reviewOnlyRisks,
          ),
      ],
    );
  }

  Widget _buildPaymentRiskSection({
    required Key key,
    required String title,
    required List<AssetLiabilityPaymentDayRisk> risks,
    String? description,
  }) {
    return Container(
      key: key,
      width: double.infinity,
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: Theme.of(context).colorScheme.surfaceContainerLow,
        borderRadius: BorderRadius.circular(8),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            title,
            style: const TextStyle(fontWeight: FontWeight.bold, height: 1.4),
          ),
          if (description != null) ...[
            const SizedBox(height: 4),
