  int _compareDebtRowsByPaymentDay(
    AssetLiabilityDebtRow a,
    AssetLiabilityDebtRow b,
  ) {
    // 給料日サイクル順 (給料日起点) に並べる。salaryDay=25 なら
    // 25,26…31,1…24 の順。未設定 (null) は末尾。
    final day = AssetLiabilityMonthlyStateStore.compareSalaryCyclePaymentDays(
      a.paymentDay,
      b.paymentDay,
      salaryDay: _salaryDay,
    );
    if (day != 0) {
      return day;
    }
    final balance = b.balance.abs().compareTo(a.balance.abs());
    if (balance != 0) {
      return balance;
    }
    return a.name.compareTo(b.name);
  }

  /// 定期固定費を給料日サイクル順に並べる。負債マスタ
  /// ([_compareDebtRowsByPaymentDay]) と同じ起点・同じ rank を共有し、支払日が同じ
  /// ときは名前順。paymentDay は非 null int なので null 救済は不要。
  int _compareRecurringFixedCostsByPaymentDay(
    AssetRecurringFixedCost a,
    AssetRecurringFixedCost b,
  ) {
    final day = AssetLiabilityMonthlyStateStore.compareSalaryCyclePaymentDays(
      a.paymentDay,
      b.paymentDay,
      salaryDay: _salaryDay,
    );
    return day != 0 ? day : a.name.compareTo(b.name);
  }

  List<AssetLiabilityDebtRow> _filteredDebtMasterRows(
    AssetLiabilityWorkbook workbook,
  ) {
    return switch (_debtMasterReviewFilter) {
      _DebtMasterReviewFilter.billingConfirmation =>
        List<AssetLiabilityDebtRow>.from(
          workbook.billingConfirmationPendingRows,
        ),
      // 未設定に加えて「設定済みだが現金・預金口座を指していない」行も出す。
      // 後者はどの口座の見込み残高からも引かれない盲点で、ここに出さないと
      // アラートで指摘しても直す場所に辿り着けない。両者は述語が排他
      // (未設定=ID空 / 不正=ID非空) なので重複は発生しない。
      _DebtMasterReviewFilter.paymentSource => <AssetLiabilityDebtRow>[
          ...workbook.paymentSourceMissingRows,
          ...workbook.paymentSourceInvalidRows,
        ],
      _DebtMasterReviewFilter.all => List<AssetLiabilityDebtRow>.from(
          workbook.debtMasterRows,
        ),
    };
  }

  Widget _buildPaymentMethodDropdown(
    AssetLiabilityDebtRow row,
    AssetLiabilityWorkbook workbook,
  ) {
    // アコムショッピング等のショッピング枠も請求のまとめ先に選べるようにする
    // (請求ホストの正当性は AssetLiabilityPlanningService.isCardBillingHostKind と一致)。
    final cardOptions = _cardBillingAccountOptions(
      workbook,
      includeShoppingDebt: true,
    ).where((account) => account.id != row.id).toList(growable: false);
    final configured = _cardBillingAccountIds[row.id];
    final selected = configured ??
        (row.paymentMethod == AssetLiabilityPaymentMethod.includedInCard
            ? row.billingAccountId
            : AssetLiabilityPlanningService.directPaymentMethodId);
    final validSelected =
        selected == AssetLiabilityPlanningService.directPaymentMethodId ||
            cardOptions.any((account) => account.id == selected);

    return SizedBox(
      width: 220,
      child: DropdownButton<String>(
        value: validSelected
            ? selected
            : AssetLiabilityPlanningService.directPaymentMethodId,
        isExpanded: true,
        items: [
          const DropdownMenuItem<String>(
            value: AssetLiabilityPlanningService.directPaymentMethodId,
            child: Text(AssetLiabilityPlanningService.directPaymentLabel),
          ),
          for (final account in cardOptions)
            DropdownMenuItem<String>(
              value: account.id,
              child: Text('${account.name}請求に含む'),
            ),
        ],
        onChanged: (value) => _updateCardBillingAccount(row, value),
      ),
    );
  }

  Widget _buildPaymentMethodScopeControl(AssetLiabilityDebtRow row) {
    final selectedScope = _cardBillingSaveScopeFor(row);
    final sourceLabel =
        AssetLiabilityPlanningService.paymentMethodSettingSourceLabel(
      row.paymentMethodSettingSource,
    );

    return SizedBox(
      width: 180,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisSize: MainAxisSize.min,
        children: [
          _buildTextStatusChip(
            label: sourceLabel,
            color: row.paymentMethodSettingSource ==
                    AssetLiabilityPaymentMethodSettingSource.monthlyOverride
                ? const Color(0xFF7C3AED)
                : const Color(0xFF475569),
          ),
          const SizedBox(height: 4),
          DropdownButton<_CardBillingSaveScope>(
            value: selectedScope,
            isExpanded: true,
            items: const [
              DropdownMenuItem<_CardBillingSaveScope>(
                value: _CardBillingSaveScope.defaultSetting,
                child: Text(
                  AssetLiabilityPlanningService.saveAsDefaultPaymentMethodLabel,
                ),
              ),
              DropdownMenuItem<_CardBillingSaveScope>(
                value: _CardBillingSaveScope.monthlyOverride,
                child: Text(
                  AssetLiabilityPlanningService.saveAsMonthlyPaymentMethodLabel,
                ),
              ),
            ],
            onChanged: (value) {
              if (value == null) {
                return;
              }
              _updateCardBillingSaveScope(row.id, value);
            },
          ),
        ],
      ),
    );
  }

  Widget _buildMonthlyPaymentInput(AssetLiabilityDebtRow row) {
    if (row.isRevolving) {
      // リボ払いは最低返済額と新規利用額から自動算出するため手入力欄は出さない。
      final billing = row.revolvingBilling!;
      return SizedBox(
        width: 150,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              _formatManagementYen(billing.billedAmount),
              style: const TextStyle(fontWeight: FontWeight.bold, height: 1.3),
            ),
            const Text(
              '25日・最低返済＋新規利用',
              style: TextStyle(fontSize: 11, height: 1.3),
            ),
          ],
        ),
      );
    }
    final controller = _monthlyPaymentControllerFor(row);
    return SizedBox(
      width: 150,
      child: TextField(
        controller: controller,
        keyboardType: TextInputType.number,
        inputFormatters: [FilteringTextInputFormatter.allow(RegExp(r'[0-9,]'))],
        onChanged: (value) => _updateMonthlyPaymentOverride(row.id, value),
        decoration: InputDecoration(
          isDense: true,
          hintText: _formatManagementYen(row.minimumPaymentEstimate),
          helperText: row.paymentAmountEstimated ? '未入力時は推定' : '実額を優先',
          suffixIcon: row.paymentAmountEstimated
              ? null
              : IconButton(
                  tooltip: '手入力値をクリア',
                  icon: const Icon(Icons.clear, size: 16),
                  onPressed: () => _clearMonthlyPaymentOverride(row.id),
                ),
        ),
      ),
    );
  }

  Widget _buildRevolvingControl(AssetLiabilityDebtRow row) {
    final config = _revolvingConfigs[row.id];
    final enabled = config != null;
    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            SizedBox(
              width: 24,
              height: 24,
              child: Checkbox(
                value: enabled,
                onChanged: (value) => _toggleRevolving(row, value ?? false),
              ),
            ),
            const SizedBox(width: 4),
            const Flexible(
              child: Text(
                'リボ返済 (最低返済＋新規利用を25日に返済)',
                style: TextStyle(fontSize: 11, height: 1.3),
              ),
            ),
          ],
        ),
        if (config != null) ...[
          const SizedBox(height: 6),
          _buildRevolvingField(
            row: row,
            label: '最低返済額',
            hint: '例: 10000',
            value: config.monthlyAmount,
            onChanged: (amount) =>
                _updateRevolvingMonthlyAmount(row.id, amount),
          ),
          const SizedBox(height: 6),
          _buildRevolvingField(
            row: row,
            label: '新規利用額',
            hint: '明細未取込時のみ',
            value: config.newUsageAmount,
            onChanged: (amount) =>
                _updateRevolvingNewUsageAmount(row.id, amount),
          ),
          const SizedBox(height: 6),
          _buildRevolvingField(
            row: row,
            label: '利用限度額',
            hint: '与信枠確認用',
            value: config.creditLimit,
            onChanged: (amount) => _updateRevolvingCreditLimit(row.id, amount),
          ),
          const SizedBox(height: 6),
          const Text(
            '返済日: 毎月25日（給料日）／明細を取り込むと新規利用額を自動反映。'
            '利用限度額は返済額ではなく与信枠不足の確認だけに使用',
            style: TextStyle(fontSize: 11, height: 1.3),
          ),
          if (row.revolvingBilling != null) ...[
            const SizedBox(height: 6),
            Text(
              '25日返済 ${_formatManagementYen(row.revolvingBilling!.billedAmount)}'
              '（既存残高の一括返済なし）',
              style: const TextStyle(
                fontSize: 11,
                height: 1.3,
                fontWeight: FontWeight.w600,
              ),
            ),
