  Widget _buildRevolvingField({
    required AssetLiabilityDebtRow row,
    required String label,
    required String hint,
    required double value,
    required ValueChanged<double> onChanged,
  }) {
    return Row(
      children: [
        SizedBox(
          width: 64,
          child: Text(label, style: const TextStyle(fontSize: 11, height: 1.3)),
        ),
        Expanded(
          child: TextFormField(
            key: ValueKey('revolving:${row.id}:$label'),
            initialValue: value > 0 ? value.toStringAsFixed(0) : '',
            keyboardType: TextInputType.number,
            inputFormatters: [
              FilteringTextInputFormatter.allow(RegExp(r'[0-9,]')),
            ],
            style: const TextStyle(fontSize: 12),
            decoration: InputDecoration(isDense: true, hintText: hint),
            onChanged: (text) {
              final normalized = text.replaceAll(',', '').trim();
              final parsed =
                  normalized.isEmpty ? 0.0 : double.tryParse(normalized) ?? 0.0;
              onChanged(parsed);
            },
          ),
        ),
      ],
    );
  }

  Widget _buildCardUsagePolicyControl(AssetLiabilityDebtRow row) {
    final policy = _cardUsagePolicies[row.id];
    final completed = policy?.enforceOneShot == true;
    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        CheckboxListTile(
          key: ValueKey('asset_card_one_shot_completed_${row.id}'),
          contentPadding: EdgeInsets.zero,
          dense: true,
          controlAffinity: ListTileControlAffinity.leading,
          value: completed,
          title: const Text(
            '完了（今後の新規利用は1回払い）',
            style: TextStyle(fontSize: 12, height: 1.3),
          ),
          onChanged: (value) =>
              _toggleCardOneShotCompleted(row.id, value ?? false),
        ),
        if (completed) ...[
          if (policy?.changedAt != null)
            Padding(
              padding: const EdgeInsets.only(bottom: 6),
              child: Text(
                '変更記録: ${DateFormat('yyyy/MM/dd HH:mm').format(policy!.changedAt!.toLocal())}',
                style: const TextStyle(fontSize: 11, height: 1.3),
              ),
            ),
          TextFormField(
            key: ValueKey('asset_card_one_shot_memo_${row.id}'),
            initialValue: policy?.memo ?? '',
            maxLength: 200,
            minLines: 1,
            maxLines: 2,
            style: const TextStyle(fontSize: 12),
            decoration: const InputDecoration(
              isDense: true,
              labelText: '受付番号・連絡日メモ',
              hintText: '例: 8/29 電話、受付 ABC123',
              helperText: 'カード番号などの機密情報は記録しないでください',
            ),
            onChanged: (value) => _updateCardUsagePolicyMemo(row.id, value),
          ),
          const SizedBox(height: 4),
          const Text(
            'この記録に関係なく、新規利用分の25日返済不足は継続監視します。',
            style: TextStyle(fontSize: 11, height: 1.3),
          ),
        ],
      ],
    );
  }

  Widget _buildActualPaymentInput(AssetLiabilityDebtRow row) {
    if (row.includedInBillingAccount) {
      return _buildTextStatusChip(
        label: AssetLiabilityPlanningService.cardBillingIncludedLabel,
        color: const Color(0xFF2563EB),
      );
    }
    final controller = _actualPaymentControllerFor(row);
    return SizedBox(
      width: 140,
      child: TextField(
        controller: controller,
        enabled: row.paid,
        keyboardType: TextInputType.number,
        inputFormatters: [FilteringTextInputFormatter.allow(RegExp(r'[0-9,]'))],
        onChanged: (value) => _updateActualPaymentAmount(row.id, value),
        decoration: InputDecoration(
          isDense: true,
          hintText: row.paid
              ? _formatManagementYen(row.scheduledPaymentAmount)
              : 'paid only',
        ),
      ),
    );
  }

  Widget _buildPaymentDifferenceReasonInput(AssetLiabilityDebtRow row) {
    if (row.includedInBillingAccount) {
      return const Text('-');
    }
    final controller = _paymentDifferenceReasonControllerFor(row);
    return SizedBox(
      width: 190,
      child: TextField(
        controller: controller,
        enabled: row.paid,
        onChanged: (value) => _updatePaymentDifferenceReason(row.id, value),
        decoration: const InputDecoration(isDense: true, hintText: 'reason'),
      ),
    );
  }

  Widget _buildPaymentAmountSourceChip(AssetLiabilityDebtRow row) {
    if (row.includedInBillingAccount) {
      return _buildTextStatusChip(
        label: row.paymentMethodLabel ??
            AssetLiabilityPlanningService.cardBillingIncludedLabel,
        color: const Color(0xFF2563EB),
      );
    }
    final isEstimated = row.paymentAmountEstimated;
    final color =
        isEstimated ? const Color(0xFFD97706) : const Color(0xFF0D9488);
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.12),
        borderRadius: BorderRadius.circular(999),
      ),
      child: Text(
        isEstimated ? '推定' : '実額',
        style: TextStyle(
          color: color,
          fontSize: 12,
          fontWeight: FontWeight.bold,
          height: 1.2,
        ),
      ),
    );
  }

  Widget _buildBillingConfirmedCell(AssetLiabilityDebtRow row) {
    if (row.includedInBillingAccount) {
      return _buildTextStatusChip(
        label: AssetLiabilityPlanningService.cardBillingIncludedLabel,
        color: const Color(0xFF2563EB),
      );
    }
    final effectiveConfirmed =
        row.billingConfirmed || !row.paymentAmountEstimated || row.paid;
    final canToggle = row.paymentAmountEstimated && !row.paid;
    return SizedBox(
      width: 160,
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Checkbox(
            value: effectiveConfirmed,
            onChanged: canToggle
                ? (value) => _toggleBillingConfirmed(row.id, value ?? false)
                : null,
          ),
          _buildTextStatusChip(
            label: effectiveConfirmed ? '確認済み' : '未確認',
            color: effectiveConfirmed
                ? const Color(0xFF0D9488)
                : const Color(0xFFD97706),
          ),
        ],
      ),
    );
  }

  Widget _buildPaidCheckbox(AssetLiabilityDebtRow row) {
    if (row.includedInBillingAccount) {
      return _buildTextStatusChip(
        label: AssetLiabilityPlanningService.cardBillingIncludedLabel,
        color: const Color(0xFF2563EB),
      );
    }
    return Checkbox(
      value: row.paid,
      onChanged: (value) {
        unawaited(_toggleMonthlyPaymentPaid(row, value ?? false));
      },
    );
  }

  Widget _buildAnnualRateInputWithEvidence(AssetLiabilityDebtRow row) {
    if (row.fullPaymentEstimate) {
      return _buildTextStatusChip(
        label: '固定費（利率なし）',
        color: const Color(0xFF475569),
      );
    }
    final controller = _annualRateControllerFor(row);
    final hasOverride = _annualRateOverrides.containsKey(row.id);
    final evidence = _annualRateEvidences[row.id];
    final verified = evidence?.matchesAnnualRate(row.annualRate) ?? false;
    final risk = _annualRateRiskForRow(row);
    return SizedBox(
      width: 220,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          TextField(
            controller: controller,
            keyboardType: const TextInputType.numberWithOptions(decimal: true),
            inputFormatters: [
              FilteringTextInputFormatter.allow(RegExp(r'[0-9.,%]')),
            ],
            onChanged: (value) => _updateAnnualRateOverride(row, value),
            decoration: InputDecoration(
              isDense: true,
              hintText: _formatRateInput(row.annualRate),
              helperText:
                  hasOverride ? (verified ? 'AI確認済み' : '証跡確認が必要') : '年利変更は証跡必須',
              suffixText: '%',
              suffixIcon: hasOverride
                  ? IconButton(
                      tooltip: '年利上書きをクリア',
                      icon: const Icon(Icons.clear, size: 16),
                      onPressed: () => _clearAnnualRateOverride(row.id),
                    )
                  : null,
            ),
          ),
          const SizedBox(height: 4),
          if (risk != null) ...[
            _buildAnnualRateRiskWarning(risk),
            const SizedBox(height: 4),
          ],
          _buildAnnualRateEvidenceCell(row),
        ],
      ),
    );
  }

  Widget _buildAnnualRateRiskWarning(DebtAnnualRateRisk risk) {
    final color = _debtSafetySeverityColor(risk.severity);
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.1),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: color.withValues(alpha: 0.24)),
      ),
      child: Text(
        risk.blocksRegistration ? risk.title : risk.detail,
        style: TextStyle(
          color: color,
          fontSize: 11,
          fontWeight: FontWeight.w700,
          height: 1.4,
        ),
      ),
    );
  }

  Widget _buildAnnualRateEvidenceCell(AssetLiabilityDebtRow row) {
    final evidence = _annualRateEvidences[row.id];
    final isVerifying = _verifyingAnnualRateEvidenceAccountIds.contains(row.id);
    final isPasteTarget = _annualRateEvidencePasteTargetRow?.id == row.id;
    final requestedRate =
        _parseAnnualRateInput(_annualRateControllerFor(row).text) ??
            row.annualRate;
    final risk = _annualRateRiskFor(
      accountName: row.name,
      annualRate: requestedRate,
      principal: row.balance.abs(),
    );
    final blocked = risk?.blocksRegistration == true;
    final verified = evidence?.matchesAnnualRate(requestedRate) ?? false;
    final color = verified
        ? const Color(0xFF0D9488)
        : evidence == null
            ? const Color(0xFFDC2626)
            : const Color(0xFFD97706);
    final label = verified
        ? 'AI証跡OK'
        : evidence == null
            ? '証跡提出'
            : '再提出';
    return Wrap(
      spacing: 6,
      runSpacing: 4,
      crossAxisAlignment: WrapCrossAlignment.center,
      children: [
        OutlinedButton.icon(
          onPressed: isVerifying || blocked
              ? null
              : () => _submitAnnualRateEvidence(row),
          icon: isVerifying
              ? const SizedBox(
                  width: 14,
                  height: 14,
                  child: CircularProgressIndicator(strokeWidth: 2),
                )
              : const Icon(Icons.upload_file, size: 14),
          label: Text(label),
          style: OutlinedButton.styleFrom(
            foregroundColor: color,
            side: BorderSide(color: color.withValues(alpha: 0.5)),
            visualDensity: VisualDensity.compact,
          ),
        ),
        OutlinedButton.icon(
          onPressed: isVerifying || blocked
              ? null
              : () => _startAnnualRateEvidencePaste(row),
          icon: const Icon(Icons.content_paste, size: 14),
          label: const Text('貼付'),
          style: OutlinedButton.styleFrom(
            foregroundColor: isPasteTarget ? const Color(0xFF2563EB) : color,
            side: BorderSide(
              color: (isPasteTarget ? const Color(0xFF2563EB) : color)
                  .withValues(alpha: 0.5),
            ),
            visualDensity: VisualDensity.compact,
          ),
        ),
        if (isPasteTarget)
          _buildTextStatusChip(
            label: 'Ctrl+V待ち',
            color: const Color(0xFF2563EB),
          ),
        if (blocked)
          _buildTextStatusChip(
            label: '20%超は登録不可',
            color: const Color(0xFFB91C1C),
          ),
        if (evidence != null)
          Tooltip(
            message: evidence.summary.isEmpty
                ? evidence.fileName
                : '${evidence.fileName}\n${evidence.summary}',
            child: _buildTextStatusChip(
              label: verified ? '確認済' : '要確認',
              color: color,
            ),
          ),
      ],
    );
  }

