  Widget _buildAssetOverviewTrendChart(
    List<({String date, double assets, double liabilities, double netWorth})>
        points,
  ) {
    final values = <double>[
      for (final point in points) ...[
        point.assets,
        point.netWorth,
        point.liabilities,
      ],
    ];
    var minY = values.reduce((a, b) => a < b ? a : b);
    var maxY = values.reduce((a, b) => a > b ? a : b);
    if (minY == maxY) {
      minY -= 1000;
      maxY += 1000;
    } else {
      final padding = (maxY - minY) * 0.14;
      minY -= padding;
      maxY += padding;
    }
    final interval = max(1, (points.length / 4).floor()).toDouble();

    LineChartBarData line({
      required List<FlSpot> spots,
      required Color color,
      bool area = false,
    }) {
      return LineChartBarData(
        spots: spots,
        isCurved: true,
        curveSmoothness: 0.22,
        color: color,
        barWidth: 3,
        dotData: const FlDotData(show: false),
        isStrokeCapRound: true,
        belowBarData: BarAreaData(
          show: area,
          color: color.withValues(alpha: 0.10),
        ),
      );
    }

    return LineChart(
      LineChartData(
        minY: minY,
        maxY: maxY,
        lineTouchData: LineTouchData(
          handleBuiltInTouches: true,
          touchTooltipData: LineTouchTooltipData(
            fitInsideHorizontally: true,
            fitInsideVertically: true,
            getTooltipItems: (spots) {
              return spots.map((spot) {
                final index =
                    spot.x.toInt().clamp(0, points.length - 1).toInt();
                final point = points[index];
                final label = spot.barIndex == 0
                    ? '総資産'
                    : spot.barIndex == 1
                        ? '純資産'
                        : '総負債';
                final color = spot.barIndex == 0
                    ? const Color(0xFF0D9488)
                    : spot.barIndex == 1
                        ? const Color(0xFF2563EB)
                        : const Color(0xFFDC2626);
                final parsedDate = DateTime.tryParse(point.date);
                final date = parsedDate == null
                    ? point.date
                    : DateFormat('yyyy/MM/dd').format(parsedDate);
                final prefix = spot == spots.first ? '$date\n' : '';
                return LineTooltipItem(
                  '$prefix$label: ${_formatYen(spot.y)}',
                  TextStyle(
                    color: color,
                    fontWeight: FontWeight.w800,
                    height: 1.45,
                  ),
                );
              }).toList();
            },
          ),
        ),
        gridData: FlGridData(
          show: true,
          drawVerticalLine: false,
          getDrawingHorizontalLine: (value) =>
              const FlLine(color: Color(0xFFE2E8F0), strokeWidth: 1),
        ),
        borderData: FlBorderData(show: false),
        titlesData: FlTitlesData(
          leftTitles: AxisTitles(
            sideTitles: SideTitles(
              showTitles: true,
              reservedSize: 50,
              getTitlesWidget: (value, meta) {
                return SideTitleWidget(
                  meta: meta,
                  space: 8,
                  child: Text(
                    NumberFormat.compact(locale: 'ja_JP').format(value),
                    style: const TextStyle(
                      fontSize: 10,
                      color: Color(0xFF64748B),
                      height: 1.5,
                    ),
                  ),
                );
              },
            ),
          ),
          bottomTitles: AxisTitles(
            sideTitles: SideTitles(
              showTitles: true,
              reservedSize: 30,
              interval: interval,
              getTitlesWidget: (value, meta) {
                final index = value.toInt();
                if (index < 0 || index >= points.length) {
                  return const SizedBox.shrink();
                }
                final parsedDate = DateTime.tryParse(points[index].date);
                final date = parsedDate == null
                    ? points[index].date
                    : DateFormat('M/d').format(parsedDate);
                return SideTitleWidget(
                  meta: meta,
                  child: Text(
                    date,
                    style: const TextStyle(
                      fontSize: 10,
                      color: Color(0xFF64748B),
                      height: 1.5,
                    ),
                  ),
                );
              },
            ),
          ),
          topTitles: const AxisTitles(
            sideTitles: SideTitles(showTitles: false),
          ),
          rightTitles: const AxisTitles(
            sideTitles: SideTitles(showTitles: false),
          ),
        ),
        lineBarsData: [
          line(
            spots: [
              for (var i = 0; i < points.length; i++)
                FlSpot(i.toDouble(), points[i].assets),
            ],
            color: const Color(0xFF0D9488),
            area: true,
          ),
          line(
            spots: [
              for (var i = 0; i < points.length; i++)
                FlSpot(i.toDouble(), points[i].netWorth),
            ],
            color: const Color(0xFF2563EB),
          ),
          line(
            spots: [
              for (var i = 0; i < points.length; i++)
                FlSpot(i.toDouble(), points[i].liabilities),
            ],
            color: const Color(0xFFDC2626),
          ),
        ],
      ),
    );
  }

