  /// 最終更新日キー (yyyy-MM-dd) から経過日数を返す。未記録・本日更新・
  /// パース不能は 0 扱い。
  int _staleDaysForDateKey(String? dateKey, String todayStr) {
    if (dateKey == null || dateKey == todayStr) return 0;
    final last = DateTime.tryParse(dateKey);
    final today = DateTime.tryParse(todayStr);
    if (last == null || today == null) return 0;
    final days = today.difference(last).inDays;
    return days < 0 ? 0 : days;
  }

  Widget _buildAssetInputRow(String type) {
    final todayStr = _todayDateKey();
    final isUpdatedToday = _lastUpdatedDates[type] == todayStr;
    final isCompact = _isCompact;
    final watchlistEntry = _watchlistByType[type];

    // 最新残高を取得
    final lastDate = _lastUpdatedDates[type];
    double? lastAmount;
    if (lastDate != null) {
      lastAmount = _assetData[lastDate]?[type];
    }
    final isLiability = (lastAmount ?? 0) < 0;
    final canQuickUpdate = lastAmount != null && !isUpdatedToday;

    final accentColor =
        isLiability ? const Color(0xFFDC2626) : const Color(0xFF0D9488);
    final staleDays = _staleDaysForDateKey(lastDate, todayStr);
    final statusLabel = lastAmount == null
        ? '未記録'
        : lastDate == todayStr
            ? '本日更新'
            : '最終更新 $lastDate ($staleDays日前)';
    // 放置日数に応じて段階的に警告色へ (7日以上: 琥珀 / 30日以上: 赤)。
    // 1日遅れと1ヶ月放置が同じグレーに見えると更新漏れに気づけないため。
    final staleColor = staleDays >= 30
        ? const Color(0xFFDC2626)
        : staleDays >= 7
            ? const Color(0xFFB45309)
            : const Color(0xFF64748B);

    final titleBlock = Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Container(
          width: 38,
          height: 38,
          decoration: BoxDecoration(
            color: accentColor.withValues(alpha: 0.10),
            borderRadius: BorderRadius.circular(11),
          ),
          child: Icon(_getIconForAsset(type), size: 19, color: accentColor),
        ),
        const SizedBox(width: 10),
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                type,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                  fontSize: 14,
                  fontWeight: FontWeight.w800,
                  color: Color(0xFF0F172A),
                  height: 1.35,
                ),
              ),
              const SizedBox(height: 4),
              Wrap(
                spacing: 6,
                runSpacing: 6,
                crossAxisAlignment: WrapCrossAlignment.center,
                children: [
                  Text(
                    lastAmount == null ? '--' : _formatYen(lastAmount),
                    style: TextStyle(
                      fontSize: 13,
                      fontWeight: FontWeight.w900,
                      color: accentColor,
                      height: 1.35,
                    ),
                  ),
                  _buildAssetStatusPill(
                    icon: isUpdatedToday
                        ? Icons.check_circle
                        : staleDays >= 30
                            ? Icons.warning_amber_rounded
                            : Icons.history_toggle_off,
                    label: statusLabel,
                    color:
                        isUpdatedToday ? const Color(0xFF047857) : staleColor,
                  ),
                ],
              ),
            ],
          ),
        ),
      ],
    );

    final amountField = TextField(
      controller: _controllers[type],
      keyboardType: const TextInputType.numberWithOptions(
        decimal: true,
        signed: true,
      ),
      decoration: InputDecoration(
        labelText: '今日の残高',
        hintText: '負債はマイナス(-)をつける',
        prefixIcon: const Icon(Icons.edit_outlined, size: 18),
        suffixIcon: IconButton(
          tooltip: '符号切替 (資産⇔負債)',
          onPressed: () => _toggleMinusForType(type),
          // exposure_neg_1 (「-1」) は文字カウンタの残数表示に見えて
          // 誤解を招いたため ± アイコンにする。
          icon: const Icon(Icons.exposure),
        ),
        border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(12),
          borderSide: const BorderSide(color: Color(0xFFCBD5E1)),
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(12),
          borderSide: BorderSide(color: accentColor, width: 1.6),
        ),
        isDense: true,
        filled: true,
        fillColor:
            isUpdatedToday ? const Color(0xFFECFDF5) : const Color(0xFFF8FAFC),
      ),
    );

    final actions = Wrap(
      spacing: 6,
      runSpacing: 6,
      alignment: WrapAlignment.end,
      crossAxisAlignment: WrapCrossAlignment.center,
      children: [
        IconButton(
          tooltip:
              watchlistEntry == null ? 'Add to watchlist' : 'Edit watchlist',
          onPressed: () => _showWatchlistDialog(type),
          icon: Icon(
            watchlistEntry == null ? Icons.star_border : Icons.star,
            color: watchlistEntry == null
                ? const Color(0xFF64748B)
                : const Color(0xFF92400E),
          ),
        ),
        if (canQuickUpdate)
          OutlinedButton.icon(
            onPressed: () => _quickUpdateAssetData(type),
            icon: const Icon(Icons.history_toggle_off, size: 16),
            label: const Text('同額'),
          ),
        FilledButton.icon(
          onPressed: () => _saveSingleAssetData(type),
          icon: Icon(isUpdatedToday ? Icons.check : Icons.save_outlined),
          label: Text(isUpdatedToday ? '保存済' : '記録'),
          style: FilledButton.styleFrom(
            backgroundColor:
                isUpdatedToday ? const Color(0xFF94A3B8) : accentColor,
            foregroundColor: Colors.white,
            visualDensity: VisualDensity.compact,
          ),
        ),
        if (type != '現金')
          IconButton(
            tooltip: '削除',
            icon: const Icon(Icons.delete_outline, color: Color(0xFF94A3B8)),
            onPressed: () => _showRemoveAssetDialog(type),
          ),
      ],
    );

    return Container(
      key: _assetRowKeyForType(type),
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: isLiability ? const Color(0xFFFFFBFB) : Colors.white,
        borderRadius: BorderRadius.circular(14),
        border: Border.all(
          color: isUpdatedToday
              ? const Color(0xFF86EFAC)
              : accentColor.withValues(alpha: isLiability ? 0.35 : 0.16),
        ),
        boxShadow: const [
          BoxShadow(
            color: Color(0x0A0F172A),
            blurRadius: 10,
            offset: Offset(0, 4),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          if (watchlistEntry != null) ...[
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                _buildWatchlistMetaChip(
                  icon: Icons.star,
                  label: watchlistEntry.group.isEmpty
                      ? 'Watching'
                      : 'Watch: ${watchlistEntry.group}',
                  iconColor: const Color(0xFF92400E),
                ),
                if (watchlistEntry.memo.isNotEmpty)
                  _buildWatchlistMetaChip(
                    icon: Icons.sticky_note_2_outlined,
                    label: watchlistEntry.memo,
                  ),
              ],
            ),
            const SizedBox(height: 10),
          ],
          if (isCompact)
            Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                titleBlock,
                const SizedBox(height: 10),
                amountField,
                const SizedBox(height: 10),
                Align(alignment: Alignment.centerRight, child: actions),
              ],
            )
          else
            Row(
              children: [
                Expanded(flex: 3, child: titleBlock),
                const SizedBox(width: 12),
                Expanded(flex: 2, child: amountField),
                const SizedBox(width: 10),
                Flexible(flex: 2, child: actions),
              ],
            ),
          if (canQuickUpdate) ...[
            const SizedBox(height: 8),
            const Text(
              '残高が変わっていなければ「同額」で前回と同じ額をすぐ記録できます。',
              style: TextStyle(
                fontSize: 11,
                color: Color(0xFF64748B),
                fontWeight: FontWeight.w600,
                height: 1.5,
              ),
            ),
          ],
        ],
      ),
    );
  }

  Widget _buildWatchlistMetaChip({
    required IconData icon,
    required String label,
    Color? iconColor,
  }) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
      decoration: BoxDecoration(
        color: Theme.of(context).colorScheme.surfaceContainerLow,
        borderRadius: BorderRadius.circular(999),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(icon, size: 14, color: iconColor ?? const Color(0xFF334155)),
          const SizedBox(width: 6),
          Flexible(
            child: Text(
              label,
              style: const TextStyle(
                fontSize: 11,
                fontWeight: FontWeight.w600,
                height: 1.5,
              ),
              overflow: TextOverflow.ellipsis,
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildAssetWatchlistSection() {
    final entries = _visibleWatchlistEntries;

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: const Color(0xFF64748B),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: const Color(0xFFFDE68A)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Icon(Icons.star, color: Color(0xFF92400E)),
              const SizedBox(width: 8),
              const Expanded(
                child: Text(
                  'Watchlist',
                  style: TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.w700,
                    height: 1.4,
                  ),
                ),
              ),
              Text(
                '${entries.length} item(s)',
                style: TextStyle(
                  fontSize: 12,
                  color: Theme.of(context).colorScheme.onSurface,
                  fontWeight: FontWeight.w600,
                  height: 1.5,
                ),
              ),
            ],
          ),
          const SizedBox(height: 6),
          const Text(
            'Keep important assets or liabilities pinned with a short memo.',
            style: TextStyle(
              fontSize: 12,
              color: Color(0xFF9CA3AF),
              height: 1.5,
            ),
          ),
          const SizedBox(height: 12),
          if (entries.isEmpty)
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: Theme.of(context).colorScheme.surfaceContainerLow,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: const Color(0xFFFEF3C7)),
              ),
              child: const Text(
                'Use the star button on any asset row to add it here.',
                style: TextStyle(fontSize: 12, height: 1.5),
              ),
            )
          else
            ...entries.map((entry) {
              final lastDate = _lastUpdatedDates[entry.assetType];
              double? lastAmount;
              if (lastDate != null) {
                lastAmount = _assetData[lastDate]?[entry.assetType];
              }
              final isLiability = (lastAmount ?? 0) < 0;
              final amountColor = isLiability
                  ? const Color(0xFF64748B)
                  : const Color(0xFF047857);

              return Container(
                key: Key('asset_watchlist_item_${entry.assetType}'),
                margin: const EdgeInsets.only(bottom: 10),
                padding: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: Theme.of(context).colorScheme.surfaceContainerLow,
                  borderRadius: BorderRadius.circular(14),
                  border: Border.all(color: const Color(0xFFFEF3C7)),
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        Icon(
                          _getIconForAsset(entry.assetType),
                          color: amountColor,
                        ),
                        const SizedBox(width: 8),
                        Expanded(
                          child: Text(
                            entry.assetType,
                            style: const TextStyle(
                              fontWeight: FontWeight.w700,
                              height: 1.5,
                            ),
                          ),
                        ),
                        IconButton(
                          tooltip: 'Jump to row',
                          onPressed: () => _jumpToAssetType(entry.assetType),
                          icon: const Icon(Icons.vertical_align_bottom),
                        ),
                        IconButton(
                          tooltip: 'Edit watchlist',
                          onPressed: () =>
                              _showWatchlistDialog(entry.assetType),
                          icon: const Icon(Icons.edit_outlined),
                        ),
                      ],
                    ),
                    Wrap(
                      spacing: 8,
                      runSpacing: 8,
                      children: [
                        if (entry.group.isNotEmpty)
                          _buildWatchlistMetaChip(
                            icon: Icons.folder_open_outlined,
                            label: entry.group,
                            iconColor: const Color(0xFF92400E),
                          ),
                        if (lastAmount != null)
                          _buildWatchlistMetaChip(
                            icon: isLiability
                                ? Icons.trending_down
                                : Icons.trending_up,
                            label:
                                'Latest ${NumberFormat('#,###').format(lastAmount)}',
                            iconColor: amountColor,
                          ),
                        if (lastDate != null)
                          _buildWatchlistMetaChip(
                            icon: Icons.schedule,
                            label: 'Updated $lastDate',
                          ),
                      ],
                    ),
                    if (entry.memo.isNotEmpty) ...[
                      const SizedBox(height: 10),
                      Text(
                        entry.memo,
                        style: const TextStyle(fontSize: 12, height: 1.5),
                      ),
                    ],
                  ],
                ),
              );
            }),
        ],
      ),
    );
  }

  Widget _buildLegendCard() {
    if (_sortedDates.isEmpty) return const SizedBox.shrink();
    final latestDate = _sortedDates.last;
    final latestData =
        _effectiveAssetDataByDate[latestDate] ?? _assetData[latestDate] ?? {};
    double totalAssets = 0;
    double totalLiabilities = 0;

    latestData.forEach((key, value) {
      if (value >= 0) {
        totalAssets += value;
      } else {
        totalLiabilities += value;
      }
    });

    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: Theme.of(context).colorScheme.surfaceContainerLow,
        borderRadius: BorderRadius.circular(8),
      ),
      child: Column(
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              const Text('総資産:'),
              Text(
                '¥${NumberFormat('#,###').format(totalAssets)}',
                style: const TextStyle(
                  color: Color(0xFF0D9488),
                  fontWeight: FontWeight.bold,
                  height: 1.5,
                ),
              ),
            ],
          ),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              const Text('総負債:'),
              Text(
                '¥${NumberFormat('#,###').format(totalLiabilities)}',
                style: const TextStyle(
                  color: Color(0xFFB91C1C),
                  fontWeight: FontWeight.bold,
                  height: 1.5,
                ),
              ),
            ],
          ),
          const Divider(),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              const Text(
                '純資産:',
                style: TextStyle(fontWeight: FontWeight.bold, height: 1.5),
              ),
              Text(
                '¥${NumberFormat('#,###').format(totalAssets + totalLiabilities)}',
                style: const TextStyle(
                  fontWeight: FontWeight.bold,
                  fontSize: 16,
                  height: 1.4,
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  // ③ 固定費
  Widget _buildFlowCard() {
    final visibleFlows = _flowsForMonth(_selectedFlowHistoryMonth);
    final visibleMonthLabel = _flowMonthLabel(_selectedFlowHistoryMonth);
    final canMoveForward = !_isSameMonth(
      _selectedFlowHistoryMonth,
      DateTime.now(),
    );
    final isTransferSelected = _selectedFlowType == '振替';
    final transferOptions = _transferDestinationOptions(
      _selectedSource,
      include: _selectedTransferDestination,
    );
    int totalIncome = 0;
    int totalExpense = 0;
    int totalTransfer = 0;

    for (final item in visibleFlows) {
      final amount = (item['amount'] as num?)?.toInt() ?? 0;
      final actionType = item['action_type'] as String? ?? '';
      if (_isIncomeActionType(actionType)) totalIncome += amount;
      if (_isExpenseActionType(actionType)) totalExpense += amount;
      if (_isTransferActionType(actionType)) totalTransfer += amount;
    }

    return Card(
      elevation: 2,
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Row(
              children: [
                Icon(Icons.receipt_long, color: Color(0xFF6366F1)),
                SizedBox(width: 8),
                Text(
                  '④収支の記録',
                  style: TextStyle(
                    fontSize: 18,
                    fontWeight: FontWeight.bold,
                    height: 1.4,
                  ),
                ),
              ],
            ),
            Text(
              'お金の流れをすべてリスト化する。収入・支出に加えて口座間の振替も記録できます。表示中: $visibleMonthLabel（過去月に切替可）',
              style: const TextStyle(
                fontSize: 11,
                color: Color(0xFF9CA3AF),
                height: 1.5,
              ),
            ),
            const SizedBox(height: 12),
            Align(
              alignment: Alignment.centerLeft,
              child: OutlinedButton.icon(
                onPressed: _isImportingSmbcCsv ? null : _pickAndImportSmbcCsv,
                icon: _isImportingSmbcCsv
                    ? const SizedBox(
                        width: 16,
                        height: 16,
                        child: CircularProgressIndicator(strokeWidth: 2),
                      )
                    : const Icon(Icons.upload_file),
                label: Text(
                  _isImportingSmbcCsv ? '三井住友CSV取込中...' : '三井住友CSV取込',
                ),
              ),
            ),
            const SizedBox(height: 16),
            Row(
              children: [
                Expanded(
                  flex: 2,
                  child: DropdownButtonFormField<String>(
                    key: const Key('asset_flow_type_dropdown'),
                    initialValue: _selectedFlowType,
                    decoration: const InputDecoration(
                      border: OutlineInputBorder(),
                      isDense: true,
                      contentPadding: EdgeInsets.symmetric(
                        horizontal: 8,
                        vertical: 8,
                      ),
                    ),
                    items: _flowTypeOptions
                        .map(
                          (value) => DropdownMenuItem(
                            value: value,
                            child: Text(
                              value,
                              style: const TextStyle(fontSize: 13, height: 1.6),
                            ),
                          ),
                        )
                        .toList(),
                    onChanged: (value) {
                      if (value != null) {
                        _updateSelectedFlowType(value);
                      }
                    },
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  flex: 3,
                  child: InkWell(
                    onTap: () async {
                      final date = await showDatePicker(
                        context: context,
                        initialDate: _selectedFlowDate,
                        firstDate: DateTime(2020),
                        lastDate: DateTime.now(),
                      );
                      if (date != null) {
                        setState(() => _selectedFlowDate = date);
                      }
                    },
                    child: Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 12,
                        vertical: 10,
                      ),
                      decoration: BoxDecoration(
                        border: Border.all(
                          color: Theme.of(context).colorScheme.onSurfaceVariant,
                        ),
                        borderRadius: BorderRadius.circular(4),
                      ),
                      child: Row(
                        mainAxisAlignment: MainAxisAlignment.spaceBetween,
                        children: [
                          Text(DateFormat('MM/dd').format(_selectedFlowDate)),
                          Icon(
                            Icons.calendar_today,
                            size: 16,
                            color: Theme.of(
                              context,
                            ).colorScheme.onSurfaceVariant,
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 8),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
              decoration: BoxDecoration(
                color: const Color(0xFF64748B),
                borderRadius: BorderRadius.circular(10),
                border: Border.all(
                  color: const Color(0xFF475569).withValues(alpha: 0.12),
                ),
              ),
              child: Row(
                children: [
                  IconButton(
                    tooltip: '前月',
                    onPressed: () => _shiftFlowHistoryMonth(-1),
                    icon: const Icon(Icons.chevron_left),
