                    onChanged: (value) {
                      setState(() {
                        _isStacked = value;
                        _updateChartData();
                      });
                    },
                  ),
                  const Text('合計', style: TextStyle(fontSize: 10, height: 1.5)),
                ],
              ),
            const SizedBox(height: 24),
            SizedBox(
              height: 300,
              child: _lineChartBars.isEmpty && _barChartGroups.isEmpty
                  ? const Center(child: Text('戦況データなし。'))
                  : _showDailyChange
