  Widget _buildAssetTrendChart() {
    return LineChart(
      LineChartData(
        lineTouchData: LineTouchData(
          touchTooltipData: LineTouchTooltipData(
            getTooltipItems: _getTooltipItems,
          ),
          handleBuiltInTouches: true,
        ),
        gridData: const FlGridData(show: true),
        titlesData: _buildChartTitles(),
        borderData: FlBorderData(
          show: true,
          border: Border.all(
            color: Theme.of(context).colorScheme.outlineVariant,
          ),
        ),
        lineBarsData: _lineChartBars,
      ),
    );
  }

  Widget _buildDailyChangeChart() {
    return BarChart(
      BarChartData(
        alignment: BarChartAlignment.spaceAround,
        maxY: _maxDailyChange,
        minY: -_maxDailyChange,
        barTouchData: BarTouchData(
          touchTooltipData: BarTouchTooltipData(
            getTooltipItem: (group, groupIndex, rod, rodIndex) {
              final dateIndex = group.x.toInt();
              final dateStr = dateIndex < _sortedDates.length
                  ? _sortedDates[dateIndex]
                  : '';
              final date = dateStr.isNotEmpty
                  ? DateFormat('MM/dd').format(DateTime.parse(dateStr))
                  : '';
              final val = NumberFormat.simpleCurrency(
                locale: 'ja_JP',
                decimalDigits: 0,
              ).format(rod.toY);
              return BarTooltipItem(
                '$date\n$val',
                TextStyle(
                  color: rod.toY >= 0
                      ? Colors.lightGreenAccent
                      : const Color(0xFFB91C1C),
                  fontWeight: FontWeight.bold,
                  height: 1.5,
                ),
              );
            },
          ),
        ),
        titlesData: _buildChartTitles(),
        gridData: FlGridData(
          show: true,
          checkToShowHorizontalLine: (value) => value == 0,
          getDrawingHorizontalLine: (value) {
            if (value == 0) {
              return FlLine(
                color: Theme.of(context).colorScheme.onSurfaceVariant,
                strokeWidth: 1,
              );
            }
            return FlLine(
              color: Theme.of(context).colorScheme.outlineVariant,
              strokeWidth: 1,
            );
          },
        ),
        borderData: FlBorderData(show: false),
        barGroups: _barChartGroups,
      ),
    );
  }

  FlTitlesData _buildChartTitles() {
    return FlTitlesData(
      leftTitles: AxisTitles(
        sideTitles: SideTitles(
          showTitles: true,
          reservedSize: 50,
          getTitlesWidget: _leftTitleWidgets,
        ),
      ),
      bottomTitles: AxisTitles(
        sideTitles: SideTitles(
          showTitles: true,
          reservedSize: 30,
          getTitlesWidget: _bottomTitleWidgets,
          interval: max(1, (_sortedDates.length / 5).floor().toDouble()),
        ),
      ),
      topTitles: const AxisTitles(sideTitles: SideTitles(showTitles: false)),
      rightTitles: const AxisTitles(sideTitles: SideTitles(showTitles: false)),
    );
  }

  Widget _bottomTitleWidgets(double value, TitleMeta meta) {
    const style = TextStyle(fontSize: 10, height: 1.5);
    String text = '';
    if (value.toInt() < _sortedDates.length) {
      text = DateFormat(
        'MM/dd',
      ).format(DateTime.parse(_sortedDates[value.toInt()]));
    }
    return SideTitleWidget(
      meta: meta,
      child: Text(text, style: style),
    );
  }

  Widget _leftTitleWidgets(double value, TitleMeta meta) {
    final format = NumberFormat.compact(locale: 'ja_JP');
    return SideTitleWidget(
      meta: meta,
      space: 8,
      child: Text(
        format.format(value),
        style: const TextStyle(fontSize: 10, height: 1.5),
      ),
    );
  }

  List<LineTooltipItem> _getTooltipItems(List<LineBarSpot> spots) {
    final dateIndex = spots.first.spotIndex;
    if (dateIndex >= _sortedDates.length) return [];
    final date = _sortedDates[dateIndex];
    final assetsOnDate =
        _effectiveAssetDataByDate[date] ?? _assetData[date] ?? {};
    double total = 0;
    assetsOnDate.forEach((_, value) => total += value);
    final formattedDate = DateFormat('yyyy/MM/dd').format(DateTime.parse(date));
    final formattedTotal = NumberFormat.simpleCurrency(
      locale: 'ja_JP',
    ).format(total);
    final tooltips = <LineTooltipItem>[
      LineTooltipItem(
        '$formattedDate\n',
        const TextStyle(
          color: Colors.white,
          fontWeight: FontWeight.bold,
          height: 1.5,
        ),
      ),
      if (_isStacked)
        LineTooltipItem(
          '総資産: $formattedTotal\n',
          const TextStyle(
            color: Colors.white,
            fontWeight: FontWeight.bold,
            fontSize: 14,
            height: 1.5,
          ),
        ),
    ];
    final sortedAssets = assetsOnDate.entries.toList()
      ..sort((a, b) => b.value.compareTo(a.value));
    for (var entry in sortedAssets) {
      final color = _colors[_assetTypes.indexOf(entry.key) % _colors.length];
      final formattedValue = NumberFormat.simpleCurrency(
        locale: 'ja_JP',
      ).format(entry.value);
      tooltips.add(
        LineTooltipItem(
          '${entry.key}: $formattedValue',
          TextStyle(color: color, fontWeight: FontWeight.bold, height: 1.5),
        ),
      );
    }
    return tooltips;
  }

  IconData _getIconForAsset(String type) {
    if (type.contains('現金')) return Icons.wallet;
    if (type.contains('銀行')) return Icons.account_balance;
    if (type.contains('証券')) return Icons.trending_up;
    if (type.contains('ローン') || type.contains('カード')) return Icons.credit_card;
    return Icons.monetization_on;
  }
}

/// 支払確認手順ダイアログ。決定論ベース手順を即時表示し、開いた直後に AI(ネット検索)
/// で金融機関別の詳しい手順を取得する。取得失敗時はベース手順だけで完結する。
class _PaymentCheckGuideDialog extends StatefulWidget {
  const _PaymentCheckGuideDialog({
    required this.debtName,
    required this.baseGuide,
    required this.fetchAiGuide,
  });

  final String debtName;
  final String baseGuide;

  /// AI 詳細手順を取得する。失敗/無効時は null を返す。
  final Future<String?> Function() fetchAiGuide;

  @override
  State<_PaymentCheckGuideDialog> createState() =>
      _PaymentCheckGuideDialogState();
}

class _PaymentCheckGuideDialogState extends State<_PaymentCheckGuideDialog> {
  bool _loading = true;
  bool _failed = false;
  String? _aiGuide;

  @override
  void initState() {
    super.initState();
    unawaited(_load());
  }

  Future<void> _load() async {
    String? text;
    var failed = false;
    try {
      text = await widget.fetchAiGuide();
      failed = text == null || text.trim().isEmpty;
    } catch (_) {
      failed = true;
    }
    if (!mounted) {
      return;
    }
    setState(() {
      _aiGuide = text;
      _failed = failed;
      _loading = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    return AlertDialog(
      title: Text('${widget.debtName} の支払確認手順'),
      content: SingleChildScrollView(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              '基本の確認手順',
              style: TextStyle(
                fontWeight: FontWeight.bold,
                color: scheme.onSurface,
              ),
            ),
            const SizedBox(height: 4),
            SelectableText(
              widget.baseGuide,
              style: const TextStyle(fontSize: 13, height: 1.6),
            ),
            const Divider(height: 24),
            Row(
              children: [
                Icon(Icons.travel_explore, size: 16, color: scheme.primary),
                const SizedBox(width: 6),
                Expanded(
                  child: Text(
                    'AIによる金融機関別の詳しい手順',
                    style: TextStyle(
                      fontWeight: FontWeight.bold,
                      color: scheme.onSurface,
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 6),
            if (_loading)
              const Row(
                children: [
                  SizedBox(
                    width: 16,
                    height: 16,
                    child: CircularProgressIndicator(strokeWidth: 2),
                  ),
                  SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      'ネット検索で手順を取得しています…',
                      style: TextStyle(fontSize: 13, height: 1.5),
                    ),
                  ),
                ],
              )
            else if (_failed || _aiGuide == null)
              Text(
                'AIによる詳しい手順を取得できませんでした。上記の基本手順をご利用ください。',
                style: TextStyle(
                  fontSize: 13,
                  height: 1.5,
                  color: scheme.onSurfaceVariant,
                ),
              )
            else
              SelectableText(
                _aiGuide!,
                style: const TextStyle(fontSize: 13, height: 1.6),
              ),
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.of(context).pop(),
          child: const Text('閉じる'),
        ),
      ],
    );
  }
}

/// 負債マスタ行の支払済みチェックボックスを、アクションアイテムからのジャンプ着地時に
/// 一時的に点滅させて「ここをチェックすればよい」と視線誘導するラッパー。
/// [active] が true の間だけ枠が明滅する。false のときは子をそのまま描画するが、
/// レイアウトのずれを避けるため常に幅 2px の枠 (非アクティブ時は透明) を確保する。
class _DebtPaidCheckboxHighlight extends StatefulWidget {
  const _DebtPaidCheckboxHighlight({required this.active, required this.child});

  final bool active;
  final Widget child;

  @override
  State<_DebtPaidCheckboxHighlight> createState() =>
      _DebtPaidCheckboxHighlightState();
}

class _DebtPaidCheckboxHighlightState extends State<_DebtPaidCheckboxHighlight>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 550),
  );

  @override
  void initState() {
    super.initState();
    if (widget.active) {
      _controller.repeat(reverse: true);
    }
  }

  @override
  void didUpdateWidget(_DebtPaidCheckboxHighlight oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.active && !oldWidget.active) {
      _controller.repeat(reverse: true);
    } else if (!widget.active && oldWidget.active) {
      _controller.stop();
      _controller.value = 0;
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _controller,
      builder: (context, child) {
        final t =
            widget.active ? Curves.easeInOut.transform(_controller.value) : 0.0;
        // 自分株式会社ブランドのオレンジ (DESIGN.md) で明滅する。
        const accent = Color(0xFFF97316);
        return Container(
          decoration: BoxDecoration(
            color: accent.withValues(alpha: 0.12 * t),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(
              color: accent.withValues(alpha: 0.75 * t),
              width: 2,
            ),
          ),
          child: child,
        );
      },
      child: widget.child,
    );
  }
}
